namespace HeartOfTheRain.App.Localization { internal static class StoryLocaleCatalog {
internal static readonly string[][][] Chapters = new string[][][] {
new string[][] { // es
new string[] {"El pozo de la aldea","En la aldea de Zarech, donde crecían margaritas de ciervo blancas sobre un río plateado, Ivan había aprendido a reparar un tejado antes de aprender a llevar una espada. Años después, regresó como general de la guardia de la Antigua Moscú.","Los aldeanos recibieron al comandante, pero su vieja amiga Daria le preguntó si aún recordaba sus nombres. Ivan respondió ayudando a reparar el pozo de la aldea. Esa tarde llegó un mensajero: el Corazón sagrado de la ciudad había empezado a latir de forma irregular. Ivan dejó atrás su estandarte ceremonial y tomó su capa de viaje.\n\nIvan: «Una ciudad son las personas que han de vivir con nuestras decisiones»."},
new string[] {"La cámara bajo la plaza","En la plaza central, Ivan entró en una cámara construida alrededor de un piedra luminosa: el corazón del antiguo Moscú. Su luz viajaba a través de canales enterrados hasta los pozos, jardines y pabellones protectores.","El guardián de Orel le mostró un crack en la línea del cabello. Alguien había estado alimentando a los susurros del corazón de desconfianza, convirtiendo el temor que tiene la ciudad contra sus defensas. Ivan ordenó la cámara sellada mientras los guardias de ciudad buscaban en el canal. Por encima de ellos, las linternas del festival brillaban aunque ningún viento se movía por la calle.\n\nOrel: «Nos guarda sólo mientras que su luz puede llegar a nosotros»"},
new string[] {"Una puerta de humo","Los susurros robados abrieron un estrecho paso a través de la pared. Una figura de piedra negra pisó a través, llevando una linterna del hierro llena con humo rojo.","Era Malrec, enviado de Varkul. Ivan golpeó la linterna, pero su humo se dividió en tres sombras y resbaló alrededor de él. Orel tiró del general a medida que se rompió un anillo exterior. Malrec levantó el corazón sin tocarlo. Por un terrible instante, cada linterna de la antigua Moscú lanzó una sombra hacia el cielo.\n\nMalrec: «Tu miedo nos ha abierto la puerta»"},
new string[] {"La noche de las brasas","Cuando el Corazón desapareció, los canales enterrados se revirtieron. Los embers reventaron de fuentes vacías; la oscuridad se reunió entre casas, y las llamas escaló los techos madereros.","Ivan no podía perseguir a Malrec mientras la gente estaba atrapada bajo un pasarela colapsado. Ordenó a los guardias de la ciudad que cortaran un tiroteo y llevaron al niño hasta el cuadrado. Desde la cresta occidental se produjo el sonido de tres campanas, aunque ninguna torre estaba allí. Orel reconoció la señal de Horno Hueco. El corazón estaba siendo llevado más allá de los límites del pueblo vivo.\n\nIvan: «Abre las carriles. Nadie queda atrás»"},
new string[] {"Tres que no se quedarían","Yaroslav, el capitán más antiguo de Ivan... organizó un reloj restante. Boris, un mason de pueblo y herrero reforzó los refugios.","Daria mapeó el movimiento del fuego y encontró un rastro donde la oscuridad fluía al oeste. Los tres se ofrecieron a unirse con Ivan. Se negó al principio: un general no debería vaciar las defensas de su ciudad para una búsqueda privada. Yaroslav colocó el mando en manos del capitán Vera, que ya había asegurado los refugios. Juntos, acordaron una misión de rescate con cuatro viajeros y un pueblo que aún podía protegerse.\n\nDaria: «Llévanos porque podemos ayudar, no por ser tus amigos»"},
new string[] {"La última luz del guardián","Orel sobrevivió a la cámara destrozada, pero su salida había dilatado las mágicas piedras protectoras que llevaba. Le dio a Ivan su chispa restante dentro de una brújula cristal.","La brújula apuntaba al Corazón cada vez que su portador recordaba a alguien de quien deseaban proteger. No podía distinguir un camino de una pared, y no ofrecía ninguna promesa a la victoria. Orel advirtió que Varkul quería más de una ciudad quemada: él quiso a sus sobrevivientes creer, cada rescate requería un nuevo víctima. Ivan aceptó la brújulas y rechazó ese trato.\n\nIvan: «Entonces debemos traer más que una piedra»"},
new string[] {"La puerta que aún resistía","En la puerta occidental, los guardias de ciudad le rogaron a Ivan que tomara una fuerza más grande. Sin embargo, más allá de las paredes un ejército amplio llamaría la atención del Horno y dejaría a los refugios expuestos.","Ivan eligió el camino estrecho. Antes de partir, dio órdenes Vera para proteger a las familias juntos. Mantener los pozos cubiertos y registrar cada persona desaparecida Los cuatro viajeros pisaron bajo el arco que sobrevivió. Detrás de ellos, los ciudadanos comunes levantaron una barrera contra las chispas. Ivan miró atrás una vez, entendiendo que la resistencia de esta ciudad ya había comenzado.\n\nVera: «Trae el amanecer. Vamos a tener un lugar para él»"},
new string[] {"El camino de ceniza","Ash borró las marcas de carretera fuera del antiguo Moscú. Daria recuperó su dirección de los cortes del drenaje bajo el polvo; Boris puso piedras planas a través al suelo caliente.","Al atardecer descubrieron a los refugiados enredados en una capilla descubierta. La brújula se ha ido al oeste, lejos de las familias encadenadas pero Ivan paró. Yaroslav distribuyó sus alimentos de repuesto, mientras que los otros despejaron un camino a las viviendas. El retraso les costó luz del día. También demostró que no se permitiría a la misión del general convertir al pueblo en obstáculos.\n\nYaroslav: «Un corazón rescatado significa poco a una ciudad vacía»"},
new string[] {"Una cinta intacta","En el borde del campo de ceniza, una cinta índigo estrecha colgó desde un puesto ennegrecido. A diferencia de todo lo que está a su alrededor, la tela se mantuvo fresca.","Daria encontró marcas de juego en piedras cercanas: alguien había estado guiando a los refugiados por pasajes seguros. Ivan siguió los signos a un resorte sellado bajo una escoria. Cuando Boris lo cambió, agua limpia se levantó a través de la ceniza. Un mensaje arañado en la piedra no llamada autor, sólo una advertencia: el puente occidental escuchaba un temor hablado. Ivan tiró la cinta al lado de su brújulas.\n\nDaria: «Alguien caminó por este camino ante nosotros, y se preocupaba de quién vino después»"},
new string[] {"El puente de las tres campanas","El puente occidental estaba sobre un barranco lleno de oscuridad no natural. Tres campanas vacías colgaron sobre su centro.","Cuando Boris admitió que temía la caída, el primer campanario sonó y un banquete desapareció. Ivan pidió a cada compañero que declarara un peligro práctico y una respuesta práctica. Yaroslav aseguró una cuerda, Daria identificó los soportes de piedra y Boris probó las tablas restantes. Su honestidad retuvo el puente; sólo un pánico había alimentado su hechizo. En el lado lejano, la linterna de una mujer apareció entre los arcos arruinados.\n\nIvan: «Nombrar el peligro. Entonces, nombre lo que podamos hacer»"},
new string[] {"La linterna tras el barranco","La mujer más allá del puente no esperó a ser rescatada. Estaba bajando una cuerda a dos extraños atrapados en un candelabro.","Ivan se unió a ella, y juntos atracaron los viajeros hasta la seguridad. Se presentó como Mila, aprendiz de los Guardianes de la Lluvia desaparecidos y preguntó si el general tenía intención para ayudar a las personas o simplemente derrotar un enemigo. Ivan respondió dando a los extraños las últimas coáguelas secas. Mila se dio cuenta de que había una cinta indigo en su cinturón. Era de ella, dejado para marcar un camino que las llamas no podían tragar.\n\nMila: «Guárdate el lazo. Todavía hay gente que necesita el camino»"},
new string[] {"Un manantial bajo la piedra","Mila llevó a los compañeros al aspersores cubiertos, donde no podía entrar el calor del Horno. Ella podía guiar agua a lo largo de los viejos canales mágicos protectores, pero no podría convocar lluvia ni restaurar el corazón robado.","Boris reparó el lavabo roto mientras Mila limpiaba su mano quemada. El general le agradeció demasiado formalmente, y se rió a la distancia que tenía detrás de su título. Fuera, Yaroslav estaba de guardia; dentro Daria comparó las marcas del camino a Mila con su propio mapa. Sus viajes separados comenzaron a convertirse en una sola ruta.\n\nMila: «Puedes fijar tu rango lo suficiente como para beber»"},
new string[] {"El mapa que necesitaba dos manos","El mapa de Daria terminó en el barranco. La memoria de Mila comenzó más allá, donde niebla en movimiento ocultó el camino a Horno Hueco.","Solo, ninguno de los guías podía llegar a la guarida del demonio. Juntos dibujaron un recorrido a través del Bosque de Cristal, el Barrio Sunken y la Ciudadela de los Clavadores. Mila insistió en unirse a esta expedición porque los Guardianes de la Lluvia desaparecidos habían dejado registros por ese camino. Ivan aceptó su experiencia sin prometerle obediencia. Al amanecer, cinco viajeros dejaron el aspersores con un propósito común más que una orden.\n\nDaria: «Tu memoria es un camino. Mi mapa puede darle bordes»"},
new string[] {"El huerto sin sombras","Entraron en un huerto de árboles salados, cuyas raíces habían sido endurecidas por la magia Horno. No había fruto, y cada tronco arrojaba la misma sombra independientemente de su luz.","Mila descubrió que las sombras estaban alejando agua bajo tierra. Ivan quería cortar un camino recto, pero Boris advirtió que las raíces mantenían la pendiente juntos. Ellos aflojaron el hechizo un árbol a la vez. Cuando el agua fluía, las hojas vivas aparecieron bajo la corteza de plata. Ivan comenzó a ver la restauración como una especie de victoria que nunca le habían enseñado.\n\nBoris: «Una carretera que colapsa detrás de nosotros no es un camino a casa»"},
new string[] {"La promesa del general","Una patrulla de soot rodeó el huerto: guardias humanoides silenciosos tallados a partir del crack block stone. Yaroslav formó una línea de escudo, mientras que Ivan luchó un camino a tierra más alta.","Mila reorientó un resorte bajo los guardias, enfriando sus articulaciones hasta que se encerró en su lugar. Después, Ivan prometió mantener el peligro lejos de ella. Mila rechazó una promesa que no podía cumplir. Ella pidió la verdad sobre cada riesgo y voz en todas las decisiones. Ivan está de acuerdo, incomoda con lo que la simple honestidad le exigía.\n\nMila: «No prometas que nunca tendré miedo. Prométeme que escucharás»"},
new string[] {"Cartas en una torre en ruinas","En una torre de señal arruinada, Mila encontró un Guardián de la Lluvia sellado en vidrio. Describió el robo de Varkul a piedras protectoras mágicas menores y su intento por construir una corona desde la luz prestada.","Se había eliminado la página final. Ivan buscó en el piso superior y descubrió que la señal de esta torre aún podía llegar a su ciudad. Él dictó un mensaje para Vera: el Corazón sobrevivió, y la misión había encontrado una guía. Mila ha añadido en silencio las instrucciones al resorte restaurado. Hope, están de acuerdo. Debería viajar con algo que la gente pueda usar\n\nIvan: «Diles dónde está el agua. Entonces diles que vamos a volver»"},
new string[] {"Una mesa para cinco","La lluvia no cayó, pero una niebla fría permitió a los compañeros descansar bajo la torre. Boris cocinó una cena delgada en un pote reparado.","Yaroslav le dijo a Mila cómo Ivan una vez trató de controlar un techo filtrante y perdió el argumento. Por primera vez desde el robo, Ivan se rió. Mila habló de las colinas que esperaba construir, con una ventana lo suficientemente amplia como para ver a su primera tormenta. Ivan describió bien el agua del pueblo. Sus deseos sonaban normales, y por esa razón más preciosos que cualquier tesoro encantado.\n\nMila: «Cuando esto termine, me gustaría un cuarto que no pertenece a ninguna profecía»"},
new string[] {"El precio de un atajo","Una nueva carretera apareció durante la noche, pavimentada con piedra blanca intocable. En su entrada, un mensajero sin rostro ofreció paso directo al corazón a cambio de la brújulas cristal.","Mila sospechó que había un acuerdo de Horno, pero las piedras del camino eran reales. Daria descubrió que cada paso desplazó más lejos la salida. Ivan rechazó el comercio y llevó a todos de vuelta al difícil camino. Antes de desaparecer, el mensajero reveló que Varkul sabía su nombre. Ella había esperado que su viaje pudiera permanecer oculto de él.\n\nIvan: «Una promesa que se mueve cuando está probado es sólo otra trampa»"},
new string[] {"La verdad incompleta de Mila","Mila admitió que su profesor había entrado en el Horno y nunca volvió. Ella había pasado meses tras fragmentos de los registros del Guardianes de la Lluvia, esperando aprender lo que pasó.","Su linterna era el último instrumento de trabajo del orden, y Varkul había intentado incautarlo antes. Ivan estaba herido de que ella había esperado para decirle, pero reconoció lo poco confianza un uniforme solo mereció. Preguntó qué más podía hacer la linterna. Mila respondió de verdad: Ella aún no lo sabía. Convinieron en que se hablaría de incertidumbre, no oculta.\n\nMila: «Puedo darte lo que sé. No puedo darte certeza»"},
new string[] {"La puerta al Bosque de Cristal","En la entrada a Bosque de Cristal, los troncos translúcidos formaron un muro alrededor de una puerta antigua. Su cerradura respondió a la brújulas y al encierro juntos.","Cuando Ivan y Mila los criaron, se abrió una puerta a un bosque que reflejaba el cielo ni había visto. Daria marcó el umbral con tiza común para que ningún hechizo pudiera borrar la vuelta. Yaroslav apretó sus correas de escudo; Boris llevaba cuñas adicionales para tierra inestable. Los compañeros entraron como un equipo. Detrás de ellos, las nuevas hojas en el huerto se reventaron por primera vez.\n\nYaroslav: «Marque el regreso antes de dar un próximo paso»"},
new string[] {"Árboles de luz prestada","Los troncos de Bosque de Cristal almacenaron luz del día robada. Cada rama mostró un recuerdo diferente de la antigua Moscú, algunos verdaderos y otros inventados.","Ivan vio la aldea sin tocar por el fuego y casi se alejó del rastro. Mila probó su visión con el linterna; no reflejaba agua ni derramaba un aliento humano al vidrio. Rompían la imagen falsa sin dañar su raíz viva. Daria comenzó a marcar árboles confiables con cordón. El bosque se cruzaría a través de la observación, no mediante confianza en el lugar más brillante.\n\nMila: «Una respuesta hermosa puede ser aún el camino equivocado»"},
new string[] {"La segunda oportunidad del capitán","Yaroslav encontró un reflejo de soldados que no había podido salvar años antes. El cristal le ofreció una batalla que podía ganar esta vez si abandonaba a los otros.","Bajó su escudo y confesaba la vieja derrota a Ivan. El general no ofreció una absolución fácil. Recordó a su amigo de la gente que estaba esperando en el camino actual. Juntos se alejaron del reflejo. Yaroslav dejó una tira de tela azul en el tronco, un pequeño reconocimiento que recordar la pérdida no necesita convertirse a ella.\n\nYaroslav: «Los recuerdo. No abandonaré a los vivos para seguirlos»"},
new string[] {"La medida del albañil","Una escalera resplandeciente cruzó un abismo, pero Boris no vio articulaciones de carga. La piedra mágica exigió que los viajeros creen en su fuerza.","Boris en su lugar construyó un simple brace de vigas caídas y mostró a los otros donde cada pie debería aterrizar. La escalera se rompió exactamente donde había predicho, dejando intacta su sección. Mila ayudó a enfriar las superficies cortadas mientras Daria midió el intervalo restante. Ivan dio las gracias a Boris por no estar de acuerdo con él antes del cruce. La autoridad de un general, que estaba aprendiendo... debe dejar espacio para una mejor respuesta.\n\nBoris: «La confianza es bienvenida. Una articulación sonora sigue siendo necesaria»"},
new string[] {"Un mapa de lo que queda","Daria descubrió que Bosque de Cristal había cambiado por los deseos en lugar de pasos. Cada vez que alguien imaginaba llegar al Horno, el destino se movió.","Ella mapeó lo que podía ser tocado: un pozo de piedra, el arco caído y una piscina olía a lluvia. La ruta resultante parecía torcida, pero se mantuvo estable. Mila añadió marcas del viaje de su profesor, incluyendo una espiral al lado. Ivan reconoció esa espiral de la cámara del corazón. Por primera vez, la desaparición de los Guardianes de la Lluvia y su luz robada parecían pertenecer al mismo diseño.\n\nDaria: «Vamos a mapear lo que queda, no qué promete el bosque»"},
new string[] {"El estanque de las palabras calladas","La piscina espiral tenía voces en lugar de reflexiones. Ivan escuchó la esperanza de Milo para un hogar, y ella oyó su temor que volvería como héroe a una ciudad con tumbas.","Se fueron, pero el agua se levantó a través de su camino. Mila sugirió hablar directamente para que el grupo ya no los poseyera. Ivan admitió que estaba empezando a cuidarla más allá de la misión. Ella dijo que el sentimiento era mutuo, entonces le pidió a él para permitir su crecimiento sin hacer un voto hecho bajo asedio.\n\nMila: «Vamos a elegir el uno al otro también de día»"},
new string[] {"El recolector de fragmentos","Un teniente de Horno enmascarado llamado Serev vigiló el centro del bosque. Él cosechó chorros de luz del día y ofreció venderlos a la gente que había sido robada.","Cuando Ivan se negó, Serev selló el rastro con vidrio quemado. Daria identificó su línea de suministro; Boris rompió sus soportes mientras Yaroslav protegía a los otros. Mila enfrió el muro, e Ivan rompió las máscaras del teniente. Serev escapó a través de un fumo, dejando su tienda del día detrás. Los compañeros lo liberaron a los árboles en lugar de tomarla como un botín.\n\nIvan: «La luz tomada de un hogar no es tuya para vender»"},
new string[] {"El claro de las estrellas verdaderas","El día libre abrió un claro donde se podía ver el verdadero cielo nocturno. Los compañeros descansaron sin un vigilante tratando de negociar con ellos.","Mila le enseñó a Ivan cómo su linterna midió humedad en el aire. Le mostró el parche de tela planas bajo su armadura, cosida por la madre antes del primer mando. Hablaron de la gente que había hecho posible su trabajo. Cuando sus manos se reunieron sobre el mango de la linterna, no te retiraste. El momento era lo suficientemente pequeño como para pertenecer solo a ellos.\n\nIvan: «Me gustaría conocerte cuando nadie necesita salvarte»"},
new string[] {"La carta sin sello","Cerca del claro, Mila encontró una carta de su profesor Lada. Explicó que el Corazón sólo podía ser devuelto a través de una secuencia inquebrantable del canal mágico protector.","Un violento escape podría recuperar la piedra, pero destruir el camino que llevaba su luz a casa. Lada había entrado al Horno para descubrir una ruta más segura. La carta terminó con una advertencia sobre un dispositivo llamado el bloqueo de Ash. Su propósito no estaba, pero su esquema se parecía a la espiral que Ivan había visto bajo esta ciudad. Los compañeros copiaron cada línea antes de seguir adelante.\n\nMila: «Ella estaba buscando una forma de traer a todo el mundo»"},
new string[] {"Un beso ante el umbral","En la puerta de Bosque de Cristal, el amanecer apareció como una banda delgada a distancia. Ivan le ofreció a Mila el derecho de volver al refugio con los registros recuperados.","Ella eligió continuar, entonces le hizo la misma pregunta. Sonrió a que le ofrecieran una salida de su propia leyenda. Antes de reunirse con los otros, compartieron un primer beso tranquilo. Ni lo llamó destino. Prometieron seguir pidiendo, escuchando y hacer espacio para un futuro más grande que este camino. La puerta se abrió hacia las afueras ahogadas.\n\nMila: «Estoy aquí porque elijo estar»"},
new string[] {"El bosque devuelve lo perdido","A medida que los cinco viajeros se fueron, la corteza de vidrio cayó del árbol más cercano. Las ramas verdes emergieron sin tragar los viejos caminos.","Daria envió una segunda señal hacia la antigua Moscú, marcando el bosque como un posible refugio. Yaroslav grabó la máscara del teniente y su dirección de escape. Boris mantuvo un chorro inofensivo para el marco roto de la brújulas. Ivan miró de nuevo a la limpieza restaurada y entendió el patrón del viaje: cada lugar reparado podría convertirse en parte al hogar. Por debajo de la cresta, las torres arruinadas se levantaron del agua oscura.\n\nBoris: «No sólo encontramos el camino. Lo estamos haciendo utilizable»"},
new string[] {"Calles bajo aguas quietas","El Barrio Sunken había pertenecido a un pequeño asentamiento en la antigua carretera comercial. La magia de Horno lo había inundado sin lluvia, sosteniendo el agua aún por encima del techo.","Mila podría hacer un estrecho carril seco, pero no podía sostenerlo durante mucho tiempo. Daria ubicó un calabozo elevado en su mapa; Boris puso a prueba los pasos sumergidos con el polo. Ivan ordenó cruces cortos y repeticiones de descanso más que un ataque heroico. En la superficie, las luces pálidas de ventana se movieron desde casa a vivienda invitándoles al salir del camino seguro.\n\nIvan: «Cruzamos al ritmo que nuestra guía puede sostener»"},
new string[] {"La casa de la ventana seca","Una habitación superior se mantuvo seca. Un anciano alfarero llamado Anya había sellado su ventana con ward-clay y protegido a varios vecinos dentro.","Habían sobrevivido recogiendo condensación e compartiendo grano. Ivan ayudó a bajar los residentes hasta la causa mientras Boris estudiaba el sello de arcilla. Mila reconoció una receta Guardián de la Lluvia escondida en el trabajo común del alfarero. Anya les dio una bolsa de arcilla y pidió que su propósito fuera recordado. Ningún título había protegido la habitación; habilidad, paciencia y vecinos que confiaban unos a otros lo habían hecho.\n\nAnya: «Toma la arcilla. Deja el conocimiento con alguien que lo necesita»"},
new string[] {"El mercado de las tazas vacías","En el mercado ahogado, las tazas sobrevivieron los puestos abandonados. Cada taza se ofreció a quitar un recuerdo doloroso, dejando al viajero más ligero y menos seguro de por qué habían venido.","Yaroslav casi aceptó uno después de escuchar las voces del soldado perdido. Mila derramó agua corriente en ella. La taza se rompió, revelando el humo escondido dentro. Juntos, los compañeros rompieron el hechizo del mercado y recuperaron buques útiles para sus refugiados. Ivan mantuvo su dolor y temor. No entregaría a la gente dentro de ellos para que el camino fuera más fácil.\n\nYaroslav: «El dolor me puede cargar sin tener mis decisiones»"},
new string[] {"El registro bajo la campana","Una campana de la capilla está bajo el agua, descansando en una puerta sellada. Boris y Yaroslav lo levantaron con una palanca de madera mientras Mila retenía el agua a un lado.","En el interior, Daria encontró evidencia de que los sirvientes del Varkul habían redirigido las mágicas cadenas protectoras al Horno. Las inundaciones fueron un depósito de energía robada. Un segundo disco llamado Lada como un prisionero transferido a la ciudadela de Callers. La esperanza de Mila se levantó demasiado rápido, e Ivan preguntó suavemente qué edad tenía el récord. Llevaron la evidencia sin fingir que prometió sobrevivir.\n\nIvan: «Seguiremos el récord. No vamos a hacerlo decir más de lo que hace»"},
new string[] {"Un baile en la calzada","Con los residentes a salvo más allá de la inundación, Anya se humilló con una vieja melodía del pueblo. Daria aprovechó su ritmo en una taza vacía, y Boris añadió un latido desigual.","Mila tomó las manos de Ivan y le enseñó unos pasos en el amplio camino. Se movió como un comandante tratando de marchar a través del baile, lo que la hizo reír hasta casi olvidar el frío. El momento no borró el peligro. Les recordó lo que el peligro amenazaba: placeres ordinarios, compartidos libremente y sin un enemigo decidiendo su precio.\n\nMila: «Puedes dirigir un ejército. Yo voy a dirigir este baile»"},
new string[] {"El agua que ascendía","Malrec volvió a medianoche e invirtió la corriente del trimestre. El agua subió a las paredes de la torre y presionó contra el calabozo.","Ivan quería perseguirlo, pero Mila sólo podía mantener un carril de escape abierto. El general eligió proteger a los residentes de nuevo. Daria abrió una puerta de drenaje mientras Boris rompió los dientes que la sujetaban. Yaroslav bloqueó la linterna de humo Malrec lo suficiente para que todos se retiraran. El enviado escapó, furioso de que su cebo había fallado. El barrio drenado reveló una escalera de piedra que conduce por debajo del antiguo depósito.\n\nIvan: «Déjalo correr. Mantén el carril abierto»"},
new string[] {"El depósito de los nombres","Por debajo del trimestre, las paredes de los embalses llevaban nombres a personas cuyas piedras mágicas protectoras habían sido robadas. La escritura brilló cada vez que alguien se acordó de la persona a quien llamó.","Daria encontró pueblos omitidos de cada mapa que tenía. Mila encontró el nombre de Lada, que aún está débil. Ivan pidió una copia completa, negándose a tratar vidas desconocidas como menos dignas de rescate. La brújula se fortaleció cuando leyó los nombres en voz alta. La luz del corazón no fue atraída sólo hacia su propia casa, sino que reconoció el cuidado dirigido más allá de las calles familiares.\n\nDaria: «Un lugar que falta sigue siendo un sitio. Lo pondremos de nuevo en el mapa»"},
new string[] {"Lo que la linterna no puede reparar","Mila encontró el alojamiento roto de una linterna Guardián de la Lluvia. Intentó repararlo hasta que sus manos se sacudieron, pero su cristal interior había sido consumido.","Ivan se sentó a su lado sin ordenarle que descansara o le dijera la pérdida tenía un propósito. Eventualmente, ella puso los fragmentos. Admitió que salvar al corazón no podía salvarle a su profesor. Ivan admitió que temía perder a Mila ahora de haber empezado un futuro con ella. Dejaron que ambas verdades permanecieran, y compartieron el silencio sin tratar de convertirlo en valor.\n\nIvan: «No tienes que hacer este daño útil»"},
new string[] {"La escalera de la luz que regresa","Con la arcilla de Anya, Boris selló las articulaciones dañadas del embalse. Mila reorientó su poder restante a los canales vacíos hacia el antiguo Moscú.","Por un momento, la brújulas mostró una carretera completa de oro y luego se desplomó a través del Citadel. Daria marcó la brecha como su próximo objetivo. Por encima de ellos, los residentes rescatados comenzaron a abrir habitaciones secas otra vez. Los compañeros dejaron herramientas e instrucciones, convirtiendo el refugio en un arreglo de trabajo. Restaurar el corazón requeriría este mismo trabajo a una mayor escala.\n\nBoris: «La magia abre el canal. Alguien aún debe reparar sus paredes»"},
new string[] {"La ciudadela en el horizonte rojo","Desde la escalera superior, los viajeros vieron que el Citadelde Cinders se suspendió sobre un llano cicatrizado. Sus torres estaban en grandes cadenas conectadas al Horno Hueco más allá.","Beneat la ciudadela, los aldeanos llevaban piedras para reparar las paredes que sus captores seguían rompiendo. Ivan estudió a los guardias en lugar de dibujar su espada. Mila reconoció su marca de linterna en una ventana. La ruta se había convertido en una misión de rescate, así como un robo deshecho. Juntos planearon una entrada que dejaría salir a más de cinco personas.\n\nIvan: «No entramos hasta que sabemos cómo se van los prisioneros»"},
new string[] {"Una puerta para los obreros cautivos","Daria descubrió una puerta de suministro bajo la cadena occidental del Citadel. Los trabajadores captivos se desplazaron a través de ella en intervalos fijos, vigilados por guardias que siguieron sonidos más bien no caras.","Yaroslav creó un desvío con placas de escudo sueltas, mientras que Boris atornilló el haz del bloqueo. Ivan y Mila guiaron al primer grupo a través de un pasaje del drenaje. Los trabajadores eligieron representantes para organizar su propia fuga. El general les dio su mapa y preguntó qué peligros había perdido. Su conocimiento cambió el plan antes de que los guardias notaran la apertura.\n\nIvan: «Conoces esta prisión. Enséñanos dónde está mal nuestro plan»"},
new string[] {"El taller de los veranos robados","En el interior de la ciudadela, las jarras del calor se colgaron sobre un taller. Cada uno tuvo un verano robado de una piedra mágica protectora, dejando su hogar frío y estéril.","Boris encontró la marca de su pueblo en un conducto desmantelado y entendió lo ampliamente que había llegado el Horno. Mila abrió los jares cuidadosamente, devolviendo su luz a las cadenas intactas más cercanas. Ivan quería destruir el taller, pero los prisioneros podían usar sus herramientas. Rompían los sifones, guardaban las cercas e hicieron de la habitación el primer servicio.\n\nBoris: «Rompe lo que esclaviza. Mantenga lo que puede ayudar a alguien vivir»"},
new string[] {"La prisionera que esperaba la lluvia","Mila encontró a Lada viva en una célula marcada, debilitada pero todavía estudiando las paredes. Su reunión comenzó con lágrimas y se convirtió en un argumento cuando Lada le pidió a su aprendiz que saliera.","Mila se negó a dejar que el miedo decidiera por cualquiera de ellos. Lada reveló que el Corazón estaba intacto dentro del motor corona de Varkul. El bloqueo Ash lo conectó a la Horno: quitar el corazón activaría un aumento de retorno por cada canal mágico robado. Lada había encontrado una forma de desviar ese aumento, pero el ancla exterior necesario permanecía más allá del citadela.\n\nLada: «Quería una solución. Encontré la forma del peligro»"},
new string[] {"El comandante de las cenizas","El comandante de la Citadel, Ruzhen... bloqueó las escaleras con un cuchillo forjado a partir del rayo. Se burló de Ivan por desacelerar su misión para liberar a extraños.","Ivan respondió a través de la batalla: Yaroslav protegía los prisioneros, mientras que el general alejó al Ruzhen. Daria lanzó un contrapeso, separando al comandante de su fuente eléctrica. Boris rompió el conducto expuesto. El arma de Ruzhen se convirtió en hierro común, y Ivan lo derrotó sin colapsar las escaleras. Los prisioneros pasaron por el espacio que su captor había reclamado.\n\nIvan: «Tus prisioneros no son el precio de mi victoria»"},
new string[] {"El motor de la corona","Desde una galería de mantenimiento, los compañeros vieron la visión del motor Horno. El corazón dorado se cercó dentro de un marco crownforma, alimentando luz roja en el trono distante del Varkul.","Cuatro anclajes mantuvieron el sistema estable: la cadena de CitadEl, las raíces Bosque de Cristal. Ya habían restaurado dos. Boris podría liberar el ancla de CitadEl sin matar a los trabajadores más abajo, si alguien reemplazara su carga por un soporte para piedra. Ivan volvió a demorar la persecución. Un corazón recuperado que reposa por encima de los prisioneros aplastados sería una derrota.\n\nDaria: «El motor tiene cuatro anclajes. Podemos cambiar cómo falla»"},
new string[] {"La discusión en el parapeto","Ivan le pidió a Mila que acompañara al Lada y los prisioneros liberados para su seguridad. Oía que le importaba, pero también el regreso de un comando disfrazado como protección.","Mila le recordó su promesa de huerto. Admitió que el amor había hecho al peligro sentirse lo suficientemente personal para nublar su juicio. Admite que a veces escondió el agotamiento para parecer indispensable. Convinieron en límites compartidos: no hay síntomas ocultos, ni barajas privadas y ninguna decisión sobre la vida de otra persona sin su voz. Su amor se volvió más fuerte porque el desacuerdo había sido permitido existir.\n\nMila: «Pídeme que me quede a salvo. No decidas mi lugar por mí»"},
new string[] {"Una promesa sin profecía","Esa noche, Ivan talló un pequeño marco de madera desde una caja rota. Se lo dio a Mila como una promesa de su casa.","Mila ató su cinta de indigo a través, entonces rompió el marco en dos piezas que coinciden para cada uno podría llevar mitad. Acordaron que los restos no garantizaban nada; eran recordatorios para buscar una vida después de la misión. Ella lo besó bajo el parapeto incompleto. Por encima de ellos, no aparecieron estrellas pero ni esperaron a que el cielo aprobara su elección.\n\nIvan: «Una ventana para la primera tormenta de primavera. Si ambos lo elegimos todavía»"},
new string[] {"La cadena bajo la ciudad","Boris y los trabajadores liberados construyeron juntos el soporte. Daria verificó las cargas mientras Yaroslav guardaba a los guardias del lugar de trabajo.","Ivan llegó al cerrojo de la cadena principal y encontró a Malrec esperando con una nueva linterna. En lugar de luchar solo, llamó a sus compañeros y mantuvo el pasaje hasta que llegaron. Mila enfrió el linterna; Yaroslav lo rompió con su escudo. Malrec huyó hacia el Horno, despojado de su arma más fácil. Los trabajadores liberaron la cadena, y el Ciudadela se instaló a salvo en los cimientos que habían hecho.\n\nIvan: «Te necesito aquí. Esa es una orden que debería haber aprendido antes»"},
new string[] {"La salida de Lada","Lada se negó a gastar su rescate esperando en silencio. Ella organizó a los trabajadores liberados en equipos de reparación y dio Daria la fórmula para el portón exterior.","Ella regresaría con los evacuados hacia el Barrio Sunken, reforzando las mágicas cadenas de protección tras la expedición. Antes de partir, le dijo a Mila que el valor no se midió por cuánto dolor podía soportar inesperado. Mila prometió mantener esa lección. Su despedida tenía incertidumbre, pero también un plan práctico: señales y puntos de encuentro.\n\nLada: «Traed a toda vuestra casa, no sólo la parte que puede ser útil»"},
new string[] {"La puerta tras la ciudadela","La carretera Horno comenzó en un arco hecho de ceniza refrigerada. Cuando el ancla de CitadEl desconectó, un arco se agrietó y reveló una senda a través del monte con vidrio rojo.","La linterna de Mila se desplomó cuando abrió el primer sello. Se lo dijo a Ivan inmediatamente, cumpliendo su acuerdo. Dividían las tareas de la linterna entre lámparas comunes y el brújulo para conservar su fuerza. Yaroslav dejó un marcador para los equipos de Lada. Los cinco viajeros continuaron, llevando un camino más seguro por todos los que habían decidido repararlo detrás de ellos.\n\nMila: «La linterna es más débil. Te lo estoy diciendo antes de que falle»"},
new string[] {"La montaña que respiraba calor","Los pasajes de la montaña se expandieron con el aliento del Horno. El aire caliente empujó hacia fuera en largos intervalos; entre ellos, los túneles dibujaron todo al centro.","Daria midió el ritmo con hilos colgantes mientras Boris fijaba plataformas de descanso en las paredes. Ivan movió a los compañeros sólo durante el aliento exterior. En la primera cámara segura, Milo encontró gotas de agua clara bajo el vidrio rojo. La puerta de lluvia exterior aún estaba viva en algún lugar dentro del monte, escondida bajo capas que robaban calor.\n\nDaria: «Nos movemos al ritmo que medimos, no a quien esperamos»"},
new string[] {"La sala de las espadas inconclusas","Una forja abandonada tenía filas de espadas sin mangos. El Horno había hecho armas sin que nadie se fuera a llevarlas.","Boris reconoció que las cuchillas eran coleccionistas de luz, sacando energía a cada persona quien entró. Él cubría sus bordes de corte con ward-arcilla, mientras que Mila basaba el semáforo almacenado a través del drenaje. Ivan encontró una simple espada inacabada y la dejó donde estaba. Su propia arma, mantenida por las manos humanas fue suficiente. En la pared más lejana, el patrón enfriado de las forjas reveló su primera llave.\n\nBoris: «Un arma que toma de su alfiler es otra cadena»"},
new string[] {"Un trato con la voz de Ivan","Varkul habló a través de la forja usando su propia voz. Se ofreció a devolver el corazón si la general se rindió de su linterna.","Incluso prometió su seguridad, pero se negó a nombrar al pueblo cuyos canales de protección mágicos permanecerían esclavizados. Ivan pidió una respuesta completa; la voz de imitación sólo repitió el ofrecimiento. Mila levantó su linterna y reveló el conducto de habla. Juntos lo sellaron. El arma más peligrosa del demonio no era la llama. Fue un trato que se hizo sonar como una decisión de Ivan ya había elegido.\n\nIvan: «Si tu misericordia no puede nombrar su precio, No es piedad»"},
new string[] {"La primera Puerta de la Lluvia","La puerta está bajo un piso de vidrio, mecanismo circular diseñado para llamar a los asaltos dormados. Su obra de piedra había sido fusionada por el calor.","Boris lo enfrió gradualmente mientras Daria alineaba las marcas de la fórmula Lada. Mila utiliza sólo un poco de luz, permitiendo que el agua del mecanismo pueda llevar al resto. La puerta se abrió, pero su cámara inferior estaba vacía. Se había extraído un ancla central que se llevaba más profundo a la montaña. Reiniciar la puerta requeriría encontrar ese ancla antes de tocar el corazón.\n\nMila: «Hemos abierto una puerta. Aún no hemos resuelto lo que está detrás de ella»"},
new string[] {"El general deja su estandarte","Una cámara de guardia exigió un banner del comandante como precio para entrar. Ivan se dio cuenta que el Horno reconocía los símbolos de autoridad más fácilmente, como la gente bajo ellos.","Retiró su cierre de hombro decorativo y envolvió la armadura en el manto del trabajador. Daria condujo a los compañeros por el pasaje de mantenimiento que la cámara del guardia ignoró. Mila lo vio dejar el emblema atrás sin resentimiento. Seguía siendo un general debido a sus responsabilidades, no porque una puerta encantada reconociera su rango. Más allá, la segunda forja esperó.\n\nIvan: «El deber viene conmigo. El adorno puede quedarse»"},
new string[] {"Una sala sin eco","La segunda forja contenía una cámara que se tragó cada sonido. No es posible llamar a las instrucciones, los viajeros trabajaron de señales que habían acordado antes.","Yaroslav mantuvo al grupo junto a las grietas en su escudo; Daria marcó peligros de tiza. Mila tomó las manos de Ivan cuando se profundizó, y siguió su linterna sin intentar conducir cada paso. En la puerta más baja, Boris restauró un resonador crack. El sonido volvió en un solo apuro, y la primera palabra audible de Milo fue el nombre del Ivan.\n\nMila: «Ivan. Aquí estás»"},
new string[] {"El ancla perdida","El ancla de lluvia se paró en la tercera forja, convertido a un pedestal para que Serev robara luz del día. El teniente volvió con una máscara de vidrio milagroso e intentó atrapar a los compañeros en visiones del futuro deseado.","Ivan vio la colina de casa; Milo vió a Lada salvo y sonriendo. Reconocían que precisamente la trampa utilizaba lo de su amor. Daria cubría los espejos mientras Yaroslav colgaba la capa de Serev. Boris liberó el ancla, y Mila drenaba las falsas visiones. Serev huyó sin su máscara, incapaz de llevar la verdad que había expuesto.\n\nMila: «La búsqueda de un futuro no hace que esta visión sea real»"},
new string[] {"El secreto del Cierre de Ceniza","El último esquema de Lada llegó por la línea de señales reparada. Confirmaba un mecanismo terrible: cuando el Corazón saliera del motor de la corona, el Cierre de Ceniza devolvería el calor acumulado hacia la ciudad.","El ancla de lluvia podía desviar la mayor parte de la oleada hacia la puerta exterior. Había que mantener sujeto a mano un segundo pestillo dentro de la cámara del motor hasta que el Corazón cruzara el umbral. Quien lo sujetara podría escapar si la puerta permanecía estable; nadie tenía que morir. Ivan dejó clara esa diferencia y preparó una liberación mediante cuerdas, un soporte de repuesto y una salida alternativa.\n\nIvan: «El plan es que salgamos todos. No se designará a nadie como sacrificio»."},
new string[] {"El hogar que pensaban construir","Antes de llevar el ancla, los compañeros descansaron en un alcoba fresco. Mila le preguntó a Ivan qué haría cuando ya no necesitara tener una espada.","Respondió que quería aprender a construir lo suficientemente bien como para merecer la aprobación de Boris. Ella imaginó enseñar a la nave de linterna y plantar flores margaritas fuera su ventana. Presionaron las dos mitades de su madera. Su futuro es concreto ahora, hecho de tareas y errores que esperan compartir. Su ternura les dio razón para seguir un plan más seguro, no es motivo de abandono.\n\nIvan: «Enséñame la linterna. Aprenderé la ventana»"},
new string[] {"La puerta aprende la lluvia","Boris reinicia el ancla mientras Daria sincronizó un mecanismo. Mila guió un hilo de agua a través del canal restaurado.","Lejos de aquí, la brújulas mostró a los antiguos Moscú que contestaban con un pulso dorado débil. La puerta funcionó, aunque una fractura roja bajo su fundación permanecía más allá de sus herramientas. Ellos documentaron la debilidad y prepararon soportes de repuesto. Yaroslav envió los resultados a Lada y Vera. Luego, los compañeros abrieron la puerta interior de montaña. Más allá de ella se encontraba el Horno Hueco, donde un corazón golpeó al trono vacío del Varkul.\n\nDaria: «La ruta responde. Seguimos viendo la fractura»"},
new string[] {"La guarida del Rey Hueco","El Horno Hueco era una fortaleza construida dentro, sus torres colgando sobre un eje de luz roja. Los sirvientes de Varkul habían creado cada corredor para dirigir a los visitantes hacia el trono.","Daria buscó las rutas de los trabajadores. Encontró pies a mano y estantes de herramientas escondidos detrás del muro ceremonial. Ivan la siguió a través de los pasajes estrechos mientras Milo escuchaba el pulso del corazón. Entraron a la guarida sin anunciarse. Bajo la galería del trono, una cadena de células ocupadas esperó al calor.\n\nDaria: «Alguien tuvo que mantener este lugar. Su ruta será nuestra»"},
new string[] {"Quienes siguen tras los muros","Las células retuvieron a los cangrejos cuyo conocimiento mantuvo vivo al Horno. Entre ellos estaba un estonemason que había cortado la puerta de lluvia original.","Advirtió que su fundación había sido deliberadamente debilitada para colapsar después de la eliminación del Corazón. Boris le pidió que marcara el borde oculto de la fractura. Mila pasó una señal a Lada, que podía organizar reparaciones desde el lado exterior. Ivan abrió las celdas y dio a los prisioneros herramientas más que órdenes. Ellos eligieron si salir inmediatamente o ayudar a desmantelar la máquina que los había retenido.\n\nIvan: «Tu libertad no está condicionada a ayudarnos»"},
new string[] {"La resistencia del capitán","Una patrulla descubrió las celdas abiertas. Yaroslav tuvo un estrecho aterrizaje mientras los prisioneros cruzaban detrás de él.","Su escudo se rompió bajo las cuchillas calentadas de los guardias, y una piedra que cayó le hirió la pierna. Ivan volvió para ayudar a pesar de que la brújulas lo empujó hacia el corazón. Juntos se retiraron tras la barrera temporal de Boris. Yaroslav se negó a llamar al perjuicio un pago noble; era problema tratar. Mila se enfrió, Daria adaptó su ruta y el capitán continuó con un personal en lugar de fingir que nada había cambiado.\n\nYaroslav: «No alabes la herida. Ayúdame a caminar»"},
new string[] {"La puerta del albañil","Boris selló el pasaje de patrulla con un muro que la Horno no pudo derretir rápidamente. Detrás talló un estrecho bloque extraíble, dejando una ruta de regreso deliberada.","El general preguntó si se mantendría. Boris respondió con un límite, no una garantía: el tiempo suficiente para uno de los pasajes quizás dos si nadie golpeó la base. Daria escribió la condición al lado del mapa. Enviaron a los prisioneros restantes mientras se encontraba la barrera. Cada límite honesto hizo que su plan fuera menos glorioso y más probable de mantener a alguien vivo.\n\nBoris: «Se mantiene bajo estas condiciones. Recuerda las condiciones»"},
new string[] {"La brújula robada","Malrec emergió de un suelo del humo y tomó la brújulas. Su aguja dorada se inclinó hacia el trono, sacándolo de su camino.","Ivan casi lo persigue solo, pero Mila le detuvo en el estafado roto. Daria reconoció un puente de servicio a continuación y guió al grupo alrededor. Recuperaron la brújulas de Malrec. El enviado había aprendido que la brújulas no servía a un portador, quien sólo buscaban posesión. Furioso, rompió la jaula y huyó hacia su amo por otro arma.\n\nMila: «Podemos recuperarlo juntos. No convierta la urgencia en soledad»"},
new string[] {"La propia batalla de la doncella","Mila encontró una bóveda de linterna del Horno, donde cristales Guardián de la Lluvia rotos alimentaron un muro con fuego rojo. Ivan se ofreció a vigilar la entrada mientras ella eligió cómo liberarlos.","Con la ayuda de Daria, Mila cambió el alineamiento del cristal en lugar que derramara su propia fuerza a un muro. El fuego se ablandó en luz azul. Ella recuperó el viejo lente de su profesor y se lo puso a la linterna. La mejora no la hizo invencible, pero le dio más control. Ivan admiró más la habilidad detrás del milagro que el espectáculo mismo.\n\nMila: «¡Alto! Esta parte es mía para resolver»"},
new string[] {"La sala de los rostros prestados","Varkul llenó el próximo salón con copias de gente del pasado, Ivan. Cada uno exigía un rescate diferente, descuartizando su atención hasta que apenas podía moverse.","Mila se negó a identificar el verdadero camino adivinando que voz sonaba más sincera. Ella y Daria rastrearon los canales de protección mágicos del suelo, mientras que Boris probó cada puerta. Ivan siguió el trabajo que podían verificar. Las caras copiadas se desvanecieron cuando el motor oculto estaba desconectado. Una señal verdadera seguía siendo: el informe de Vera que la antigua Moscú todavía tenía, y los pozos reparados habían comenzado a brillar.\n\nIvan: «La ciudad sigue allí. Respondemos al verdadero mensaje»"},
new string[] {"La última linterna de Malrec","El enviado esperó a la puerta interior con una linterna tallada de su cadena citadela. Dibujó cada chispa en el corredor hacia la armadura de Ivan.","El general dejó a un lado su espada y usó el gancho de los trabajadores para engrasar la cadena. Yaroslav golpeó la bisagra de las linterna; Milo enfrió su núcleo. Malrec trató de escapar a través del humo, pero la cadena cercada selló su pasaje. Su forma de piedra negra se desmoronó en cenizas inofensivas cuando Boris rompió la linterna vacía. Dejaron el corredor intacto para su regreso en lugar de quemar la victoria a sus paredes.\n\nYaroslav: «The bise, Ivan. Deja en paz al centro brillante»"},
new string[] {"El umbral del Corazón","Más allá de la puerta interior, el corazón flotó dentro del motor corona. Su luz dorada brilló alrededor de cadenas rojas, e Ivan reconoció el ritmo desde la cámara.","Los cinco viajeros revisaron su plan una vez más: puerta de lluvia contestando, cuerda asegurada y paso alternativo marcado. Mila operaría el cierre de agua porque su lente restaurada podía controlarlo; Boris lo movería, Daria coordinaba las puertas y Yaroslav protegía a los que salían. Ivan se enfrentaría a Varkul. Mila le pidió que mirara a ella antes de mirar al trono, y él lo hizo.\n\nMila: «Recuerda el camino de salida, incluso cuando ves lo que viniste a buscar»"},
new string[] {"El señor que se llamaba Aurora","Varkul descendió del trono vacío, una figura humanoide de obsidiana envuelta en vestiduras rojas. Dijo que la luz robada le hizo el amanecer legítimo de esta ciudad.","Ivan preguntó por qué un amanecer necesitaba prisioneros, pozos rotos y oscuridad para sobrevivir. El demonio respondió levantando las cadenas del motor de la corona. Mila tenía el agua abierta; Daria llamó a los intervalos de pulso. Ivan avanzó con su hoja de acero común. La batalla comenzó alrededor de una máquina que podía ser entendida, interrumpida y desmantelada.\n\nIvan: «La luz que necesita nuestra oscuridad no tiene derecho a gobernarnos»"},
new string[] {"Una corona hecha de otras vidas","La corona de Varkul sacó fuerza a partir del nombre tallado en los canales mágicos robados. Cada golpe que Ivan golpeó volvió como calor a través del suelo.","Daria reconoció los símbolos del embalse y le dijo que dejara de atacar directamente la corona. Mila abrió un canal azul a los comprimidos de nombre liberados; Boris cortó el conducto más cercano. La corona perdió una de sus luces. Ivan cambió su enfoque, luchando para exponer las conexiones en lugar de sobrecargar al demonio. Varkul recoiled at the first thing he could not substitute: a cautive source become free.\n\nDaria: «Cortar la conexión. No le des otro golpe a la corona»"},
new string[] {"El plan de cuatro partes","La batalla se extendió a través de cuatro galerías. Yaroslav mantuvo la salida contra los guardias de hollín; Boris reforzó el cierre, Daria señaló a Lada en su puerta exterior. Milo controlaba las presiones del agua","Ivan no podía ver a ninguno de ellos claramente por medio del calor creciente, así que confió en las señales acordadas. Cuando una galería se rompió, Daria llamó a la pausa en lugar de ocultar el retraso. Ivan sacó a Varkul lo suficiente para que Boris la estabilizara. El plan funcionaba porque a todos se les permitía denunciar un fracaso mientras todavía había tiempo para responder.\n\nDaria: «Pausa la liberación. El apoyo oeste se está moviendo»"},
new string[] {"La oferta de una ciudad viva","Varkul mostró a Ivan una visión del antiguo Moscú restaurada, con Mila al lado de él bajo un cielo claro. Él lo ofreció a cambio de los nombres del embalse: extraños cuyas casas permanecerían oscuras para siempre.","Ivan sintió la crueldad de una elección en forma exactamente como su deseo. Se negó a hablar por la gente que se comerciaba. Mila cerró su visión con un flujo de luz. La oferta del demonio falló porque su amor había hecho espacio para un futuro, pero nunca les habían dado propiedad de nadie más.\n\nIvan: «No puedo comprar nuestra casa con otra persona»"},
new string[] {"La hoja de hierro común","Varkul rompió la espada de Ivan al guardia. Boris le tiró la hoja inacabada que se recuperaba de su forja, ahora está equipada con un agarre a madera.","No tenía luz robada. Ivan lo usó para abrir la placa de mantenimiento del motor corona mientras Yaroslav cubría su aproximación. Daria llamó a las cerraduras expuestas en secuencia. El demonio chocó de forma salvaje a medida que su fuerza se convirtió en un conjunto más vulnerable. El arma final de Ivan importaba porque podía hacer una tarea simple, no debido a que la profecía había nombrado su portador.\n\nBoris: «Es hierro sonoro. Haz que haga el trabajo»"},
new string[] {"El cierre se resiste","Las tres primeras cerraduras de corona se abrieron. El cuarto permaneció fusionado a un canal mágico de protección dañado bajo el trono del Varkul.","Mila advirtió que forzarlo enviaría un aumento a los cimientos fracturados de esta puerta. Boris y Daria propusieron enfriarlo en etapas, mientras que Lada fortaleció el lado exterior. Ivan mantuvo a Varkul lejos de la cerradura y contó las señales. Ganaron tiempo a costa del agotamiento, pero evitaron una liberación ciega. En el trono, una vena roja no vista comenzó a calentarse más rápido que sus diagramas predicho.\n\nMila: «No está lista. Dad tiempo a la puerta para responder»"},
new string[] {"Una voz de la Antigua Moscú","La señal de Vera llegó a la cámara por los canales mágicos casi restaurados. Informó de que los ciudadanos habían despejado el enchufe del corazón y había conectado las viviendas a sus canales.","La ciudad se estaba preparando para recibir lo que los compañeros esperaban volver. Ivan oyó voces familiares bajo la cresta: el alfarero Anya, los trabajadores liberados y las personas del camino. Varkul trató de ahogarlos en el trueno del motor, pero Mila amplificó su señal. Su trabajo se había convertido en un círculo de gente ayudándose unos a otros, sin que ningún héroe tuviera toda su fuerza.\n\nVera: «La cámara está lista. La ciudad está trabajando contigo»"},
new string[] {"La corona cae","La señal de Lada confirmó el primer refuerzo del portón. Daria lanzó la cerradura de corona final, y Boris cortó el conducto del trono.","La corona de Varkul entró en segmentos aburridos. El corazón se descolgó del marco, todavía retenido por el cerrojo interior de Ash. Ivan conoció al demonio en la escalera baja y lo alejó de las fuentes restantes. Por primera vez, Varkul lanzó una sombra común. Él era peligroso todavía, pero ya no es grande con la luz extraída de otros.\n\nIvan: «No queda nada en esa corona que te pertenece»"},
new string[] {"La derrota de Varkul","Varkul trató de reconectarse al Corazón a través del trono roto. Ivan lo obligó al puente de mantenimiento, mientras que Mila selló el último conducto vivo.","Yaroslav cortó la cadena del puente a las señales de Daria, dejando caer su sección vacía lejos y separando el retiro al demonio. Ivan golpeó el núcleo expuesto de noviembre en un pecho con la hoja del hierro. La llama robada salió. Varkul colapsó en fragmentos fríos, y el Horno se quedó callado. Ivan había derrotado al líder del demonio, pero el Corazón aún no ha cruzado la umbral.\n\nIvan: «La luz de la ciudad se va a casa»"},
new string[] {"El Corazón en manos humanas","El bloqueo interior de Ash se abrió cuando Mila equilibró su último canal agua. Ivan levantó el corazón de su cuna.","Su calor era suave, a diferencia del fuego de la Horno y su luz mostraba claramente cada cara agotada. Boris revisó el rejilla; Yaroslav comenzó a moverse hacia la salida marcada. Daria esperó la confirmación de liberación del portón exterior. Ivan le dijo a Mila que el Corazón era libre y llegó por su mano. La liberación prevista asistida debería haber seguido. En cambio, la vena roja bajo el trono muerto estalló a través del suelo.\n\nIvan: «Lo tenemos. Ahora nos sacamos a todos»"},
new string[] {"La última orden del Horno","La muerte de Varkul desencadenó un mecanismo encubierto más allá del bloqueo Ash. La puerta exterior de lluvia perdió su segundo soporte; la cuerda que se había quemado antes, Mela podía dejar ir el cerrojo.","Ella reportó el fracaso inmediatamente. Boris trató de reemplazar la cuerda mientras Daria buscara otro control. Ivan puso el corazón en un borde estable y volvió a Mila. El motor comenzó a tirar de calor hacia la ciudad, y una onda roja cruzó el distante galerío. Su enemigo se había ido. Su máquina aún exigía una respuesta.\n\nMila: «La cuerda se ha ido. El cierre está reteniendo el resorte»"},
new string[] {"La decisión ante el pestillo roto","Ivan y Boris intentaron enredar la cerradura con el spread brace. La vena de calor oculta suavizó el hierro antes que pudiera sentarse.","Daria encontró un paso estrecho al umbral, pero no hay segundo control. Mila entendió el momento: si un corazón cruzaba al umbral mientras que su cerradura permanecía, este aumento se desviaría a las montañas en lugar de ir más allá. Le pidió a los otros que siguieran buscando un permiso mientras Ivan realizaba el Corazón. Ivan se negó a dejarla sin probar primero el pasaje restante. Todavía estaban trabajando para cinco sobrevivientes.\n\nMila: «Sigue buscando. Cógelo sólo cuando dé la señal»"},
new string[] {"El camino que se cerró","Yaroslav cruzó el estrecho paso para asegurar su extremo largo. Una escoria que caía selló el lado de regreso y aplastaba la mano bajo los pies del Ivan.","Mila reorientó el canal de agua, atrapando a las losas lo suficiente para que Boris le dejara claro. El esfuerzo rompió su lente de linterna. Daria trató de señalar a Lada, pero la puerta colapsante respondió sólo en pulsos rotos. Ivan ahora podía alcanzar el Corazón y su umbral; no pudo llegar a la cerradura desde fuera. Mila le pidió que escuchara los hechos antes de decidir qué esperanza aún había permitido.\n\nMila: «Escucha lo que ha cambiado. Entonces elige conmigo»"},
new string[] {"El último intento de rescate","Boris construyó una cuña de piedra a partir del paso; Daria lo sincronizó con los pulsos restantes. Por un momento, el cerrojo se mantuvo sin las manos de Mila.","Ivan llegó a ella, y dieron un paso juntos. Entonces la vena oculta dividió el cuña, enviando una lanza roja hacia su pecho. Mila lo tiró detrás del escudo de piedra. Ella fue golpeada por el reverso a través de su linterna, no con la elección que había elegido para abandonarla. El daño ya no podía ser revertido. Se mantuvo consciente y le pidió que se moviera mientras el escudo todavía estaba.\n\nIvan: «Una forma más. Debe haber una forma más»"},
new string[] {"La doncella contiene la lluvia","Mila colocó su linterna rota en el pestillo y creó un último canal estable. Sabía que duraría más que sus fuerzas, pero solo lo suficiente para que Ivan cruzara con el Corazón.","Le dijo que el hogar que habían soñado era real porque lo habían elegido, aunque no fueran a compartir sus habitaciones. Ivan se arrodilló a su lado y juntó las dos mitades de su recuerdo. Ella le pidió que mantuviera la ventana amplia, que enseñara a alguien el oficio de las linternas y que siguiera viviendo. Él lo prometió entre lágrimas y después levantó el Corazón.\n\nMila: «Lleva la luz. Sigue viviendo donde pueda alcanzarte»."},
new string[] {"Más allá del umbral","Ivan cruzó el umbral a medida que Mila liberó un salto final hacia las montañas. Yaroslav y Boris lo tiraron detrás del muro de protección; Daria selló el pasaje antes que la onda roja pudiera seguir.","La luz del corazón está firme. A través de una abertura estrecha, Ivan vio a Mila más allá del polvo que caía. El calor pasó, y el motor volvió a ser piedra. Los compañeros reabrieron el camino más pequeño de seguridad inmediatamente. Ivan volvió sin el corazón, dejándolo en las manos vigiladas de sus amigos.\n\nIvan: «Guard the Heart. Voy a volver por ella»"},
new string[] {"El silencio después de su nombre","Encontraron a Mila en la cámara ya fría. Ivan la sostuvo mientras la última luz azul abandonaba la linterna rota.","Ella lo oyó pronunciar su nombre y respondió con el de él. Sus últimas palabras fueron sencillas: se alegraba de que se hubieran encontrado en el camino. Entonces murió. Ningún pacto oculto la devolvió a la vida; ningún beso cambió la pérdida. Boris la envolvió con cuidado en una tela limpia, y los compañeros la sacaron juntos. Habían salvado el Corazón y derrotado a Varkul. Aquel precio no era una prueba de amor, y no lo llamaron justo.\n\nMila: «Me alegro de que fueras tú a quien encontré en el camino»."},
new string[] {"La carga compartida por cuatro","Fuera del Horno, Ivan no podía levantar el corazón y Mila está envuelto solo. Yaroslav tomó el corazón; Boris y Daria hicieron un marco de carga para su amigo.","Cuando Ivan trató de dar órdenes, su voz falló. Daria le dijo claramente los pasos siguientes: descanso, agua y luego la puerta exterior. Los otros aceptaron el trabajo sin pedirle que se convirtiera en un símbolo de resistencia. Detrás de ellos se desvaneció el resplandor rojo del Horno. En dirección, el camino que habían reparado se quedó preparado para llevar a la luz rescatada y al hombre perdido.\n\nDaria: «No tienes que llevar cada parte de esto»"},
new string[] {"Lada en la Puerta de la Lluvia","Lada conoció a los compañeros junto al portón exterior dañado. Ha reparado sus canales sobrevivientes con los artesanos liberados, pero no ha podido restaurar el apoyo colapsado a tiempo.","Cuando vio la linterna rota, entendió antes de que Ivan pudiera hablar. No culpó al aprendiz que los había salvado, ni excusaba a la máquina de su elección. Juntos grabaron lo que había fallado, así ninguna sala futura dependería de una persona con un cierre letal. Luego Lada colocó el círculo de plata a Mila junto al encierro envuelto.\n\nLada: «Nos acordaremos de ella, y vamos a cambiar lo que le falló»"},
new string[] {"El regreso por lugares vivos","Los trabajadores de la Ciudadela abrieron sus puertas a los viajeros. En el Barrio Sunken, Anya ofreció mantas limpias; en Bosque de Cristal los árboles restaurados protegían la estructura de transporte.","Ivan reconoció cada lugar que habían parado para ayudar, ahora ayudándoles a cambio. Le dijo a los que le preguntaron: \"Mila había sido una mujer de cangrejo, guía y aprendiz del profesor. Se negó a que se convirtiera en el momento de su muerte. Su historia pertenecía a la vida que había vivido en el camino.\n\nIvan: «Recuerda lo que hizo posible mientras estaba aquí»"},
new string[] {"Las colinas ante la ciudad","En las colinas de Moscú antigua, Ivan eligió un lugar protegido cerca del resorte para poner a Mila al descanso. Lada y los tres amigos estaban con él.","No plantó ninguna semilla mágica y no esperaba volver de la tierra. Dejó la mitad de las ventanas a su lado, manteniendo al otro bajo el coágulo. Por debajo de ellos, la ciudad aún se quemó a lo largo del exterior. La señal de Vera llamó desde la puerta. Ivan se levantó cuando pudo, y los compañeros continuaron con el corazón hacia la cámara esperando debajo del cuadrado.\n\nIvan: «Te recordaré en la vida que aún tengo»"},
new string[] {"La puerta vuelve a abrirse","La antigua puerta occidental de Moscú se abrió antes que el general la alcanzara. Vera había mantenido los refugios intactos, y sus pozos reparados suministraban las cortafuegos finales.","Los ciudadanos alinearon la carretera despejada sin que se animara. Vieron el agotamiento de los cuatro amigos, la linterna rota y un corazón dorado que se llevaba cuidadosamente entre ellos. Ivan le dio al reloj de la ciudad una cuenta completa: el demonio fue derrotado, El Corazón se recuperó y Milo estaba muerto. Vera escuchaba, luego le asignaba nuevas manos al trabajo de la cámara. El regreso no significa que la tarea haya terminado.\n\nVera: «Hemos tomado el camino. Llevemos la siguiente parte»"},
new string[] {"La ciudad hace sitio a la luz","La plaza seguía llena de refugios y madera salvada. Antes de restaurar el corazón, Ivan ayudó a Vera al alejar las familias del techo inestable.","Boris revisó las reparaciones; Daria coincidió con los nuevos canales a su mapa de regreso. Lada colocó el lente que sobrevivió a Mila en un nicho de señal, donde podía distribuir luz sin llevar calor peligroso. Orel, frágil pero vivo ha reconocido las rutas reparadas que llegan más allá de la ciudad. El Corazón regresaría a una red más amplia que la de donde había sido robado.\n\nOrel: «Has traído de vuelta los caminos, así como la luz»"},
new string[] {"El Corazón encuentra su lugar","Ivan descendió con el Corazón en sus manos. El enchufe bajo la plaza había sido reconstruido con el ward-clay, braces de madera del pueblo y piedra forma por trabajadores liberados.","No había nada que no se tocara; todo estaba listo. La linterna rota de Mila descansó cerca como una memoria, no un mecanismo que requiere otra vida. Ivan colocó el Corazón en su centro original. Por un largo aliento, la cámara se mantuvo oscura. Luego, la luz de oro llenó el anillo reparado y se trasladó hacia fuera por cada canal que habían hecho entero.\n\nIvan: «Para la gente de aquí, y para los que están en el camino»"},
new string[] {"Relámpagos sobre las torres","El pulso restaurado del corazón llegó a la puerta de lluvia por los canales protectores mágicos conectados. Un rayo blanco cruzó el cielo negro por encima de la antigua Moscú, iluminando cada techo quemado y reconstruido arco.","Los ciudadanos se revolotearon, entonces escucharon la profunda respuesta de los truenos. Ivan subió a la plaza cuando las primeras gotas de frío golpearon los cálculos. Daria revisó los drenajes; Vera movieron a la gente bajo cubierta estable. El milagro más esperado llegó con trabajo que hacer, y la ciudad estaba lista para recibirlo sin tratar a maravilla como un sustituto de cuidado.\n\nDaria: «Abre los drenajes. La tormenta es real»"},
new string[] {"La lluvia que apagó el fuego","La lluvia cayó en los torrentes. Las llamas sonreían a lo largo de los techos, luego se doblaban en vapor.","El resplandor rojo de los pozos desapareció, dejando agua lo suficientemente clara como para reflejar las linternas. Ivan estaba bajo el agua hasta que Yaroslav colocó un coágulo sobre sus hombros. A su alrededor, los ciudadanos abrazaron y llevaron agua a brasas escondidas. La ciudad había sido salvada del fuego. No se había ahorrado cada pérdida. Ambas verdades pertenecían al mismo cielo que regresaba.\n\nYaroslav: «Ven bajo la capa. Se te permite tener frío»"},
new string[] {"La primera mañana","Por la mañana, las lluvias pensaron en hilos de plata. La luz solar llegó al cuadrado central a través de nubes desgarradas, tocando piedra mojada y paredes apretadas.","Orel anunció que su ritmo era constante. Ivan vio a la ciudad despertar sin esperar alegría para reemplazar su dolor. La ausencia de Mila se mantuvo al lado del belleza que había ayudado a restaurar. Se sacó la mitad del marco de madera y lo mantuvo en el semáforo. Luego se unió a Boris en una casa dañada, donde todavía había que hacer un verdadero escaparate.\n\nIvan: «La mañana está aquí. Hagamos lugar para eso»"},
new string[] {"Margaritas de ciervo en las colinas","A los pocos días, las margaritas de ciervo blancas se abrieron por las colinas sobre la Antigua Moscú. Eran las flores que los aldeanos siempre habían llamado así: pétalos blancos, centros dorados y hojas finas de un verde plateado.","Las gotas de lluvia aún brillaban en sus tallos. Ivan fue al lugar donde descansaba Mila con Lada y los tres amigos. Llevó un pequeño ramo y habló de la ventana reparada, de los niños que aprendían el oficio de las linternas y de la lluvia que por fin había llegado. Le habló de la vida, porque esa era la promesa que aún podía cumplir.\n\nIvan: «Han florecido. Ojalá pudieras verlas»."},
new string[] {"La escuela de las linternas abiertas","Lada abrió un taller de linterna en una casa reparado cerca del cuadrado. Su primera regla fue escrita sobre el banco: ninguna sala debe requerir una mano cautiva.","Daria ayudó a documentar las liberaciones seguras y señales de fracaso. Boris le enseñó a los estudiantes que construyeran viviendas sonoras antes de confiar en cristales brillantes. Ivan asistió a la primera lección como principiante, luchando con un delicado cierre. Cuando los estudiantes se rieron, él reía con ellos. La nave de Mila continuó a través del aprendizaje, más que mediante una denuncia por haber regresado. Su nombre pertenecía a la obra, no por encima de una demanda para el sacrificio.\n\nLada: «Construye el lanzamiento antes de que construya la luz»"},
new string[] {"El general y la ciudad inconclusa","Ivan mantuvo su mando, pero cambió de trabajo. El reloj reparó caminos, entrenaba equipos de rescate y protegía los asentamientos conectados al Corazón.","La pierna de Yaroslav se sanó lentamente; enseñaba a los capitanes más jóvenes que denunciaran heridas sin vergüenza. Boris supervisó los nuevos cimientos, y Daria publicó un mapa que incluía a las aldeas una vez omitida. Ivan construyó la ventana de colina que había prometido, dejando a su disposición el cuarto para los viajeros. Él no lo llamó el hogar que él y Mila habrían compartido. Fue un lugar de vida hecho posible al recordarla.\n\nIvan: «La ciudad está lo suficientemente segura como para reconstruirla. Ese es nuestro próximo deber»"},
new string[] {"La leyenda de la lluvia que regresa","Años después, la gente contaba cómo un general nacido en una aldea y sus tres amigos habían seguido al Corazón robado hasta la oscuridad. Hablaban de Mila, que había hecho transitable el camino, amado libremente y salvado a Ivan cuando el Horno frustró su huida.","Ivan siempre añadía los nombres de los maestros, obreros, refugiados y vecinos que habían hecho posible aquel viaje. Cuando la primera tormenta de primavera llegó a las colinas, abrió la gran ventana. Tras la lluvia llegó el sol, y las margaritas de ciervo brillaron sobre la Antigua Moscú. La leyenda terminaba con una ciudad que seguía viviendo y con un amor recordado sin deshacer la pérdida.\n\nIvan: «Contad también su vida. Hablad de todas las manos que trajeron la luz a casa»."},
},
new string[][] { // fr
new string[] {"Le puits du village","Dans le village de Zarech, où des marguerites du cerf blanches poussaient au-dessus d'une rivière argentée, Ivan avait appris à réparer un toit avant de savoir porter une épée. Des années plus tard, il y revint en tant que général de la garde de Moscou l'Ancienne.","Les villageois accueillirent le commandant, mais son amie de toujours, Daria, lui demanda s'il connaissait encore leurs noms. Ivan répondit en aidant à réparer le puits du village. Ce soir-là, un messager arriva : le Cœur sacré de la ville s'était mis à battre de façon irrégulière. Ivan laissa sa bannière de cérémonie et prit son manteau de voyage.\n\nIvan : « Une ville, ce sont les gens qui doivent vivre avec nos décisions. »"},
new string[] {"La salle sous la place","Sous la place centrale, Ivan entra dans une chambre construite autour d'une pierre lumineuse : le Cœur de Moscou l'Ancienne. Sa lumière traversa les canaux enterrés jusqu'aux puits, aux jardins et aux salles de protection.","Le gardien Orel lui a montré une fissure de la ligne des cheveux dans l'anneau externe. Quelqu'un avait nourri le cœur murmurant de méfiance, tournant la peur de la ville contre ses défenses. Ivan a ordonné que la chambre soit scellée pendant que les gardes de la ville fouillaient les canaux. Au-dessus d'eux, les lanternes du festival ont flippé, bien qu'aucun vent ne se soit déplacé dans les rues.\n\nOrel : « Elle ne nous protège que pendant que sa lumière peut nous atteindre »"},
new string[] {"Une porte de fumée","Les chuchotements volés ont ouvert un passage étroit à travers le mur de la chambre. Une figure de pierre noire est passée par elle, portant une lanterne en fer remplie de fumée rouge.","Il était Malrec, envoyé de Varkul, le seigneur de la Fournaise Creuse. Ivan frappa la lanterne, mais sa fumée se divisa en trois ombres et glissa autour de lui. Orel a tiré le général clair alors que l'anneau extérieur s'est brisé. Malrec a soulevé le Cœur sans le toucher. Pour un instant terrible, chaque lanterne de Moscou l'Ancienne a jeté une ombre vers le ciel.\n\nMalrec : « Ta peur nous a ouvert la porte »"},
new string[] {"La nuit des braises","Quand le Cœur a disparu, les canaux enterrés se sont inversés. Des embûches éclatèrent des fontaines vides; l'obscurité s'empara entre les maisons, et les flammes montèrent sur les toits de bois.","Ivan ne pouvait pas poursuivre Malrec alors que les gens étaient piégés sous une passerelle effondrée. Il ordonna aux gardes de la ville de couper des pare-feu et de porter un enfant sur la place. De la crête ouest est venu le son de trois cloches de fer, bien qu'aucune tour n'était là. Orel a reconnu le signal de la Fournaise Creuse. Le Cœur était porté au-delà des frontières de la ville vivante.\n\nIvan : « Ouvrez les couloirs. Personne n'est laissé pour compte »"},
new string[] {"Trois compagnons prêts à partir","Yaroslav, le plus ancien capitaine d'Ivan, a organisé la montre restante. Boris, maçon et forgeron du village, a renforcé les abris.","Daria a cartographié le mouvement du feu et a trouvé un sentier où l'obscurité coulait vers l'ouest. Les trois ont proposé de rejoindre Ivan. Il a d'abord refusé: un général ne devrait pas vider les défenses de sa ville pour une poursuite privée. Yaroslav a placé le commandement entre les mains du capitaine Vera, qui avait déjà sécurisé les abris. Ensemble, ils ont convenu d'une mission de sauvetage avec quatre voyageurs et une ville qui pourrait encore se protéger.\n\nDaria : « Prenez-nous parce que nous pouvons vous aider, pas parce que nous sommes vos amis »"},
new string[] {"La dernière lumière du gardien","Orel a survécu à la chambre brisée, mais le départ du Cœur avait diminué la pierre de protection magique qu'il portait. Il a donné à Ivan son étincelle restante dans une boussole en cristal.","La boussole pointait vers le Cœur chaque fois que son porteur se souvenait de quelqu'un qu'il voulait protéger. Il ne pouvait pas distinguer une route d'un mur, et il n'offrait aucune promesse de victoire. Orel avertit que Varkul voulait plus qu'une ville en feu : il voulait que ses survivants croient que chaque sauvetage nécessite une nouvelle victime. Ivan a accepté la boussole et a rejeté ce marché.\n\nIvan : « Alors nous devons ramener plus qu'une pierre »"},
new string[] {"La porte qui résistait encore","À la porte ouest, les gardes de la ville supplièrent Ivan de prendre une force plus importante. Au-delà des murs, cependant, une vaste armée attirerait l'attention de la Fournaise et laisserait les abris exposés.","Ivan a choisi la route étroite. Avant de partir, il a donné l'ordre à Vera d'abriter les familles, de garder les puits couverts et d'enregistrer chaque personne disparue. Les quatre voyageurs passèrent sous l'arche survivante. Derrière eux, les citoyens ordinaires ont levé une barrière de patchwork contre les étincelles qui tombent. Ivan a regardé en arrière une fois, comprenant que la résistance de la ville avait déjà commencé.\n\nVera : « Apportez l'aube. Nous allons tenir une place pour elle »"},
new string[] {"La route des cendres","Ash a effacé les marques routières à l'extérieur de Moscou l'Ancienne. Daria a récupéré leur direction des coupes de drainage sous la poussière; Boris a posé des pierres plates à travers le sol chaud.","Au coucher du soleil, ils ont découvert des réfugiés dans une chapelle sans toit. La boussole s'étendait vers l'ouest, loin des familles échouées, mais Ivan s'arrêtait. Yaroslav distribua leur nourriture de rechange tandis que les autres allèrent vers les abris de la ville. Le retard leur a coûté la lumière du jour. Il a également prouvé que la mission du général ne serait pas permise de transformer les personnes qu'il servait en obstacles.\n\nYaroslav : « Un cœur sauvé signifie peu pour une ville vide »"},
new string[] {"Un ruban épargné par le feu","Au bord du champ de cendres, un ruban indigo étroit accroché à un poteau noirci. Contrairement à tout ce qui l'entoure, le tissu est resté frais.","Daria a trouvé des marques correspondantes sur des pierres voisines : quelqu'un avait guidé les réfugiés à travers des passages sûrs. Ivan a suivi les panneaux d'une source scellée sous une dalle. Quand Boris l'a déplacé, l'eau claire s'est levée à travers les cendres. Un message éraflé sur la pierre ne s'appelait pas auteur, seulement un avertissement: le pont occidental écoutait la peur parlée. Ivan a jeté le ruban à côté de la boussole.\n\nDaria : « Quelqu'un a marché cette route devant nous, et s'est soucié de qui est venu après »"},
new string[] {"Le pont des trois cloches","Le pont ouest se tenait au-dessus d'un ravin rempli d'obscurité contre nature. Trois cloches vides accrochées au-dessus de son centre.","Quand Boris a admis qu'il craignait la chute de la portée, la première cloche sonna et une planche disparut. Ivan a demandé à chaque compagnon d'indiquer un danger pratique et une réponse pratique. Yaroslav a fixé une corde, Daria a identifié les supports de pierre, et Boris a testé les planches restantes. Leur honnêteté a maintenu le pont; la panique seule avait nourri son sort. Au loin, la lanterne d'une femme apparaît parmi les arches ruinées.\n\nIvan : « Donnez le danger. Alors nommez ce que nous pouvons faire »"},
new string[] {"La lanterne au-delà du ravin","La femme au-delà du pont n'a pas attendu pour être secourue. Elle abaissait une corde à deux inconnus piégés sur un rebord.","Ivan s'est joint à elle, et ensemble ils ont conduit les voyageurs à la sécurité. Elle s'est présentée comme Mila, une apprentie des Gardiens de la Pluie disparus, et a demandé si le général avait l'intention d'aider les gens ou simplement de vaincre un ennemi. Ivan répondit en donnant aux étrangers les derniers manteaux secs. Mila a remarqué le ruban indigo à sa ceinture. C'était à elle, laissée pour marquer un chemin que les flammes ne pouvaient pas avaler.\n\nMila : « Gardez le ruban. Il y a encore des gens qui ont besoin de la route »"},
new string[] {"Une source sous la pierre","Mila conduisit les compagnons à une maison de printemps couverte où la chaleur du Fournaise ne pouvait entrer. Elle pouvait guider l'eau le long de vieux canaux de protection magiques, mais ne pouvait pas invoquer la pluie ni restaurer le Cœur volé.","Boris a réparé le bassin brisé tandis que Mila a nettoyé la main brûlée d'Ivan. Le général la remerciait trop formellement, et elle riait à la distance qu'il gardait derrière son titre. À l'extérieur, Yaroslav se tenait sur ses gardes; à l'intérieur, Daria comparait les traces de Mila avec sa propre carte. Leurs voyages séparés ont commencé à devenir une route.\n\nMila : « Vous pouvez poser votre rang assez longtemps pour boire »"},
new string[] {"La carte à deux mains","La carte de Daria s'est terminée au ravin. La mémoire de Mila a commencé au-delà, où le brouillard en mouvement a dissimulé la route à la fournaise Hollow.","Seul, aucun des deux guides ne pouvait atteindre le repaire du démon. Ensemble, ils ont tracé une route à travers le Bois de Verre, le Sunken Quarter et la Citadelle de Cinders. Mila a insisté pour rejoindre l'expédition parce que les Gardiens de la Pluie manquants avaient laissé des records le long de ce chemin. Ivan a accepté son expertise sans promettre son obéissance. À l'aube, cinq voyageurs ont quitté la maison de printemps, liée par un but commun plutôt qu'un commandement.\n\nDaria : « Votre mémoire est une route. Ma carte peut lui donner des bords »"},
new string[] {"Le verger sans ombres","Ils entrèrent dans un verger d'arbres à feuilles d'argent dont les racines avaient été endurcies par la magie de Fournaise. Aucun fruit ne resta, et chaque tronc jeta la même ombre, quelle que soit la lumière.","Mila a découvert que les ombres retenaient l'eau souterraine. Ivan voulait couper un chemin droit, mais Boris a averti que les racines maintenaient la pente ensemble. Ils ont desserré le sort un arbre à la fois. Lorsque l'eau coulait, des feuilles vivantes apparaissaient sous la croûte d'argent. Ivan a commencé à voir la restauration comme une sorte de victoire qu'on ne lui avait jamais apprise à diriger.\n\nBoris : « Une route qui s'effondre derrière nous n'est pas une route de retour »"},
new string[] {"La promesse du général","Une patrouille de suie entourait le verger : des gardes humanoïdes silencieux sculptés à partir de pierre noire fissurée. Yaroslav a formé une ligne de bouclier tandis qu'Ivan a combattu un chemin vers le sol supérieur.","Mila a redirigé une source sous les gardes, refroidissant leurs articulations jusqu'à ce qu'ils se verrouillent. Ensuite, Ivan a promis de garder le danger loin d'elle. Mila a refusé une promesse qu'il ne pouvait pas tenir. Elle a demandé la vérité sur chaque risque et une voix dans chaque décision. Ivan était d'accord, mal à l'aise avec combien cette simple honnêteté exigeait de lui.\n\nMila : « Ne promets pas que je n'aurai jamais peur. Promets-toi d'écouter »"},
new string[] {"Lettres dans une tour en ruine","À l'intérieur d'une tour de signalisation ruinée, Mila a trouvé une lettre Gardien de la Pluie scellée en verre. Il décrivait le vol de pierres de protection moins magiques de Varkul et sa tentative de construire une couronne à partir de lumière empruntée.","La dernière page avait été retirée. Ivan a fouillé l'étage supérieur et a découvert que le signal de la tour pouvait encore atteindre la ville. Il dicta un message pour Vera: le Cœur survécut, et la mission avait trouvé un guide. Mila ajouta calmement les directions du printemps restauré. Hope, ils ont accepté, devrait voyager avec quelque chose que les gens pourraient utiliser.\n\nIvan : « Dites-leur où se trouve l'eau. Alors dis-leur que nous revenons »"},
new string[] {"Une table pour cinq","La pluie ne tomba pas, mais une brume froide permit aux compagnons de se reposer sous la tour. Boris a préparé un mince souper dans un pot réparé.","Yaroslav a dit à Mila que Ivan avait essayé de commander une fuite de toit et a perdu l'argument. Pour la première fois depuis le vol, Ivan a ri. Mila a parlé de la maison qu'elle espérait construire, avec une fenêtre assez large pour voir la première tempête du printemps. Ivan a décrit le puits d'eau du village. Leurs souhaits semblaient ordinaires, et pour cette raison plus précieux que n'importe quel trésor enchanté.\n\nMila : « Quand c'est fini, je voudrais une chambre qui n'appartient à aucune prophétie »"},
new string[] {"Le prix d'un raccourci","Une nouvelle route apparut pendant la nuit, pavée de pierre blanche intacte. À son entrée, un messager sans visage offrait le passage droit au Cœur en échange de la boussole cristalline.","Mila soupçonnait une affaire de Fournaise, mais les pierres de la route étaient réelles. Daria a découvert que chaque étape déplaçait la sortie plus loin. Ivan a refusé le commerce et a conduit tout le monde à la voie difficile. Avant de disparaître, le messager a révélé que Varkul connaissait le nom de Mila. Elle avait espéré que son voyage lui resterait caché.\n\nIvan : « Une promesse qui bouge lorsqu'elle est testée n'est qu'un autre piège »"},
new string[] {"La vérité incomplète de Mila","Mila a admis que son professeur était entré dans la Fournaise et n'était jamais revenu. Elle avait passé des mois après des fragments des records des Gardiens de la Pluie, espérant apprendre ce qui s'est passé.","Sa lanterne était le dernier instrument de travail de cet ordre, et Varkul avait essayé de la saisir avant. Ivan a été blessé qu'elle avait attendu pour lui dire, mais a reconnu combien peu de confiance un uniforme seul méritait. Il a demandé ce que la lanterne pouvait faire d'autre. Mila répondit avec véridicité: elle ne savait pas encore. Ils étaient d'accord pour dire que l'incertitude ne serait pas cachée.\n\nMila : « Je peux te donner ce que je sais. Je ne peux pas vous donner de certitude »"},
new string[] {"La porte du Bois de Verre","À l'entrée de Bois de Verre, des troncs translucides formaient un mur autour d'une vieille porte. Sa serrure répondait à la boussole et à la lanterne ensemble.","Lorsque Ivan et Mila les ont élevés, la porte s'ouvrit sur une forêt qui reflétait un ciel et qu'elle n'avait pas vu. Daria a marqué le seuil avec la craie ordinaire afin qu'aucun sort ne puisse effacer le chemin du retour. Yaroslav resserra ses sangles de bouclier ; Boris porta des coins supplémentaires pour un sol instable. Les compagnons entraient en équipe. Derrière eux, les nouvelles feuilles du verger roulaient pour la première fois.\n\nYaroslav : « Marquez le retour avant de passer à l'étape suivante »"},
new string[] {"Les arbres de lumière empruntée","Les coffres de Bois de Verre entreposés en plein jour. Chaque branche a montré un souvenir différent de Moscou l'Ancienne, certains vrai et d'autres inventé.","Ivan vit le village intact par le feu et s'éloigna presque du sentier. Mila a testé la vision avec sa lanterne; elle ne reflétait pas l'eau et ne jetait aucun souffle humain sur le verre. Ils ont brisé la fausse image sans endommager la racine vivante au-dessous. Daria a commencé à marquer des arbres dignes de confiance avec du cordon. La forêt serait traversée par l'observation, et non par la confiance dans la scène la plus brillante.\n\nMila : « Une belle réponse peut encore être la mauvaise route »"},
new string[] {"La seconde chance du capitaine","Yaroslav a rencontré un reflet de soldats qu'il n'avait pas réussi à sauver des années auparavant. Le verre lui a offert une bataille qu'il pourrait gagner cette fois s'il abandonnait les autres.","Il a baissé son bouclier et a avoué l'ancienne défaite à Ivan. Le général n'a pas offert d'absolution facile. Il a rappelé à son ami les gens qui attendent sur la route actuelle. Ensemble, ils se sont éloignés de la réflexion. Yaroslav a laissé une bande de tissu bleu sur le tronc, une petite reconnaissance qui se souvient perte n'a pas besoin de devenir un abandon à elle.\n\nYaroslav : « Je m'en souviens. Je n'abandonnerai pas les vivants pour les suivre »"},
new string[] {"La mesure du maçon","Un escalier scintillant traversa un chasme, mais Boris ne vit aucune articulation portante. La pierre magique exigeait que les voyageurs croient en sa force.","Boris a plutôt construit un appareil simple à partir de poutres tombées et a montré les autres où chaque pied devrait atterrir. L'escalier s'est rompu exactement là où il l'avait prédit, laissant intact leur section de bras. Mila a aidé à refroidir les surfaces coupées pendant que Daria mesurait la portée restante. Ivan a remercié Boris d'être en désaccord avec lui avant la traversée. L'autorité d'un général, il apprenait, doit laisser de la place pour une meilleure réponse.\n\nBoris : « La confiance est la bienvenue. Un joint sonore est encore nécessaire »"},
new string[] {"La carte de ce qui reste","Daria a découvert que Bois de Verre se déplaçait autour des souhaits plutôt que des pas. Chaque fois que quelqu'un imaginait atteindre la Fournaise, la destination bougeait.","Elle a cartographié ce qui pouvait être touché: un puits de pierre, un arc tombé, une piscine qui sentait la pluie. La route qui en résultait semblait tortueuse, mais restait stable. Mila a ajouté des marques du voyage de son professeur, y compris une spirale à côté de la piscine. Ivan a reconnu cette spirale de la chambre du cœur. Pour la première fois, la disparition des Gardiens de la Pluie et la lumière volée de la ville semblaient appartenir au même dessein.\n\nDaria : « Nous allons cartographier ce qui reste, pas ce que la forêt promet »"},
new string[] {"Le bassin des mots tus","La piscine spirale tenait des voix au lieu de réflexions. Ivan a entendu l'espoir de Mila pour une maison, et elle a entendu sa crainte qu'il revienne comme un héros dans une ville de tombes.","Embarrassés, ils essayèrent de partir, mais l'eau se leva sur leur chemin. Mila a suggéré de parler directement pour que la piscine ne les possède plus. Ivan a admis qu'il commençait à s'occuper d'elle au-delà de la mission. Elle a dit que le sentiment était mutuel, puis lui a demandé de le laisser grandir sans en faire un vœu fait sous siège.\n\nMila : « Sélectionnons-nous en plein jour aussi »"},
new string[] {"Le collectionneur d'éclats","Un lieutenant de Fournaise masqué nommé Serev a gardé le centre de la forêt. Il a récolté des durs du jour et offert de les revendre aux personnes dont ils avaient été volés.","Quand Ivan a refusé, Serev a scellé la piste avec du verre brûlant. Daria a identifié sa ligne d'approvisionnement; Boris a brisé ses supports tandis que Yaroslav protégeait les autres. Mila a refroidi le mur, et Ivan a brisé le masque du lieutenant. Serev s'est échappé par une fente de fumée, laissant son magasin de lumière du jour derrière. Les compagnons le libèrent dans les arbres au lieu de le prendre comme butin.\n\nIvan : « La lumière prise d'une maison n'est pas à vous de vendre »"},
new string[] {"La clairière des vraies étoiles","La lumière du jour a ouvert une clairière où le vrai ciel nocturne pouvait être vu. Les compagnons se reposèrent sans qu'un guetteur essaie de négocier avec eux.","Mila a appris à Ivan comment sa lanterne mesurait l'humidité dans l'air. Il lui montra la tache de tissu sous son armure, cousue par sa mère avant son premier commandement. Ils ont parlé des gens qui avaient rendu leur travail possible. Quand leurs mains se sont rencontrées sur la poignée de la lanterne, ni se sont retirées. Le moment était assez petit pour leur appartenir seul.\n\nIvan : « J'aimerais vous connaître quand personne n'a besoin de sauver »"},
new string[] {"La lettre sans sceau","Près de la clairière, Mila a trouvé une lettre de son professeur, Lada. Il a expliqué que le Cœur ne pouvait être retourné que par une séquence ininterrompue de canaux de protection magiques.","Une évasion violente pourrait récupérer la pierre tout en détruisant la route qui a porté sa maison légère. Lada était entrée dans la Fournaise pour découvrir une route plus sûre. La lettre s'est terminée par un avertissement au sujet d'un appareil appelé Verrou de Cendre. Son but était manquant, mais son contour ressemblait à la spirale qu'Ivan avait vue sous la ville. Les compagnons ont copié toutes les lignes avant de passer à autre chose.\n\nMila : « Elle cherchait un moyen de ramener tout le monde »"},
new string[] {"Un baiser avant le seuil","À la porte lointaine de Bois de Verre, l'aube apparaît comme une bande mince au loin. Ivan a offert à Mila le choix de retourner dans les refuges avec les dossiers récupérés.","Elle a choisi de continuer, puis lui a posé la même question. Il sourit à se faire offrir une sortie de sa propre légende. Avant de rejoindre les autres, ils ont partagé un premier baiser tranquille. Ni le nom de destin. Ils ont promis de continuer à demander, à écouter et à faire place à un avenir plus grand que cette route. La porte s'ouvrit vers la périphérie noyée.\n\nMila : « Je suis ici parce que je choisis d'être »"},
new string[] {"La forêt rend ses trésors","Comme les cinq voyageurs sont partis, la croûte de verre est tombée des arbres les plus proches. Les branches vertes émergeaient sans avaler les vieux chemins.","Daria a envoyé un second signal vers Moscou l'Ancienne, marquant la forêt comme un refuge possible. Yaroslav a enregistré le masque du lieutenant et la direction de son évasion. Boris a gardé un feu inoffensif pour le cadre fissuré de la boussole. Ivan regarda en arrière la clairière restaurée et comprit le modèle du voyage: chaque endroit réparé pouvait devenir une partie de la route maison. Au-dessous de la crête, des tours ruinées s'élèvent de l'eau sombre.\n\nBoris : « Nous ne trouvons pas seulement la route. Nous la rendons utilisable »"},
new string[] {"Les rues sous l'eau immobile","Le quartier Sunken avait appartenu à une petite colonie sur l'ancienne route commerciale. La magie de la fournaise l'avait inondée sans pluie, tenant l'eau encore au-dessus des poutres du toit.","Mila pouvait faire une voie sèche étroite, mais ne pouvait pas la maintenir longtemps. Daria a localisé une chaussée relevée sur sa carte; Boris a testé des marches submergées avec un poteau. Ivan a ordonné des passages courts et des arrêts de repos répétés plutôt qu'une ruée héroïque. Sous la surface, des lumières de fenêtre pâles se déplaçaient de maison en maison, les invitant à quitter la voie sûre.\n\nIvan : « Nous croisons au rythme que notre guide peut maintenir »"},
new string[] {"La maison à la fenêtre sèche","Une chambre haute est restée sèche. Un potier âgé, Anya, avait scellé sa fenêtre avec des glaçons et abrité plusieurs voisins à l'intérieur.","Ils avaient survécu en ramassant la condensation et en partageant le grain. Ivan a aidé à abaisser les habitants à la chaussée tandis que Boris a étudié le phoque d'argile. Mila a reconnu une recette Gardien de la Pluie cachée dans le travail ordinaire du potier. Anya leur donna une poche d'argile et demanda que son but soit rappelé. Aucun titre n'avait protégé la pièce; la compétence, la patience et les voisins qui se faisaient confiance l'avaient fait.\n\nAnya : « Prenez l'argile. Laissez la connaissance à quelqu'un qui en a besoin »"},
new string[] {"Le marché des tasses vides","Au marché noyé, les tasses planaient au-dessus des étals abandonnés. Chaque coupe offrait d'enlever un souvenir douloureux, laissant le voyageur plus léger et moins certain de la raison de leur venue.","Yaroslav en a presque accepté une après avoir entendu les voix de ses soldats perdus. Mila y versa de l'eau ordinaire. La tasse s'est cassée, révélant la fumée cachée à l'intérieur. Ensemble, les compagnons ont brisé le sort du marché et récupéré des vaisseaux utiles pour les réfugiés. Ivan a gardé son chagrin et sa peur. Il n'abandonnerait pas les gens à l'intérieur d'eux pour faciliter la route.\n\nYaroslav : « La douleur peut me faire du mal sans avoir à prendre mes décisions »"},
new string[] {"Le registre sous la cloche","Une cloche de chapelle était posée sous l'eau, reposant sur une porte d'archives scellée. Boris et Yaroslav l'ont levé avec un levier en bois tandis que Mila tenait l'eau de côté.","À l'intérieur, Daria a trouvé des preuves que les serviteurs de Varkul avaient redirigé les canaux magiques de protection du quartier vers la Fournaise. Les inondations étaient un réservoir pour l'énergie volée. Un deuxième dossier nommé Lada comme prisonnier transféré à la Citadelle des Cinders. L'espoir de Mila s'est levé trop vite, et Ivan a demandé doucement quel était l'âge du disque. Ils ont porté la preuve sans prétendre qu'elle avait promis la survie.\n\nIvan : « Nous allons suivre le dossier. Nous ne le ferons pas dire plus qu'il ne le fait »"},
new string[] {"Une danse sur la chaussée","Avec les habitants en toute sécurité au-delà de l'inondation, Anya a brouillé un vieux morceau de village. Daria a tapé son rythme sur une tasse vide, et Boris a ajouté un rythme inégal.","Mila a pris la main d'Ivan et lui a appris quelques pas sur la large chaussée. Il a déménagé comme un commandant essayant de marcher à travers une danse, ce qui lui a fait rire jusqu'à ce qu'elle ait presque oublié le froid. Le moment n'a pas effacé le danger. Elle leur rappelait ce que le danger menaçait : des plaisirs ordinaires, partagés librement, sans qu'aucun ennemi ne décide de leur prix.\n\nMila : « Vous pouvez diriger une armée. Je dirigerai cette danse »"},
new string[] {"L'eau qui montait","Malrec est revenu à minuit et a inversé le courant du quart. L'eau a grimpé les murs de la tour et a pressé contre la chaussée.","Ivan voulait le poursuivre, mais Mila ne pouvait tenir qu'une voie d'évacuation ouverte. Le général a choisi de protéger à nouveau les résidents. Daria a ouvert une porte de drainage tandis que Boris a cassé les dents de fer la tenant fermée. Yaroslav a bloqué la lanterne de Malrec assez longtemps pour que tout le monde se retire. L'envoyé s'est échappé, furieux que son appât avait échoué. Le quartier drainé a révélé un escalier en pierre menant sous l'ancien réservoir.\n\nIvan : « Laissez-le courir. Gardez la voie ouverte »"},
new string[] {"Le réservoir des noms","Au-dessous du quartier, les murs du réservoir portaient le nom de personnes dont les pierres magiques de protection avaient été volées. L'écriture rayonnait chaque fois que quelqu'un se souvenait de la personne qu'elle appelait.","Daria a trouvé des villages omis de chaque carte qu'elle possédait. Mila a trouvé le nom de Lada, encore faiblement allumé. Ivan a commandé une copie complète, refusant de traiter des vies inconnues comme moins dignes de sauvetage. La boussole s'est renforcée quand il a lu les noms à haute voix. La lumière du Cœur n'a pas été attirée seulement vers sa propre maison; elle a reconnu les soins dispensés au-delà des rues familières.\n\nDaria : « Un endroit manquant est toujours un endroit. Nous allons le remettre sur la carte »"},
new string[] {"Ce que la lanterne ne peut réparer","Mila a trouvé le logement brisé d'une lanterne Gardien de la Pluie. Elle a essayé de le réparer jusqu'à ce que ses mains secouent, mais son cristal intérieur avait été consumé.","Ivan s'assit à côté d'elle sans lui ordonner de se reposer ni de lui dire que la perte avait un but. Elle a fini par poser les fragments. Elle a admis que sauver le cœur ne sauverait peut-être pas son professeur. Ivan a admis qu'il craignait de perdre Mila maintenant qu'il avait commencé à imaginer un avenir avec elle. Ils ont laissé les deux vérités rester, et ont partagé le silence sans essayer de le transformer en courage.\n\nIvan : « Tu n'as pas à rendre ça utile »"},
new string[] {"L'escalier du retour de la lumière","En utilisant l'argile d'Anya, Boris a scellé les joints endommagés du réservoir. Mila a redirigé sa puissance restante vers les canaux vides vers Moscou l'Ancienne.","Pendant un moment, la boussole a montré une route complète d'or, puis a diminué à une pause sous la Citadelle. Daria a marqué l'écart comme leur prochain objectif. Au-dessus d'eux, les résidents secourus ont recommencé à ouvrir des salles sèches. Les compagnons laissèrent les outils et les instructions, transformant le refuge en une colonie de travail. Rétablir le Cœur nécessiterait ce même travail à une plus grande échelle.\n\nBoris : « Magic ouvre la chaîne. Quelqu'un doit encore réparer ses murs »"},
new string[] {"La citadelle à l'horizon rouge","De l'escalier supérieur, les voyageurs virent la Citadelle de Cinders suspendue au-dessus d'une plaine écartée. Ses tours se tenaient sur de grandes chaînes reliées à la Fournaise Creuse au-delà.","Sous la citadelle, les villageois portaient des pierres pour réparer les murs que leurs ravisseurs n'arrêtaient pas de briser. Ivan a étudié les gardes plutôt que de tirer son épée. Mila a reconnu la marque de lanterne de son professeur sur une fenêtre de prison. L'itinéraire était devenu une mission de sauvetage ainsi qu'un vol défait. Ensemble, ils ont prévu une entrée qui laisserait une issue à plus de cinq personnes.\n\nIvan : « Nous n'entrons pas avant de savoir comment les prisonniers partent »"},
new string[] {"Une porte pour les ouvriers captifs","Daria a découvert une porte d'approvisionnement sous la chaîne ouest de la Citadelle. Les ouvriers captifs se déplaçaient à intervalles fixes, surveillés par des gardes de pierre qui suivaient les sons plutôt que les visages.","Yaroslav a créé une diversion avec des plaques de bouclier lâches tandis que Boris a bloqué le faisceau de verrouillage de la porte. Ivan et Mila ont guidé le premier groupe à travers un passage de drainage. Les travailleurs ont choisi des représentants pour organiser leur propre évasion. Le général leur a donné sa carte et a demandé quels dangers il avait manqués. Leur connaissance a changé le plan avant que les gardes ne remarquent l'ouverture.\n\nIvan : « Vous connaissez cette prison. Montrez-nous où notre plan est mauvais »"},
new string[] {"L'atelier des étés volés","A l'intérieur de la Citadelle, des pots de lumière chaude accrochés au-dessus d'un atelier. Chacun tenait un été volé à une pierre de protection magique, laissant sa maison froide et stérile.","Boris a trouvé la marque maçonnée de son village sur un conduit démantelé et a compris à quel point la Fournaise avait atteint. Mila ouvrit soigneusement les pots, retournant leur lumière aux canaux intacts les plus proches. Ivan voulait détruire l'atelier, mais les prisonniers pouvaient utiliser ses outils. Ils brisèrent les siphons, gardèrent les bancs et firent de la pièce le poste de secours de la voie d'évacuation.\n\nBoris : « Détruire ce qui asservit. Gardez ce qui peut aider quelqu'un à vivre »"},
new string[] {"La prisonnière qui attendait la pluie","Mila a trouvé Lada vivant dans la cellule marquée, affaiblie mais toujours en train d'étudier les murs. Leur réunion a commencé avec des larmes et est devenue un argument quand Lada a demandé à son apprenti de partir.","Mila refusa de laisser la peur décider pour l'un d'eux. Lada a révélé que le cœur était intact à l'intérieur du moteur de la couronne de Varkul. Le Verrou de Cendre l'a connecté à la Fournaise : enlever le Cœur déclencherait une poussée de retour par chaque canal de protection magique volé. Lada avait trouvé un moyen de détourner cette poussée, mais l'ancre extérieure nécessaire restait au-delà de la citadelle.\n\nLada : « Je voulais une solution. J'ai trouvé la forme du danger »"},
new string[] {"Le commandant des cendres","Le commandant de la Citadelle, Ruzhen, a bloqué les escaliers de la prison avec une lame forgée à partir d'une lumière de quartier capturée. Il se moquait d'Ivan pour avoir ralenti sa mission aux étrangers libres.","Ivan répondit à travers la bataille elle-même : Yaroslav protégeait les prisonniers tandis que le général tirait Ruzhen loin de l'étroite sortie. Daria a libéré un contrepoids, séparant le commandant de sa source d'énergie. Boris a brisé le conduit exposé. L'arme de Ruzhen est devenue du fer ordinaire, et Ivan l'a vaincu sans s'effondrer dans les escaliers. Les prisonniers passaient par l'espace que leur ravisseur avait réclamé.\n\nIvan : « Vos prisonniers ne sont pas le prix de ma victoire »"},
new string[] {"Le moteur de la couronne","D'une galerie d'entretien, les compagnons virent une vision du moteur de la Fournaise. Le Cœur d'or planait à l'intérieur d'un cadre de fer en forme de couronne, alimentant la lumière rouge dans le trône lointain de Varkul.","Quatre ancres maintiennent le système stable : la chaîne Citadelle, la racine de Bois de Verre, le réservoir Sunken et une porte de pluie extérieure. Ils en avaient déjà restauré deux. Boris pourrait libérer l'ancre de la Citadelle sans tuer les ouvriers en bas, si quelqu'un a d'abord remplacé sa charge par des supports de pierre. Ivan a encore retardé la poursuite. Un cœur retrouvé se reposant au-dessus des prisonniers écrasés serait une défaite.\n\nDaria : « Le moteur a quatre ancres. Nous pouvons changer la façon dont il échoue »"},
new string[] {"La dispute sur le parapet","Ivan a demandé à Mila d'accompagner Lada et les prisonniers libérés à la sécurité. Elle entendit des soins, mais aussi le retour d'un commandement déguisé en protection.","Mila lui a rappelé leur promesse de verger. Il a admis que l'amour avait rendu le danger suffisamment personnel pour obscurcir son jugement. Elle a admis qu'elle cachait parfois l'épuisement pour paraître indispensable. Ils se sont entendus sur des limites partagées : aucun symptôme caché, aucune affaire privée, et aucune décision sur la vie d'une autre personne prise sans la voix de cette personne. Leur amour devint plus fort parce que le désaccord avait été permis d'exister.\n\nMila : « Demande-moi de rester en sécurité. Ne décidez pas de ma place pour moi »"},
new string[] {"Une promesse sans prophétie","Ce soir-là, Ivan a sculpté un petit cadre de fenêtre en bois dans une caisse d'emballage cassée. Il l'a donnée à Mila comme une promesse de la maison qu'elle avait décrite.","Mila a attaché son ruban indigo à travers lui, puis a cassé le cadre en deux pièces correspondantes afin que chacun puisse porter la moitié. Ils ont convenu que les souvenirs ne garantissaient rien; ils étaient des rappels à chercher une vie après la mission. Elle l'a embrassé sous le parapet inachevé. Au-dessus d'eux, aucune étoile n'est apparue, mais ni attendu que le ciel approuve leur choix.\n\nIvan : « Une fenêtre pour la première tempête de printemps. Si nous le choisissons tous les deux encore »"},
new string[] {"La chaîne sous la ville","Boris et les ouvriers libérés ont construit les supports ensemble. Daria a vérifié les charges pendant que Yaroslav gardait les gardes du chantier.","Ivan a atteint l'écluse de la chaîne principale et a trouvé Malrec attendant avec une nouvelle lanterne à fumée. Au lieu de se battre seul, il appela ses compagnons et garda le passage jusqu'à leur arrivée. Mila refroidit la lanterne ; Yaroslav la rompit avec son bouclier. Malrec s'enfuit vers la Fournaise, dépouillée de son arme la plus facile. Les ouvriers ont libéré la chaîne, et la Citadelle s'est installée en toute sécurité sur les fondations qu'ils avaient faites.\n\nIvan : « J'ai besoin de toi ici. C'est un ordre que j'aurais dû apprendre plus tôt »"},
new string[] {"La route de sortie de Lada","Lada a refusé de passer son sauvetage à attendre tranquillement. Elle a organisé les travailleurs libérés en équipes de réparation et a donné à Daria la formule pour la porte de pluie extérieure.","Elle retournait avec les évacués vers le Sunken Quarter, renforçant les canaux magiques de protection derrière l'expédition. Avant de se séparer, elle a dit à Mila que le courage n'était pas mesuré par la douleur qu'elle pouvait endurer. Mila a promis de garder cette leçon. Leurs adieux étaient incertains, mais ils avaient aussi un plan pratique : signaux, points de rencontre et personnes responsables de chaque tronçon de la route.\n\nLada : « Apportez toute votre maison, pas seulement la partie qui peut être utile »"},
new string[] {"La porte au-delà de la citadelle","La route de Fournaise a commencé à une arche faite de cendres refroidies. Lorsque l'ancre de la Citadelle s'est déconnectée, l'arc a fêlé et a révélé un chemin à travers une montagne de verre rouge.","La lanterne de Mila a diminué en ouvrant le premier sceau. Elle l'a immédiatement dit à Ivan, honorant leur accord. Ils ont divisé les tâches de la lanterne entre les lampes ordinaires et la boussole pour conserver sa force. Yaroslav a laissé un marqueur pour les équipes de Lada. Les cinq voyageurs ont continué, portant un itinéraire rendu plus sûr par tous ceux qui avaient choisi de le réparer derrière eux.\n\nMila : « La lanterne est plus faible. Je vous le dis avant qu'il échoue »"},
new string[] {"La montagne qui soufflait la chaleur","Les passages de la montagne se sont élargis avec la respiration de la Fournaise. L'air chaud poussait vers l'extérieur à de longs intervalles; entre eux, les tunnels tiraient tout vers le centre.","Daria mesurait le rythme avec des fils suspendus tandis que Boris fixait des plates-formes de repos dans les murs. Ivan ne bougea les compagnons que pendant le souffle extérieur. Dans la première chambre sûre, Mila a trouvé des gouttes d'eau claire sous le verre rouge. La porte de pluie extérieure était encore vivante quelque part à l'intérieur de la montagne, cachée sous des couches de chaleur volée.\n\nDaria : « Nous passons au rythme que nous mesurons, pas à celui que nous espérons »"},
new string[] {"La salle des épées inachevées","Une forge abandonnée tenait des rangées d'épées sans poignées. La Fournaise avait fabriqué des armes sans qu'il ne reste personne pour les porter.","Boris reconnut que les lames étaient des collecteurs de lumière, puisant l'énergie de chaque personne qui entrait. Il a recouvert leurs bords de coupe d'argile de pupille tandis que Mila a mis à la terre la lumière stockée dans un égout. Ivan a trouvé une simple épée inachevée et l'a laissée là où elle se trouvait. Sa propre arme, entretenue par des mains humaines, était suffisante. Au mur lointain, le motif refroidi de la forge a révélé la première clé de la porte de pluie.\n\nBoris : « Une arme qui prend de son wielder est une autre chaîne »"},
new string[] {"Un marché avec la voix d'Ivan","Varkul a parlé à travers la forge en utilisant la voix d'Ivan. Il a offert de rendre le Cœur si le général a rendu la lanterne de Mila.","Il a même promis sa sécurité, mais a refusé de nommer les gens dont les canaux de protection magiques resteraient esclaves. Ivan a demandé une réponse complète; la voix d'imitation n'a répété que l'offre. Mila leva la lanterne et révéla le conduit parlant. Ensemble, ils l'ont scellé. L'arme la plus dangereuse du démon n'était pas la flamme. C'était une affaire faite pour ressembler à une décision qu'Ivan avait déjà choisie.\n\nIvan : « Si ta miséricorde ne peut pas en donner le prix, ce n'est pas de la miséricorde »"},
new string[] {"La première Porte de la Pluie","La porte se trouvait sous un sol en verre, un mécanisme circulaire conçu pour appeler les salles d'orage de la ville. Sa pierre avait été fondue par la chaleur.","Boris l'a refroidi progressivement tandis que Daria a aligné les marques de la formule de Lada. Mila n'a utilisé qu'un peu de lumière lanterne, permettant à l'eau propre du mécanisme de transporter le reste. La porte s'ouvrit, mais sa chambre basse était vide. Une ancre centrale avait été enlevée et transportée plus profondément dans la montagne. Restaurer la porte exigerait de trouver cette ancre avant de toucher le Cœur.\n\nMila : « Nous avons ouvert une porte. Nous n'avons pas encore résolu ce qui se cache derrière »"},
new string[] {"Le général dépose sa bannière","Une chambre de garde a exigé la bannière d'un commandant comme le prix de l'entrée. Ivan s'est rendu compte que la Fournaise reconnaissait les symboles de l'autorité plus facilement que les gens sous eux.","Il a enlevé son fermoir d'épaule décoratif et a enveloppé son armure dans un manteau d'ouvrier. Daria a conduit les compagnons à travers le passage d'entretien la chambre de garde ignorée. Mila le regarda laisser l'emblème derrière lui sans ressentiment. Il est resté un général en raison de ses responsabilités, non parce qu'une porte enchantée a reconnu son rang. Au-delà, la deuxième forge a attendu.\n\nIvan : « Le devoir vient avec moi. L'ornement peut rester »"},
new string[] {"Une pièce sans écho","La deuxième forge contenait une chambre qui avalait chaque son. Incapables d'appeler les instructions, les voyageurs travaillaient à partir de signaux qu'ils avaient convenus plus tôt.","Yaroslav a gardé le groupe avec des robinets sur son bouclier; Daria a marqué les dangers dans la craie. Mila prit la main d'Ivan quand les ténèbres s'approfondirent, et il suivit sa lanterne sans essayer de mener chaque pas. A la porte de l'arrière, Boris rétablit un résonateur fissuré. Son est revenu dans une seule ruée, et le premier mot audible de Mila était le nom d'Ivan.\n\nMila : « Ivan. Te voilà »"},
new string[] {"L'ancre disparue","L'ancre de pluie se trouvait dans la troisième forge, transformée en piédestal pour la lumière du jour volée de Serev. Le lieutenant est revenu avec un masque de verre miroir et a essayé de piéger les compagnons dans les visions de leur futur désiré.","Ivan a vu la maison à flanc de colline; Mila a vu Lada en sécurité et souriant. Ils ont reconnu à quel point le piège utilisait précisément ce qu'ils aimaient. Daria a couvert les miroirs pendant que Yaroslav pilonnait le manteau de Serev. Boris libéra l'ancre, et Mila draina les fausses visions. Serev s'enfuit sans son masque, incapable de porter la vérité qu'il avait exposée.\n\nMila : « Wanting a future ne rend pas cette vision réelle »"},
new string[] {"Le secret du Verrou de Cendre","Le dernier schéma de Lada arriva par la ligne de signal réparée. Il confirmait un mécanisme terrible : lorsque le Cœur quitterait le moteur de la couronne, le Verrou de Cendre renverrait la chaleur accumulée vers la ville.","L'ancre de pluie pouvait détourner la plus grande partie de la vague vers la porte extérieure. Un second loquet devait être maintenu à la main dans la chambre du moteur jusqu'à ce que le Cœur franchisse le seuil. La personne qui le tenait pourrait s'échapper si la porte restait stable ; personne n'était obligé de mourir. Ivan insista sur cette distinction et prévit un dégagement à l'aide d'une corde, un étai de secours et une autre sortie.\n\nIvan : « Nous préparons la sortie de tout le monde. Personne ne sera désigné comme sacrifice. »"},
new string[] {"La maison qu'ils voulaient bâtir","Avant de ramener l'ancre, les compagnons se reposèrent dans une alcôve fraîche. Mila demanda à Ivan ce qu'il ferait quand il n'aurait plus besoin de tenir une épée.","Il a répondu qu'il voulait apprendre à construire assez bien pour mériter l'approbation de Boris. Elle imaginait enseigner l'artisanat de lanterne et planter des fleurs de marguerite à l'extérieur de leur fenêtre. Ils ont pressé les deux moitiés de leur garde en bois ensemble. Leur avenir est maintenant spécifique, fait de tâches et d'erreurs qu'ils espèrent partager. Sa tendresse leur donnait des raisons de poursuivre un plan plus sûr, et non une raison d'en abandonner un.\n\nIvan : « Enseigne-moi la lanterne. J'apprendrai la fenêtre »"},
new string[] {"La porte apprend la pluie","Boris réinitialise l'ancre pendant que Daria synchronise le mécanisme. Mila a guidé un fil d'eau à travers chaque canal restauré.","Loin d'ici, la boussole montrait la chambre centrale de Moscou l'Ancienne répondant avec un faible pouls d'or. La porte a fonctionné, bien qu'une fracture rouge sous sa fondation soit restée au-delà de leurs outils. Ils ont documenté la faiblesse et préparé des supports de rechange. Yaroslav a envoyé les résultats à Lada et Vera. Les compagnons ouvraient alors la porte intérieure de la montagne. Au-delà se trouvait la Fournaise Creuse, où le Cœur battait au-dessus du trône vide de Varkul.\n\nDaria : « La route répond. Nous regardons toujours la fracture »"},
new string[] {"Le repaire du Roi Creux","La Fournaise Creuse était une forteresse construite vers l'intérieur, ses tours suspendues au-dessus d'un puits de lumière rouge. Les serviteurs de Varkul avaient façonné chaque couloir pour diriger les visiteurs vers le trône.","Daria a plutôt cherché les routes des travailleurs. Elle a trouvé des poignées de pied et des étagères d'outils à la main cachées derrière les murs cérémoniels. Ivan la suivit à travers les passages étroits tandis que Mila écoutait le pouls du Cœur. Ils entrèrent dans la tanière sans s'annoncer. Au-dessous de la galerie du trône, une chaîne de cellules occupées attendait dans la chaleur.\n\nDaria : « Quelqu'un devait maintenir cet endroit. Leur route sera à nous »"},
new string[] {"Ceux qui restent derrière les murs","Les cellules tenaient des artisans dont les connaissances maintenaient la Fournaise en vie. Parmi eux se trouvait un maçon qui avait coupé la porte de pluie originale.","Elle a averti que sa fondation avait été délibérément affaiblie pour s'effondrer après le retrait du Cœur. Boris lui a demandé de marquer le bord caché de la fracture. Mila passa un signal à Lada, qui pouvait organiser les réparations du côté extérieur. Ivan ouvrit les cellules et donna aux prisonniers des outils plutôt que des ordres. Ils ont choisi de partir immédiatement ou d'aider à démonter la machine qui les avait retenus.\n\nIvan : « Votre liberté n'est pas conditionnelle à nous aider »"},
new string[] {"La résistance du capitaine","Une patrouille a découvert les cellules ouvertes. Yaroslav a tenu un atterrissage étroit pendant que les prisonniers traversaient derrière lui.","Son bouclier s'est fendu sous les lames chauffées des gardes, et une pierre tombée a blessé sa jambe. Ivan est revenu pour aider malgré la boussole le tirant vers le Cœur. Ensemble, ils se sont retirés derrière la barrière temporaire de Boris. Yaroslav a refusé d'appeler la blessure un noble paiement; c'était un problème à traiter. Mila a refroidi l'enflure, Daria a adapté leur itinéraire, et le capitaine a continué avec un personnel au lieu de prétendre que rien n'avait changé.\n\nYaroslav : « Ne louez pas la blessure. Aide-moi à marcher »"},
new string[] {"La porte du maçon","Boris a scellé le passage de la patrouille avec un mur que la Fournaise ne pouvait pas fondre rapidement. Derrière, il a sculpté un étroit bloc amovible, laissant une route de retour délibérée.","Le général a demandé s'il tiendrait. Boris répondit avec une limite, pas une assurance: assez longtemps pour un passage, peut-être deux, si personne n'a frappé la base. Daria a écrit l'état à côté de la carte. Ils ont envoyé les prisonniers restants par la barrière. Chaque limite honnête a rendu leur plan moins glorieux et plus susceptible de garder quelqu'un en vie.\n\nBoris : « Il tient dans ces conditions. Souvenez-vous des conditions »"},
new string[] {"La boussole dérobée","Malrec est sorti d'un plancher de fumée et a saisi la boussole. Son aiguille d'or fila vers le trône, l'éloignant de son chemin d'évasion.","Ivan a failli poursuivre seul, mais Mila l'a arrêté à l'escalier cassé. Daria a reconnu un pont de service au-dessous et a guidé le groupe autour. Ils ont récupéré la boussole de la cage lanterne abandonnée de Malrec. L'envoyé avait appris que la boussole ne servirait pas un porteur qui ne cherchait que possession. Furieux, il rompit la cage et s'enfuit vers son maître pour une autre arme.\n\nMila : « Nous pouvons le récupérer ensemble. Ne transformez pas l'urgence en solitude »"},
new string[] {"Le combat de la jeune femme","Mila a trouvé la voûte de la lanterne de la Fournaise, où des cristaux de Gardien de la Pluie cassés ont alimenté un mur de feu rouge. Ivan a proposé de garder l'entrée pendant qu'elle choisissait comment les libérer.","Avec l'aide de Daria, Mila a changé l'alignement des cristaux au lieu de verser sa propre force dans le mur. Le feu s'est adouci en lumière bleue. Elle a récupéré l'ancienne lentille de son professeur et l'a installée à sa lanterne. L'amélioration ne la rendait pas invincible, mais elle lui donnait plus de contrôle. Ivan admirait l'habileté derrière le miracle plus que le spectacle lui-même.\n\nMila : « Pendez la porte. Cette partie est à moi pour résoudre »"},
new string[] {"La salle des visages empruntés","Varkul a rempli la salle suivante avec des copies de personnes du passé d'Ivan. Chacun a exigé un sauvetage différent, dispersant son attention jusqu'à ce qu'il puisse à peine bouger.","Mila refusa d'identifier le chemin réel en devinant quelle voix semblait la plus sincère. Elle et Daria ont tracé les canaux de protection magiques du sol, tandis que Boris a testé chaque porte. Ivan a suivi le travail qu'ils pouvaient vérifier. Les faces copiées se sont évanouies à mesure que le moteur caché était déconnecté. Un vrai signal est resté: le rapport de Vera que Moscou l'Ancienne tenait encore, et les puits réparés avaient commencé à briller.\n\nIvan : « La ville est toujours là. Nous répondons au vrai message »"},
new string[] {"La dernière lanterne de Malrec","L'envoyé attendait à la porte intérieure avec une lanterne sculptée de la chaîne citadelle. Il a attiré chaque étincelle dans le couloir vers l'armure d'Ivan.","Le général a mis son épée de côté et a utilisé un crochet d'ouvrier pour poser la chaîne. Yaroslav a heurté la charnière de la lanterne ; Mila a refroidi son noyau. Malrec a essayé de s'échapper par la fumée, mais la chaîne à terre a scellé son passage. Sa forme de pierre noire s'est effondrée en cendres inoffensives lorsque Boris a cassé la lanterne vide. Ils ont laissé le couloir intact pour le retour plutôt que de brûler la victoire dans ses murs.\n\nYaroslav : « La charnière, Ivan. Laisse le centre lumineux tranquille »"},
new string[] {"Le seuil du Cœur","Au-delà de la porte intérieure, le Cœur flottait dans le moteur de la couronne. Sa lumière dorée clignotait autour des chaînes rouges, et Ivan reconnut le rythme de la chambre de la ville.","Les cinq voyageurs ont vérifié leur plan une fois de plus : la porte de pluie répondant, la corde fixée, le passage alternatif marqué. Mila actionnait le verrou d'eau parce que son objectif restauré pouvait le contrôler; Boris l'armait, Daria coordonnait la porte et Yaroslav protégeait la sortie. Ivan ferait face à Varkul. Mila lui demanda de la regarder avant de regarder le trône, et il le fit.\n\nMila : « Souviens-toi de la sortie, même quand tu vois ce que tu es venu chercher »"},
new string[] {"Le seigneur qui se nommait Aube","Varkul descendit du trône vide, une figure humanoïde imposante d'obsidiens fissurés enveloppés de robes rouges de braise. Il a affirmé que la lumière volée faisait de lui l'aube légitime de la ville.","Ivan a demandé pourquoi une aube avait besoin de prisonniers, de puits brisés et d'obscurité pour survivre. Le démon a répondu en soulevant les chaînes du moteur de la couronne. Mila a tenu le verrou d'eau ouvert; Daria a appelé les intervalles d'impulsion. Ivan a avancé avec sa lame d'acier ordinaire. La bataille a commencé autour d'une machine qui pouvait être comprise, interrompue et démontée.\n\nIvan : « La lumière qui a besoin de nos ténèbres n'a aucune prétention à nous gouverner »"},
new string[] {"Une couronne faite d'autres vies","La couronne de Varkul tirait sa force des noms gravés sur les canaux de protection magiques volés. Chaque coup qu'Ivan a frappé est revenu comme de la chaleur à travers le sol.","Daria a reconnu les symboles du réservoir et lui a dit de cesser d'attaquer directement la couronne. Mila a ouvert un canal bleu aux comprimés de nom libérés; Boris a coupé le conduit le plus proche. La couronne a perdu une de ses lumières. Ivan a changé d'approche, se battant pour exposer les liens plutôt que de dominer le démon. Varkul recula dès la première chose qu'il ne pouvait remplacer: une source captive devenant libre.\n\nDaria : « Cut la connexion. Ne nourrissez pas la couronne d'un autre coup »"},
new string[] {"Le plan en quatre parties","La bataille s'est étendue sur quatre galeries. Yaroslav a tenu la sortie contre les gardes de suie; Boris a renforcé la serrure; Daria a signalé Lada à la porte extérieure; Mila a contrôlé la pression d'eau.","Ivan ne voyait aucun d'entre eux clairement à travers la chaleur montante, donc il faisait confiance aux signaux convenus. Quand une galerie s'est cassée, Daria a appelé une pause au lieu de cacher le retard. Ivan a tiré Varkul assez longtemps pour que Boris le stabilise. Le plan a fonctionné parce que tout le monde a été autorisé à signaler un échec alors qu'il restait du temps pour répondre.\n\nDaria : « Pause la libération. Le soutien ouest est en mouvement »"},
new string[] {"L'offre d'une ville vivante","Varkul a montré à Ivan une vision de Moscou l'Ancienne restaurée, avec Mila à côté de lui sous un ciel clair. Il l'offrait en échange des noms du réservoir: des étrangers dont les maisons resteraient dans l'obscurité pour toujours.","Ivan ressentait la cruauté d'un choix en forme exactement comme son désir. Il a refusé de parler au nom des gens qui étaient échangés. Mila a fermé la vision avec un ruisseau de sa lanterne. L'offre du démon a échoué parce que leur amour avait fait place à un avenir, mais ne leur avait jamais donné la propriété de quelqu'un d'autre.\n\nIvan : « Je ne peux pas acheter notre maison avec quelqu'un d'autre »"},
new string[] {"La lame de fer ordinaire","Varkul a brisé l'épée d'Ivan à la garde. Boris lui jeta la lame inachevée récupérée de la forge, maintenant équipée d'une poignée en bois uni.","Il n'y avait pas de lumière volée. Ivan l'a utilisé pour ouvrir la plaque d'entretien du moteur de la couronne tandis que Yaroslav a couvert son approche. Daria a appelé les serrures exposées en séquence. Le démon frappa sauvagement alors que sa force devint un ensemble de parties vulnérables. L'arme finale d'Ivan comptait parce qu'elle pouvait accomplir une tâche simple de façon fiable, et non parce qu'une prophétie avait nommé son porteur.\n\nBoris : « C'est du fer à repasser. Faites-le faire le travail »"},
new string[] {"Le verrou refuse de céder","Les trois premières serrures de la couronne ont ouvert. Le quatrième est resté fusionné à un canal de protection magique endommagé sous le trône de Varkul.","Mila a averti que le forcer enverrait une poussée dans la base fracturée de la porte de pluie. Boris et Daria ont proposé de le refroidir par étapes tandis que Lada renforçait la face externe. Ivan a tenu Varkul loin du verrou et a compté les signaux. Ils ont gagné du temps au prix de l'épuisement, mais ont évité une libération aveugle. Sous le trône, une veine rouge invisible a commencé à se réchauffer plus rapidement que leurs diagrammes prévus.\n\nMila : « Ce n'est pas prêt. Donnez le temps à la porte de répondre »"},
new string[] {"Une voix de Moscou l'Ancienne","Le signal de Vera a atteint la chambre par les canaux de protection magiques presque restaurés. Elle a signalé que les citoyens avaient déblayé la prise du Cœur et raccordé les abris à ses canaux.","La ville se préparait à recevoir ce que les compagnons espéraient revenir. Ivan entendit des voix familières sous le crépitement: le potier Anya, les ouvriers libérés, et les gens de la route. Varkul a essayé de les noyer dans le tonnerre du moteur, mais Mila a amplifié le signal. Leur travail était devenu un cercle de gens qui s'aidaient les uns les autres à distance, sans qu'aucun héros ne tienne toute sa force.\n\nVera : « La chambre est prête. La ville travaille avec vous »"},
new string[] {"La couronne tombe","Le signal de Lada a confirmé le premier renfort de la porte de pluie. Daria a libéré la dernière serrure de la couronne, et Boris a coupé le conduit du trône.","La couronne de Varkul s'est brisée en segments de fer terne. Le Cœur s'est levé hors du cadre, toujours tenu par la serrure de cendres intérieure. Ivan a rencontré le démon sur l'escalier inférieur et l'a chassé de la source d'énergie restante. Pour la première fois, Varkul a jeté une ombre ordinaire. Il était encore dangereux, mais il n'était plus vaste avec la lumière prise des autres.\n\nIvan : « Il ne reste rien dans cette couronne qui t'appartient »"},
new string[] {"La défaite de Varkul","Varkul a essayé de se reconnecter au Cœur à travers le trône brisé. Ivan l'a forcé sur le pont d'entretien pendant que Mila scellait le dernier conduit en direct.","Yaroslav a coupé la chaîne du pont au signal de Daria, en laissant tomber sa section vide et en coupant la retraite du démon. Ivan a frappé le noyau de braise exposé dans la poitrine de Varkul avec la lame de fer uni. La flamme volée s'est éteinte. Varkul s'est effondré en fragments froids, et la Fournaise est tombée silencieuse. Ivan avait vaincu le chef du démon, mais le Cœur n'avait pas encore franchi le seuil.\n\nIvan : « La lumière de la ville rentre chez elle »"},
new string[] {"Le Cœur entre des mains humaines","L'écluse de Ash s'est ouverte lorsque Mila a équilibré son dernier canal d'eau. Ivan a levé le Cœur de son berceau.","Sa chaleur était douce, contrairement à la chaleur de la Fournaise, et sa lumière montrait clairement chaque visage épuisé. Boris a vérifié l'accessoire; Yaroslav a commencé à se diriger vers la sortie marquée. Daria a attendu la confirmation de libération de la porte extérieure. Ivan a dit à Mila que le Cœur était libre et a atteint sa main. La libération prévue avec l'aide de la corde aurait dû suivre. Au lieu de cela, la veine rouge sous le trône mort éclata par le sol.\n\nIvan : « Nous l'avons. Maintenant, on nous fait sortir tous »"},
new string[] {"Le dernier ordre de la Fournaise","La mort de Varkul a déclenché un mécanisme d'effondrement caché au-delà de l'écluse de Ash cartographiée. La porte de pluie extérieure a perdu son second support; la corde de libération a brûlé avant que Mila puisse lâcher le verrou.","Elle a immédiatement signalé l'échec. Boris a essayé de remplacer la corde pendant que Daria cherchait un autre contrôle. Ivan a posé le cœur sur un rebord stable et est retourné à Mila. Le moteur a commencé à tirer de la chaleur vers la ville, et une vague rouge a traversé la galerie lointaine. Leur ennemi était parti. Sa machine demandait toujours une réponse.\n\nMila : « La corde est partie. Le loquet retient la surtension »"},
new string[] {"Le choix devant le loquet brisé","Ivan et Boris ont essayé de bloquer le verrou avec l'accessoire de secours. La veine de chaleur cachée adoucit le fer avant qu'il puisse s'asseoir.","Daria a trouvé un passage étroit au seuil, mais aucun second contrôle. Mila a compris le moment : si le Cœur franchissait le seuil alors que le verrou restait maintenu, la poussée se détournerait dans la montagne au lieu de la ville. Elle a demandé aux autres de continuer à chercher une libération pendant qu'Ivan exerçait le Cœur. Ivan a refusé de la quitter sans essayer d'abord le passage restant. Ils travaillaient encore pour cinq survivants.\n\nMila : « Continuez à regarder. Portez-le seulement quand je donne le signal »"},
new string[] {"Le chemin qui s'est refermé","Yaroslav a traversé l'étroit passage pour sécuriser son extrémité. Une dalle tombée a scellé le côté du retour et écrasé le support sous les pieds d'Ivan.","Mila a redirigé le canal d'eau, attrapant la dalle assez longtemps pour que Boris puisse le dégager. L'effort a fissuré sa lentille de lanterne. Daria a essayé de signaler Lada, mais la porte d'effondrement n'a répondu que par des impulsions cassées. Ivan pouvait maintenant atteindre le Cœur et le seuil ; il ne pouvait pas atteindre le verrou de l'extérieur. Mila lui a demandé d'entendre les faits avant de décider de ce que l'espoir permettait encore.\n\nMila : « Écoute ce qui a changé. Alors choisissez avec moi »"},
new string[] {"La dernière tentative de sauvetage","Boris a construit un coin de pierre à partir des marches de la galerie; Daria l'a synchronisé avec les impulsions restantes de la porte extérieure. Un instant, le verrou s'est tenu sans les mains de Mila.","Ivan l'a rejointe, et ils ont fait un pas ensemble. Puis la veine cachée a divisé le coin, en envoyant une lance rouge vers sa poitrine. Mila l'a tiré derrière le bouclier de pierre du verrou. Elle a été frappée par le choc à travers sa lanterne, et non par son choix de l'abandonner. Les dommages ne pouvaient plus être inversés. Elle est restée consciente et lui a demandé de bouger pendant que le bouclier tenait encore.\n\nIvan : « Une autre façon. Il doit y avoir un autre moyen »"},
new string[] {"La jeune femme retient la pluie","Mila plaça sa lanterne brisée dans le loquet, créant un dernier canal stable. Elle savait qu'il durerait plus longtemps que ses forces, mais juste assez pour qu'Ivan traverse avec le Cœur.","Elle lui dit que la maison dont ils avaient rêvé avait été réelle parce qu'ils l'avaient choisie, même s'ils n'en partageraient pas les pièces. Ivan s'agenouilla près d'elle et réunit les deux moitiés de leur souvenir. Elle lui demanda de garder la grande fenêtre, d'enseigner à quelqu'un l'art des lanternes et de continuer à vivre. Il le promit à travers ses larmes, puis souleva le Cœur.\n\nMila : « Emporte la lumière. Continue à vivre là où elle peut te rejoindre. »"},
new string[] {"Au-delà du seuil","Ivan a franchi le seuil alors que Mila lâchait la dernière vague dans la montagne. Yaroslav et Boris le tirèrent derrière le mur abritant ; Daria scella le passage avant que la vague rouge ne puisse suivre.","La lumière du Cœur s'est stabilisée. À travers une ouverture étroite, Ivan vit Mila au-delà de la poussière tombée, toujours à côté du canal bleu qu'elle avait fait. La chaleur est passée, et le moteur est redevenu pierre. Les compagnons rouvrirent immédiatement le plus petit chemin sûr. Ivan est revenu sans le Cœur, le laissant entre les mains de ses amis.\n\nIvan : « Gardez le cœur. Je retourne la chercher »"},
new string[] {"Le silence après son nom","Ils trouvèrent Mila dans la chambre refroidie. Ivan la tenait dans ses bras tandis que la dernière lueur bleue quittait la lanterne brisée.","Elle l'entendit prononcer son nom et répondit par le sien. Ses derniers mots furent simples : elle était heureuse qu'ils se soient rencontrés sur la route. Puis elle mourut. Aucun pacte caché ne la ramena ; aucun baiser ne changea la perte. Boris l'enveloppa avec soin dans un linge propre, et les compagnons l'emportèrent ensemble. Ils avaient sauvé le Cœur et vaincu Varkul. Ce prix n'était pas une preuve d'amour, et ils ne le qualifièrent pas de juste.\n\nMila : « Je suis heureuse que ce soit toi que j'aie rencontré sur la route. »"},
new string[] {"Le fardeau partagé à quatre","En dehors de la Fournaise, Ivan ne pouvait pas soulever seul le corps enveloppé du Cœur et de Mila. Yaroslav a pris le Cœur; Boris et Daria ont fait un cadre de transport pour leur ami.","Quand Ivan a essayé de donner des ordres, sa voix a échoué. Daria lui dit clairement les étapes suivantes: repos, eau, puis la porte extérieure. Les autres acceptèrent l'œuvre sans lui demander de devenir un symbole d'endurance. Derrière eux, la lueur rouge de la Fournaise s'estompait. À l'avant, la route qu'ils avaient réparée restait prête à transporter à la fois la lumière sauvée et la personne qu'ils avaient perdue.\n\nDaria : « Tu n'as pas à porter toutes les parties de ça »"},
new string[] {"Lada à la Porte de la Pluie","Lada rencontra les compagnons à côté de la porte extérieure endommagée. Elle avait réparé ses canaux survivants avec les artisans libérés, mais n'avait pas été en mesure de rétablir le soutien effondré à temps.","Quand elle a vu la lanterne cassée, elle a compris avant qu'Ivan puisse parler. Elle ne blâmait pas l'apprenti qui les avait sauvés, ni n'excusait la machine qui avait forcé le choix. Ensemble, ils ont enregistré ce qui avait échoué pour qu'aucun futur service ne dépende d'une personne tenant un verrou mortel. Puis Lada a placé le cercle argenté de Mila à côté de la lanterne enveloppée.\n\nLada : « Nous nous souviendrons d'elle, et nous changerons ce qui l'a déçue »"},
new string[] {"Le retour à travers des lieux vivants","Les ouvriers de la Citadelle ont ouvert leurs portes aux voyageurs. Dans le quartier Sunken, Anya offrait des couvertures propres; dans Bois de Verre, les arbres restaurés abritaient le cadre de transport.","Ivan a reconnu chaque endroit où ils s'étaient arrêtés pour aider, maintenant les aider en retour. Il a dit à ceux qui ont demandé que Mila avait été une artisane, guide, apprentie d'enseignant, et quelqu'un qui se moquait de sa danse. Il a refusé de la laisser devenir seulement le moment où elle est morte. Son histoire appartenait à la vie qu'elle avait vécue le long de la route.\n\nIvan : « Souviens-toi de ce qu'elle a rendu possible pendant qu'elle était ici »"},
new string[] {"Les collines devant la ville","Sur les collines au-dessus de Moscou l'Ancienne, Ivan a choisi un endroit abrité près du printemps pour poser Mila pour se reposer. Lada et les trois amis se tenaient avec lui.","Il n'a planté aucune graine magique et ne s'attendait pas à un retour de la terre. Il laissa à côté d'elle la moitié de la fenêtre en bois, gardant l'autre sous son manteau. Au-dessous d'eux, la ville brûlait encore le long de ses voies extérieures. Le signal de Vera a appelé de la porte. Ivan se leva quand il le pouvait, et les compagnons continuèrent avec le Cœur vers la chambre qui attendait sous la place.\n\nIvan : « Je me souviendrai de toi dans la vie que j'ai encore »"},
new string[] {"La porte s'ouvre à nouveau","L'ancienne porte occidentale de Moscou s'ouvrit avant que le général ne l'atteigne. Vera avait gardé les abris intacts, et les puits réparés fournissaient les derniers pare-feu.","Les citoyens ont tracé la route libre sans applaudir. Ils virent l'épuisement des quatre amis, la lanterne brisée, et le Cœur d'or porté soigneusement entre eux. Ivan a donné à la montre de la ville un compte rendu complet: le démon a été vaincu, le Cœur a récupéré, et Mila était mort. Vera écoutait, puis attribuait de nouvelles mains au travail de chambre. Le retour ne signifiait pas que la tâche était terminée.\n\nVera : « Nous avons tenu la route. Portons la partie suivante »"},
new string[] {"La ville fait place à la lumière","La place est restée bondée d'abris et de bois récupéré. Avant de restaurer le Cœur, Ivan a aidé Vera à éloigner les familles du plafond instable de la chambre.","Boris a vérifié les réparations; Daria a comparé les nouveaux canaux à sa carte de retour. Lada a placé la lentille survivante de Mila dans la niche du signal, où elle pouvait distribuer la lumière sans porter de chaleur dangereuse. Orel, fragile mais vivant, a reconnu les routes réparées allant au-delà de la ville. Le Cœur retournerait à un réseau plus large que celui d'où il avait été volé.\n\nOrel : « Vous avez ramené les routes ainsi que la lumière »"},
new string[] {"Le Cœur retrouve sa place","Ivan descendit avec le Cœur dans ses mains. La douille sous la place avait été reconstruite avec l'argile de quartier d'Anya, les accessoires en bois de village, et la pierre façonnée par les ouvriers libérés.","Rien n'était intact, tout était prêt. La lanterne cassée de Mila reposait à proximité comme un souvenir, pas un mécanisme nécessitant une autre vie. Ivan a placé le Cœur dans son centre d'origine. Pour un long souffle, la chambre est restée sombre. Puis la lumière d'or remplissait l'anneau réparé et se déplaçait vers l'extérieur par chaque canal qu'ils avaient fait entier.\n\nIvan : « Pour les gens ici, et pour ceux qui sont sur la route »"},
new string[] {"La foudre au-dessus des tours","Le pouls restauré du Cœur a atteint la porte de pluie par les canaux de protection magiques connectés. Un coup de foudre blanc a traversé le ciel noir au-dessus de Moscou l'Ancienne, illuminant chaque toit brûlé et arche reconstruite.","Les citoyens ont riposté, puis entendu la réponse profonde du tonnerre. Ivan a grimpé sur la place alors que les premières gouttes froides frappaient les pierres. Daria a vérifié les drains; Vera a déplacé les gens sous une couverture stable. Le miracle tant attendu est arrivé avec du travail à faire, et la ville était prête à le recevoir sans traiter l'émerveillement comme un substitut aux soins.\n\nDaria : « Ouvrez les drains. La tempête est réelle »"},
new string[] {"La pluie qui éteignit le feu","La pluie est tombée dans les torrents. Les flammes sifflaient le long des toits en bois, puis se repliaient en vapeur.","La lueur rouge dans les puits a disparu, laissant l'eau assez claire pour refléter les lanternes. Ivan se tenait sous la pluie, jusqu'à ce que Yaroslav mette un manteau sur ses épaules. Autour d'eux, les citoyens s'embrassaient, transportaient de l'eau jusqu'aux braises cachées, et appelaient les noms des personnes encore disparues. La ville avait été sauvée du feu. Il n'a pas été épargné toutes les pertes. Les deux vérités appartenaient sous le même ciel de retour.\n\nYaroslav : « Venez sous le manteau. Vous avez le droit d'avoir froid »"},
new string[] {"Le premier matin","Le matin, la pluie s'éclaircit en fils d'argent. La lumière du soleil a atteint la place centrale à travers les nuages déchirés, touchant la pierre humide, les murs recoupés et les visages épuisés.","Orel a annoncé que le rythme du Cœur était stable. Ivan a regardé le réveil de la ville sans s'attendre à la joie de remplacer son chagrin. L'absence de Mila est restée à côté de la beauté qu'elle avait aidé à restaurer. Il a sorti sa moitié du cadre de fenêtre en bois et l'a tenu dans la lumière. Puis il a rejoint Boris dans une maison endommagée, où une vraie fenêtre avait encore besoin de faire.\n\nIvan : « Le matin est là. Faisons de la place pour cela »"},
new string[] {"Les marguerites du cerf sur les collines","En quelques jours, des marguerites du cerf blanches s'ouvrirent sur les collines au-dessus de Moscou l'Ancienne. C'étaient les fleurs que les villageois avaient toujours appelées ainsi : des pétales blancs, des cœurs dorés et de fines feuilles vert argenté.","Des gouttes de pluie brillaient encore le long de leurs tiges. Ivan se rendit sur la tombe de Mila avec Lada et les trois amis. Il apporta un petit bouquet et parla de la fenêtre réparée, des enfants qui apprenaient l'art des lanternes et de la pluie enfin revenue. Il lui parla de la vie, car c'était la promesse qu'il pouvait encore tenir.\n\nIvan : « Elles ont fleuri. J'aurais tant aimé que tu les voies. »"},
new string[] {"L'école des lanternes ouvertes","Lada a ouvert un atelier de lanterne dans une maison réparée près de la place. Sa première règle a été écrite sur le banc: aucun pupille ne devrait nécessiter une main captive.","Daria a aidé à documenter les rejets sûrs et les signaux de défaillance. Boris a enseigné aux élèves à construire des logements sonores avant de faire confiance aux cristaux brillants. Ivan a assisté à la première leçon en tant que débutant, luttant avec un fermoir délicat. Quand les élèves riaient, il riait avec eux. L'embarcation de Mila a continué en enseignant plutôt qu'en prétendant qu'elle était revenue. Son nom appartenait à côté de l'œuvre, pas au-dessus d'une demande de sacrifice.\n\nLada : « Construisez la libération avant de construire la lumière »"},
new string[] {"Le général et la ville inachevée","Ivan a gardé son commandement, mais a changé son travail. La montre a réparé des routes, formé des équipes de secours et protégé les colonies reliées au Cœur.","La jambe de Yaroslav guérit lentement ; il enseigna aux jeunes capitaines à signaler les blessures sans honte. Boris a supervisé les nouvelles fondations, et Daria a publié une carte qui comprenait les villages une fois omis. Ivan a construit la fenêtre qu'il avait promise, laissant la chambre à la disposition des voyageurs. Il n'a pas appelé cela la maison qu'il aurait partagé avec Mila. C'était un lieu de vie rendu possible en se souvenant d'elle.\n\nIvan : « La ville est assez sûre pour se reconstruire. C'est notre prochain devoir »"},
new string[] {"La légende de la pluie revenue","Des années plus tard, on racontait comment un général né au village et ses trois amis avaient suivi le Cœur volé jusque dans les ténèbres. On parlait de Mila, qui avait rendu la route praticable, aimé librement et sauvé Ivan lorsque la Fournaise avait brisé leur issue de secours.","Ivan ajoutait toujours les noms des enseignants, des ouvriers, des réfugiés et des voisins qui avaient rendu ce voyage possible. Quand le premier orage de printemps atteignit les collines, il ouvrit la grande fenêtre. Le soleil suivit la pluie, et les marguerites du cerf brillèrent au-dessus de Moscou l'Ancienne. La légende se terminait par une ville qui continuait à vivre et un amour dont on gardait le souvenir sans annuler la perte.\n\nIvan : « Racontez aussi sa vie. Racontez toutes les mains qui ont ramené la lumière chez nous. »"},
},
new string[][] { // de
new string[] {"Der Dorfbrunnen","Im Dorf Zarech, wo oberhalb eines silbernen Flusses weiße Hirschmargeriten wuchsen, hatte Ivan schon gelernt, ein Dach zu flicken, bevor er ein Schwert tragen konnte. Jahre später kehrte er als General der Stadtwache des Alten Moskaus zurück.","Die Dorfbewohner begrüßten den Befehlshaber, doch seine alte Freundin Daria fragte, ob er ihre Namen noch kenne. Ivan antwortete, indem er bei der Reparatur des Dorfbrunnens half. Am Abend traf ein Bote ein: Das heilige Herz der Stadt hatte begonnen, unregelmäßig zu schlagen. Ivan ließ sein Zeremonienbanner zurück und nahm seinen Reisemantel.\n\nIvan: „Eine Stadt besteht aus den Menschen, die mit unseren Entscheidungen leben müssen.“"},
new string[] {"Die Kammer unter dem Platz","Unter dem zentralen Platz trat Ivan in eine Kammer ein, die um einen leuchtenden Stein herum gebaut wurde: das Herz des alten Moskau. Sein Licht reiste durch vergrabene Kanäle zu den Brunnen, Gärten und Schutzstationen.","Keeper Orel zeigte ihm einen Haarriss im äußeren Ring. Jemand hatte das Herz flüstert des Misstrauens gefüttert und die eigene Angst der Stadt gegen ihre Verteidigung gedreht. Ivan bestellte die Kammer versiegelt, während die Stadtwächter die Kanäle durchsuchten. Über ihnen flimmerten die Festivallaternen, doch kein Wind bewegte sich durch die Straßen.\n\nOrel: „Es bewacht uns nur, solange sein Licht uns erreichen kann“"},
new string[] {"Eine Tür aus Rauch","Das gestohlene Flüstern öffnete einen schmalen Durchgang durch die Kammerwand. Eine Figur aus schwarzem Stein trat durch sie und trug eine eiserne Laterne, die mit rotem Rauch gefüllt war.","Er war Malrec, Gesandter von Varkul, dem Herrn des Hohle Esse. Ivan schlug die Laterne, aber ihr Rauch teilte sich in drei Schatten und rutschte um ihn herum. Orel zog den General klar, als der äußere Ring zerschmetterte. Malrec hob das Herz, ohne es zu berühren. Für einen schrecklichen Augenblick warf jede Laterne im alten Moskau einen Schatten auf den Himmel.\n\nMalrec: „Deine Angst hat uns die Tür geöffnet“"},
new string[] {"Die Nacht des Funkenregens","Als das Herz verschwand, kehrten die vergrabenen Kanäle um. Embers platzten von leeren Brunnen; Dunkelheit zwischen den Häusern versammelt, und Flammen kletterten die Holzdächer.","Ivan konnte Malrec nicht verfolgen, während Menschen unter einem eingestürzten Gehweg gefangen waren. Er befahl den Stadtwächtern, Feuerbrüche zu schneiden und ein Kind auf den Platz zu bringen. Vom westlichen Kamm kam das Geräusch von drei eisernen Glocken, obwohl kein Turm dort stand. Orel erkannte das Signal des Hohle Esse. Das Herz wurde über die Grenzen der lebendigen Stadt hinaus getragen.\n\nIvan: „Öffnet die Bahnen. Niemand wird zurückgelassen“"},
new string[] {"Drei, die nicht bleiben wollten","Yaroslav, Ivans ältester Kapitän, organisierte die verbleibende Uhr. Boris, ein Dorf Maurer und Schmied, verstärkte die Unterkünfte.","Daria kartierte die Bewegung des Feuers und fand einen Weg, wo die Dunkelheit nach Westen fließt. Alle drei boten an, sich Ivan anzuschließen. Zuerst weigerte er sich: Ein General sollte die Verteidigung seiner Stadt nicht für eine private Verfolgung leeren. Yaroslav setzte das Kommando in die Hände von Kapitän Vera, der bereits die Schutzräume gesichert hatte. Gemeinsam einigten sie sich auf eine Rettungsmission mit vier Reisenden und einer Stadt, die sich noch schützen könnte.\n\nDaria: „Nimm uns, weil wir helfen können, nicht weil wir deine Freunde sind“"},
new string[] {"Das letzte Licht des Hüters","Orel überlebte die zerbrochene Kammer, aber der Abschied des Herzens hatte den magischen Schutzstein, den er trug, verdunkelt. Er gab Ivan seinen restlichen Funken in einem Kristallkompass.","Der Kompass zeigte auf das Herz, wann immer sich sein Träger an jemanden erinnerte, den er beschützen wollte. Es konnte einen Weg nicht von einer Mauer unterscheiden, und es bot kein Versprechen des Sieges. Orel warnte, dass Varkul mehr als eine brennende Stadt wollte: Er wollte, dass seine Überlebenden glauben, dass jede Rettung ein neues Opfer erforderte. Ivan akzeptierte den Kompass und lehnte diesen Handel ab.\n\nIvan: „Dann müssen wir mehr als einen Stein zurückbringen“"},
new string[] {"Das Tor, das noch standhielt","Am westlichen Tor baten die Stadtwächter Ivan, eine größere Truppe einzunehmen. Hinter den Mauern jedoch zog eine breite Armee die Aufmerksamkeit des Ofens auf sich und ließ die Schutzräume frei.","Ivan wählte die schmale Straße. Vor seiner Abreise gab er Vera den Befehl, Familien zusammen zu beherbergen, die Brunnen bedeckt zu halten und jede vermisste Person aufzuzeichnen. Die vier Reisenden traten unter den erhaltenen Bogen. Hinter ihnen erhoben gewöhnliche Bürger eine Flickenarbeitsbarriere gegen herabfallende Funken. Ivan blickte einmal zurück und verstand, dass der Widerstand der Stadt bereits begonnen hatte.\n\nVera: „Bringt die Morgendämmerung. Wir werden dafür einen Platz haben“"},
new string[] {"Der Weg durch die Asche","Ash löschte die Straßenmarkierungen außerhalb des alten Moskaus. Daria erholte ihre Richtung von Entwässerung Schnitte unter dem Staub; Boris legte flache Steine über den heißen Boden.","Bei Sonnenuntergang entdeckten sie Flüchtlinge in einer dachlosen Kapelle. Der Kompass zog nach Westen, weg von den gestrandeten Familien, aber Ivan blieb stehen. Yaroslav verteilte ihre Vorräte, während die anderen einen Weg zu den städtischen Notunterkünften freimachten. Die Verspätung kostete sie Tageslicht. Es bewies auch, dass die Mission des Generals nicht erlaubt würde, die Menschen, die es diente in Hindernisse zu verwandeln.\n\nYaroslav: „Ein gerettetes Herz bedeutet einer leeren Stadt wenig“"},
new string[] {"Ein unversehrtes Band","Am Rand des Aschefeldes hing ein schmales Indigoband an einem geschwärzten Pfosten. Anders als alles um sie herum blieb das Tuch kühl.","Daria fand passende Markierungen auf nahe gelegenen Steinen: Jemand hatte Flüchtlinge durch sichere Passagen geführt. Ivan folgte den Schildern zu einer Quelle, die unter einer Platte versiegelt war. Als Boris es verschoben hatte, stieg klares Wasser durch die Asche. Eine Nachricht zerkratzt auf dem Stein namens kein Autor, nur eine Warnung: die westliche Brücke hörte gesprochene Angst. Ivan hat das Band neben dem Kompass versteckt.\n\nDaria: „Jemand ging diese Straße vor uns, und kümmerte sich, wer danach kam“"},
new string[] {"Die Brücke der drei Glocken","Die westliche Brücke stand über einer Schlucht voller unnatürlicher Dunkelheit. Drei leere Glocken hingen über der Mitte.","Als Boris zugab, dass er befürchtete, die Spannweite würde fallen, klingelte die erste Glocke und ein Brett verschwand. Ivan bat jeden Gefährten, eine praktische Gefahr und eine praktische Antwort anzugeben. Jaroslav sicherte ein Seil, Daria identifizierte die Steinträger und Boris testete die restlichen Bretter. Ihre Ehrlichkeit stabilisierte die Brücke; Panik allein hatte ihren Bann gestillt. Auf der anderen Seite erschien die Laterne einer Frau unter den zerstörten Bögen.\n\nIvan: „Nennen Sie die Gefahr. Dann nennen Sie, was wir tun können“"},
new string[] {"Die Laterne jenseits der Schlucht","Die Frau hinter der Brücke wartete nicht darauf, gerettet zu werden. Sie senkte ein Seil auf zwei Fremde, die auf einer Kante gefangen waren.","Ivan schloss sich ihr an, und zusammen brachten sie die Reisenden in Sicherheit. Sie stellte sich als Mila vor, eine Lehrlingin der verschwundenen Regenhüter, und fragte, ob der General den Menschen helfen oder nur einen Feind besiegen wolle. Ivan antwortete, indem er den Fremden die letzten trockenen Mäntel gab. Mila bemerkte das Indigoband an seinem Gürtel. Es war ihres, links, um einen Weg zu markieren, den die Flammen nicht schlucken konnten.\n\nMila: „Behalte das Band. Es gibt immer noch Menschen, die den Weg brauchen“"},
new string[] {"Eine Quelle unter Stein","Mila führte die Gefährten zu einem überdachten Springhaus, wo die Hitze des Ofens nicht eindringen konnte. Sie konnte Wasser durch alte magische Schutzkanäle führen, konnte aber weder Regen herbeirufen noch das gestohlene Herz wiederherstellen.","Boris reparierte das gebrochene Becken, während Mila Ivans verbrannte Hand reinigte. Die Generalin dankte ihr zu formal, und sie lachte über die Distanz, die er hinter seinem Titel hielt. Draußen stand Yaroslav Wache; innen verglich Daria Milas Wegmarken mit ihrer eigenen Karte. Ihre getrennten Reisen begannen sich zu einer Route zu entwickeln.\n\nMila: „Du kannst deinen Rang lange genug senken, um zu trinken“"},
new string[] {"Die Karte, die zwei Hände brauchte","Darias Karte endete an der Schlucht. Milas Erinnerung begann darüber hinaus, wo sich der Nebel bewegte und die Straße zum Hohlen Ofen verbarg.","Alleine konnte kein Führer die Höhle des Dämons erreichen. Gemeinsam charteten sie eine Route durch das Glaswald, das Sunken Quarter und die Zitadelle der Cinders. Mila bestand darauf, der Expedition beizutreten, weil die vermissten Regenhüter auf diesem Weg Rekorde hinterlassen hatten. Ivan nahm ihre Expertise an, ohne ihr Gehorsam zu versprechen. In der Morgendämmerung verließen fünf Reisende das Springhouse, das eher durch einen gemeinsamen Zweck als durch ein Kommando gebunden war.\n\nDaria: „Deine Erinnerung ist eine Straße. Meine Karte kann ihr Kanten geben“"},
new string[] {"Der Obstgarten ohne Schatten","Sie betraten einen Obstgarten mit silberblättrigen Bäumen, deren Wurzeln durch die Magie des Ofens verhärtet worden waren. Keine Frucht blieb, und jeder Stamm warf den gleichen Schatten, unabhängig vom Licht.","Mila entdeckte, dass die Schatten Wasser unter der Erde zurückhielten. Ivan wollte einen geraden Weg einschlagen, aber Boris warnte, dass die Wurzeln den Hang zusammenhielten. Sie lockerten den Zauber eines Baumes nach dem anderen. Als das Wasser strömte, erschienen lebendige Blätter unter der silbernen Kruste. Ivan begann, die Wiederherstellung als eine Art Sieg zu sehen, den ihm nie gelehrt worden war, zu führen.\n\nBoris: „Eine Straße, die hinter uns zusammenbricht, ist kein Heimweg“"},
new string[] {"Das Versprechen des Generals","Eine Rußpatrouille umgab den Obstgarten: stille humanoide Wachen, die aus rissigem schwarzen Stein geschnitzt wurden. Yaroslav bildete eine Schildlinie, während Ivan einen Weg zu höheren Boden kämpfte.","Mila lenkte eine Feder unter den Wachen ab und kühlte ihre Gelenke ab, bis sie sich verriegelten. Danach versprach Ivan, Gefahr von ihr fernzuhalten. Mila lehnte ein Versprechen ab, das er nicht halten konnte. Sie bat um die Wahrheit über jedes Risiko und eine Stimme in jeder Entscheidung. Ivan stimmte zu, unbequem mit, wie viel diese einfache Ehrlichkeit von ihm verlangt.\n\nMila: „Versprich mir nicht, niemals Angst zu haben. Versprich, dass du zuhörst“"},
new string[] {"Briefe im zerfallenen Turm","In einem zerstörten Signalturm fand Mila einen in Glas versiegelten Regenhüter-Brief. Es beschrieb Varkuls Diebstahl von weniger magischen Schutzsteinen und seinen Versuch, eine Krone aus geliehenem Licht zu bauen.","Die letzte Seite wurde entfernt. Ivan durchsuchte die obere Etage und entdeckte, dass das Signal des Turms immer noch die Stadt erreichen konnte. Er diktierte Vera eine Botschaft: Das Herz überlebte, und die Mission hatte einen Führer gefunden. Mila fügte leise Anweisungen zur restaurierten Feder hinzu. Hoffe, sie stimmten zu, sollten mit etwas reisen, was die Leute gebrauchen könnten.\n\nIvan: „Erzähl ihnen, wo das Wasser ist. Dann sag ihnen, dass wir wiederkommen“"},
new string[] {"Ein Tisch für fünf","Der Regen fiel nicht, aber ein kalter Nebel erlaubte es den Gefährten, unter dem Turm zu ruhen. Boris kochte ein dünnes Abendessen in einem reparierten Topf.","Yaroslav erzählte Mila, wie Ivan einmal versuchte, ein undichtes Dach zu befehlen und das Argument verlor. Zum ersten Mal seit dem Diebstahl lachte Ivan. Mila sprach von dem Hügelhaus, das sie zu bauen hoffte, mit einem Fenster weit genug, um den ersten Sturm des Frühlings zu sehen. Ivan beschrieb den Brunnen des Dorfes. Ihre Wünsche klangen gewöhnlich, und aus diesem Grund kostbarer als jeder verzauberte Schatz.\n\nMila: „Wenn das vorbei ist, möchte ich einen Raum, der keiner Prophezeiung gehört“"},
new string[] {"Der Preis einer Abkürzung","In der Nacht erschien eine neue Straße, gepflastert mit unberührtem weißen Stein. An seinem Eingang bot ein gesichtsloser Bote im Austausch gegen den Kristallkompass einen Durchgang direkt zum Herzen an.","Mila vermutete ein Esse-Schnäppchen, aber die Steine der Straße waren echt. Daria entdeckte, dass jeder Schritt den Ausgang weiter weg verschoben hat. Ivan lehnte den Handel ab und führte alle zurück auf den schwierigen Weg. Bevor er verschwand, enthüllte der Bote, dass Varkul Milas Namen kannte. Sie hatte gehofft, ihre Reise könne vor ihm verborgen bleiben.\n\nIvan: „Ein Versprechen, das sich beim Test bewegt, ist nur eine weitere Falle“"},
new string[] {"Milas unvollständige Wahrheit","Mila gab zu, dass ihre Lehrerin in den Ofen gegangen war und nie zurückkam. Sie hatte Monate damit verbracht, Fragmente der Aufzeichnungen der Regenhüter zu verfolgen, in der Hoffnung, zu erfahren, was passiert ist.","Ihre Laterne war das letzte Arbeitsmittel dieser Ordnung, und Varkul hatte versucht, sie vorher zu ergreifen. Ivan war verletzt, dass sie gewartet hatte, um es ihm zu sagen, aber erkannte, wie wenig Vertrauen eine Uniform allein verdient. Er fragte, was die Laterne sonst noch tun könne. Mila antwortete wahrheitsgemäß: Sie wusste es noch nicht. Sie waren sich einig, dass Ungewissheit gesprochen werden würde, nicht verborgen.\n\nMila: „Ich kann dir geben, was ich weiß. Ich kann dir keine Gewissheit geben“"},
new string[] {"Die Tür zum Glaswald","Am Eingang zu Glaswald bildeten durchscheinende Stämme eine Mauer um ein altes Tor. Sein Schloss reagierte auf den Kompass und die Laterne zusammen.","Als Ivan und Mila sie aufhoben, öffnete sich das Tor in einen Wald, der einen Himmel reflektierte, den sie nicht gesehen hatten. Daria markierte die Schwelle mit gewöhnlicher Kreide, damit kein Zauber den Rückweg löschen konnte. Yaroslav zog seine Schildgurte fest; Boris trug zusätzliche Keile für instabilen Boden. Die Gefährten traten als Team ein. Dahinter stolperten die neuen Blätter im Obstgarten zum ersten Mal.\n\nYaroslav: „Markieren Sie die Rückkehr, bevor wir den nächsten Schritt machen“"},
new string[] {"Bäume aus geborgtem Licht","Die Koffer von Glaswald haben gestohlenes Tageslicht gespeichert. Jeder Zweig zeigte eine andere Erinnerung an das alte Moskau, einige wahr und einige erfunden.","Ivan sah das Dorf vom Feuer unberührt und trat fast von der Spur weg. Mila testete die Vision mit ihrer Laterne; sie reflektierte kein Wasser und warf keinen menschlichen Atem auf das Glas. Sie brachen das falsche Bild, ohne die lebende Wurzel darunter zu beschädigen. Daria fing an, vertrauenswürdige Bäume mit Schnur zu markieren. Der Wald würde durch Beobachtung gekreuzt werden, nicht durch Vertrauen in die hellste Szene.\n\nMila: „Eine schöne Antwort kann immer noch der falsche Weg sein“"},
new string[] {"Die zweite Chance des Hauptmanns","Yaroslav begegnete einem Spiegelbild der Soldaten, die er Jahre zuvor nicht gerettet hatte. Das Glas bot ihm eine Schlacht, die er gewinnen könnte, wenn er die anderen verlassen würde.","Er senkte seinen Schild und gestand Ivan die alte Niederlage. Der General bot keine einfache Absolution an. Er erinnerte seinen Freund an die Menschen, die auf der gegenwärtigen Straße warten. Gemeinsam gingen sie von der Reflexion weg. Jaroslav hinterließ einen Streifen blauen Tuches auf dem Kofferraum, eine kleine Anerkennung, dass die Erinnerung an Verlust nicht zu einer Kapitulation werden muss.\n\nYaroslav: „Ich erinnere mich an sie. Ich werde die Lebenden nicht verlassen, um ihnen zu folgen“"},
new string[] {"Das Maß des Maurers","Eine glitzernde Treppe überquerte eine Kluft, aber Boris sah keine tragenden Gelenke. Der magische Stein verlangte, dass die Reisenden an seine Stärke glauben.","Boris baute stattdessen eine einfache Zahnspange aus gefallenen Balken und zeigte den anderen, wo jeder Fuß landen sollte. Die Treppe brach genau dort ein, wo er es vorausgesagt hatte, und ließ ihren gespanten Abschnitt intakt. Mila half dabei, die Schnittflächen abzukühlen, während Daria die verbleibende Spannweite misste. Ivan dankte Boris, dass er vor der Überfahrt nicht einverstanden war. Die Autorität eines Generals, er hat gelernt, muss Raum für eine bessere Antwort lassen.\n\nBoris: „Vertrauen ist willkommen. Es ist immer noch ein Geräuschgelenk notwendig“"},
new string[] {"Eine Karte dessen, was bleibt","Daria entdeckte, dass Glaswald sich um Wünsche und nicht um Fußstapfen drehte. Jedes Mal, wenn sich jemand vorstellte, den Ofen zu erreichen, bewegte sich das Ziel.","Sie kartierte, was man berühren konnte: einen Steinbrunnen, einen gefallenen Bogen, einen Pool, der nach Regen roch. Die daraus resultierende Route sah krumm aus, blieb aber stabil. Mila fügte Spuren von der Reise ihrer Lehrerin hinzu, darunter eine Spirale neben dem Pool. Ivan erkannte diese Spirale aus der Herzkammer. Zum ersten Mal schienen das Verschwinden der Regenhüter und das gestohlene Licht der Stadt zum gleichen Design zu gehören.\n\nDaria: „Wir werden kartieren, was bleibt, nicht was der Wald verspricht“"},
new string[] {"Der Teich der ungesagten Worte","Der Spiralpool hielt statt Reflektionen Stimmen. Ivan hörte Milas Hoffnung auf ein Zuhause, und sie hörte seine Angst, dass er als Held in eine Stadt der Gräber zurückkehren würde.","Verblüfft versuchten sie zu gehen, aber das Wasser stieg über ihren Weg. Mila schlug vor, die Worte direkt zu sprechen, damit der Pool sie nicht mehr besitzen würde. Ivan gab zu, dass er begann, sich über die Mission hinaus um sie zu kümmern. Sie sagte, das Gefühl sei gegenseitig, dann bat er ihn, es wachsen zu lassen, ohne es zu einem Gelübde unter Belagerung zu machen.\n\nMila: „Lasst uns auch bei Tageslicht einander wählen“"},
new string[] {"Der Scherbensammler","Ein maskierter Leutnant des Ofens namens Serev bewachte das Waldzentrum. Er erntete Tageslichtscherben und bot an, sie an die Menschen zurück zu verkaufen, von denen sie gestohlen worden waren.","Als Ivan sich weigerte, versiegelte Serev die Spur mit brennendem Glas. Daria identifizierte seine Versorgungslinie; Boris brach seine Stützen, während Yaroslav die anderen schützte. Mila kühlte die Wand ab und Ivan zerbrach die Maske des Leutnants. Serev entkam durch einen Rauchschlitz und ließ seinen Vorrat an Tageslicht zurück. Die Gefährten ließen es in die Bäume, anstatt es als Beute zu nehmen.\n\nIvan: „Das Licht, das einem Zuhause genommen wird, gehört nicht dir“"},
new string[] {"Die Lichtung der echten Sterne","Das freigegebene Tageslicht öffnete eine Lichtung, wo der wahre Nachthimmel zu sehen war. Die Gefährten ruhten ohne einen Wächter, der versuchte, mit ihnen zu verhandeln.","Mila hat Ivan beigebracht, wie ihre Laterne Feuchtigkeit in der Luft gemessen hat. Er zeigte ihr den glatten Tuchpflaster unter seiner Rüstung, genäht von seiner Mutter vor seinem ersten Befehl. Sie sprachen von den Menschen, die ihre Arbeit möglich gemacht hatten. Als ihre Hände auf den Griff der Laterne trafen, zogen sich beide nicht zurück. Der Moment war klein genug, um ihnen allein zu gehören.\n\nIvan: „Ich würde dich gerne kennen, wenn niemand gerettet werden muss“"},
new string[] {"Der Brief ohne Siegel","In der Nähe der Lichtung fand Mila einen Brief ihrer Lehrerin Lada. Es erklärte, dass das Herz nur durch eine ununterbrochene Abfolge von magischen Schutzkanälen zurückgegeben werden konnte.","Eine gewaltsame Flucht könnte den Stein zurückgewinnen und dennoch die Straße zerstören, die ihr Licht nach Hause trug. Lada hatte den Ofen betreten, um eine sicherere Route zu entdecken. Der Brief endete mit einer Warnung vor einem Gerät namens Ascheriegel. Sein Zweck fehlte, aber seine Umrisse ähnelten der Spirale, die Ivan unter der Stadt gesehen hatte. Die Begleiter kopierten jede Zeile, bevor sie weitergingen.\n\nMila: „Sie war auf der Suche nach einem Weg, alle zurückzubringen“"},
new string[] {"Ein Kuss vor der Schwelle","Am fernen Tor von Glaswald erschien die Morgendämmerung als dünnes Band in der Ferne. Ivan bot Mila die Wahl, mit den zurückgewonnenen Akten in die Schutzräume zurückzukehren.","Sie entschied sich, weiterzumachen und stellte ihm dann dieselbe Frage. Er lächelte, als er einen Ausweg aus seiner eigenen Legende bot. Bevor sie wieder zu den anderen kamen, teilten sie einen ruhigen ersten Kuss. Auch nicht Schicksal genannt. Sie versprachen, weiter zu fragen, zuzuhören und Raum für eine Zukunft zu schaffen, die größer ist als diese Straße. Das Tor öffnete sich zum ertrunkenen Stadtrand.\n\nMila: „Ich bin hier, weil ich mich dafür entschieden habe“"},
new string[] {"Der Wald gibt zurück","Als die fünf Reisenden gingen, fiel die Glaskruste von den nächsten Bäumen. Grüne Äste entstanden, ohne die alten Pfade zu schlucken.","Daria schickte ein zweites Signal in Richtung des alten Moskau und markierte den Wald als mögliche Zuflucht. Yaroslav nahm die Maske des Leutnants und die Richtung seiner Flucht auf. Boris hielt einen harmlosen Scherben für den geknackten Rahmen des Kompasses. Ivan blickte auf die restaurierte Lichtung zurück und verstand das Reisemuster: Jeder reparierte Ort konnte Teil des Heimwegs werden. Unter dem Bergrücken stiegen die Ruinentürme aus dunklem Wasser.\n\nBoris: „Wir finden nicht nur den Weg. Wir machen es nutzbar“"},
new string[] {"Straßen unter stillem Wasser","Das versunkene Viertel gehörte zu einer kleinen Siedlung an der alten Handelsstraße. Die Feuermagie hatte sie ohne Regen überflutet und das Wasser noch über den Dachbalken gehalten.","Mila konnte eine schmale trockene Spur machen, konnte sie aber nicht lange ertragen. Daria fand einen erhöhten Damm auf ihrer Karte; Boris testete untergetauchte Stufen mit einer Stange. Ivan bestellte kurze Kreuzungen und wiederholte Ruhestopps, anstatt einen heroischen Ansturm. Unter der Oberfläche bewegten sich helle Fensterlichter von Haus zu Haus und luden sie ein, den sicheren Weg zu verlassen.\n\nIvan: „Wir überqueren in dem Tempo, das unser Führer aufrecht erhalten kann“"},
new string[] {"Das Haus mit dem trockenen Fenster","Ein oberer Raum blieb trocken. Ein alter Töpfer namens Anya hatte sein Fenster mit einem Mist-Clay versiegelt und mehrere Nachbarn im Inneren geschützt.","Sie hatten durch das Sammeln von Kondensation und das Teilen von Getreide überlebt. Ivan half den Bewohnern auf den Damm zu senken, während Boris die Tondichtung studierte. Mila erkannte ein Regenhüter-Rezept, das in der normalen Arbeit des Töpfers versteckt war. Anya gab ihnen einen Beutel Ton und bat darum, sich an seinen Zweck zu erinnern. Kein Titel hatte den Raum geschützt; Geschicklichkeit, Geduld und Nachbarn, die einander vertrauten, hatten dies getan.\n\nAnya: „Nimm den Ton. Lassen Sie das Wissen bei jemandem, der es braucht“"},
new string[] {"Der Markt der leeren Tassen","Auf dem ertrunkenen Markt schwebten Becher über verlassenen Ständen. Jede Tasse bot an, eine schmerzhafte Erinnerung zu entfernen, so dass der Reisende leichter und weniger sicher, warum sie gekommen waren.","Yaroslav nahm fast einen an, nachdem er die Stimmen seiner verlorenen Soldaten gehört hatte. Mila schüttete gewöhnliches Wasser hinein. Die Tasse zerbrach und enthüllte den Rauch, der darin versteckt war. Zusammen brachen die Gefährten den Markt und erholten nützliche Schiffe für die Flüchtlinge. Ivan behielt seine Trauer und Angst. Er würde die Menschen in ihnen nicht aufgeben, um den Weg einfacher zu machen.\n\nYaroslav: „Schmerz kann mich belasten, ohne meine Entscheidungen zu besitzen“"},
new string[] {"Die Aufzeichnung unter der Glocke","Eine Kapellenglocke lag unter Wasser und ruhte auf einer versiegelten Archivtür. Boris und Yaroslav hoben es mit einem Holzhebel auf, während Mila das Wasser beiseite hielt.","Im Inneren fand Daria Beweise dafür, dass Varkuls Diener die magischen Schutzkanäle des Viertels in Richtung Esse umgeleitet hatten. Die Überschwemmungen waren ein Reservoir für gestohlene Energie. Eine zweite Platte namens Lada als Gefangener, die in die Zitadelle der Aschenputtel überführt wurde. Milas Hoffnung stieg zu schnell, und Ivan fragte sanft, wie alt die Platte war. Sie trugen die Beweise, ohne vorzutäuschen, dass sie das Überleben versprachen.\n\nIvan: „Wir werden dem Bericht folgen. Wir werden es nicht mehr sagen lassen, als es tut“"},
new string[] {"Ein Tanz auf dem Damm","Mit den Bewohnern sicher über die Flut hinaus, summte Anya ein altes Dorflied. Daria tippte seinen Rhythmus auf eine leere Tasse, und Boris fügte einen ungleichmäßigen Beat hinzu.","Mila nahm Ivan die Hand und lehrte ihn ein paar Schritte auf dem breiten Damm. Er bewegte sich wie ein Kommandeur, der versuchte durch einen Tanz zu marschieren, was sie zum Lachen brachte, bis sie fast die Kälte vergaß. Der Moment hat die Gefahr nicht ausgelöscht. Es erinnerte sie daran, was die Gefahr bedrohte: gewöhnliche Freuden, frei geteilt, ohne Feind über ihren Preis zu entscheiden.\n\nMila: „Du kannst eine Armee führen. Ich werde diesen Tanz führen“"},
new string[] {"Das Wasser, das hinaufstieg","Malrec kehrte um Mitternacht zurück und drehte die Viertelströmung um. Wasser kletterte auf die Turmmauern und drückte gegen den Damm.","Ivan wollte ihn verfolgen, aber Mila konnte nur eine Fluchtspur offen halten. Der General entschied sich, die Bewohner wieder zu schützen. Daria öffnete ein Entwässerungstor, während Boris die eisernen Zähne brach, die es verschlossen hielten. Jaroslav hat Malrecs Rauchlaterne lange genug blockiert, damit sich alle zurückziehen können. Der Gesandte entkam, wütend, dass sein Köder versagt hatte. Das entwässerte Viertel enthüllte eine Steintreppe, die unterhalb des alten Reservoirs führte.\n\nIvan: „Lasst ihn laufen. Halten Sie die Spur offen“"},
new string[] {"Das Becken der Namen","Unterhalb des Viertels trugen die Staumauern die Namen von Menschen, deren magische Schutzsteine gestohlen worden waren. Das Schreiben leuchtete, wann immer sich jemand an die Person erinnerte, die es genannt wurde.","Daria fand Dörfer, die von jeder Karte weggelassen wurden. Mila fand Ladas Namen, immer noch schwach beleuchtet. Ivan ordnete eine vollständige Kopie an und weigerte sich, unbekannte Leben als weniger rettenswert zu behandeln. Der Kompass verstärkte sich, als er die Namen laut vorlas. Das Licht des Herzens wurde nicht nur auf sein eigenes Zuhause gerichtet; es erkannte, daß die Pflege über vertraute Straßen hinausging.\n\nDaria: „Ein vermisster Ort ist immer noch ein Ort. Wir werden es wieder auf die Karte setzen“"},
new string[] {"Was die Laterne nicht heilen kann","Mila fand das kaputte Gehäuse einer Regenhüter-Laterne. Sie versuchte es zu reparieren, bis ihre Hände zitterten, aber ihr innerer Kristall war verbraucht worden.","Ivan saß neben ihr, ohne ihr zu befehlen, sich auszuruhen oder ihr zu sagen, dass der Verlust einen Zweck hatte. Schließlich stellte sie die Fragmente auf. Sie gab zu, dass die Rettung des Herzens ihren Lehrer nicht retten könnte. Ivan gab zu, dass er befürchtete, Mila jetzt zu verlieren, da er begonnen hatte, sich eine Zukunft mit ihr vorzustellen. Sie ließen beide Wahrheiten bestehen und teilten die Stille, ohne zu versuchen, sie in Mut zu verwandeln.\n\nIvan: „Du musst diesen Schmerz nicht nützlich machen“"},
new string[] {"Die Treppe des heimkehrenden Lichts","Mit Anyas Stationsklaue versiegelte Boris die beschädigten Gelenke des Reservoirs. Mila lenkte seine verbliebene Macht in die leeren Kanäle in Richtung altes Moskau um.","Für einen Moment zeigte der Kompass eine komplette Straße aus Gold, dann bei einer Pause unter der Zitadelle gedimmt. Daria markierte die Lücke als ihr nächstes Ziel. Über ihnen begannen die geretteten Bewohner wieder trockene Räume zu öffnen. Die Gefährten verließen Werkzeuge und Anweisungen, die den Zufluchtsort in eine funktionierende Siedlung verwandelten. Die Wiederherstellung des Herzens würde diese gleiche Arbeit in größerem Umfang erfordern.\n\nBoris: „Magic öffnet den Kanal. Irgendjemand muss noch seine Wände reparieren“"},
new string[] {"Die Zitadelle am roten Horizont","Von der oberen Treppe aus sahen die Reisenden die Zitadelle der Ascher über einer vernarbten Ebene aufgehängt. Seine Türme standen auf großen Ketten verbunden mit dem Hohlofen darüber hinaus.","Unter der Zitadelle trugen die Dorfbewohner Steine, um Mauern zu reparieren. Ivan studierte die Wachen, statt sein Schwert zu ziehen. Mila erkannte das Laternenzeichen ihrer Lehrerin an einem Gefängnisfenster. Die Route war sowohl zu einer Rettungsmission als auch zu einem Diebstahl geworden. Gemeinsam planten sie einen Eingang, der mehr als fünf Menschen einen Ausweg lassen würde.\n\nIvan: „Wir betreten nicht, bis wir wissen, wie die Gefangenen gehen“"},
new string[] {"Ein Tor für die gefangenen Arbeiter","Daria entdeckte ein Versorgungstor unter der westlichen Kette der Zitadelle. Die gefangenen Arbeiter bewegten sich in festen Abständen hindurch, beobachteten von Steinwächtern, die eher Geräusche folgten als Gesichter.","Jaroslav schuf eine Ablenkung mit losen Schildplatten, während Boris den Sperrbalken des Tors blockierte. Ivan und Mila führten die erste Gruppe durch einen Entwässerungsgang. Die Arbeiter wählten Vertreter, um ihre eigene Flucht zu organisieren. Der General gab ihnen seine Karte und fragte, welche Gefahren er verpasst hatte. Ihr Wissen änderte den Plan, bevor die Wachen die Eröffnung bemerkten.\n\nIvan: „Du kennst dieses Gefängnis. Zeig uns, wo unser Plan falsch ist“"},
new string[] {"Die Werkstatt der gestohlenen Sommer","Im Inneren der Zitadelle hingen Gläser von warmem Licht über einer Werkstatt. Jeder hielt einen Sommer aus einem magischen Schutzstein gestohlen, so dass seine Heimat kalt und unfruchtbar.","Boris fand die Steinmetzmarke seines Dorfes auf einem zerlegten Kanal und verstand, wie weit der Ofen erreicht hatte. Mila öffnete die Gläser sorgfältig und brachte ihr Licht auf die nächsten intakten Kanäle zurück. Ivan wollte die Werkstatt zerstören, aber die Gefangenen konnten ihre Werkzeuge benutzen. Sie brachen die Siphons, hielten die Bänke und machten den Raum zur Erste-Hilfe-Station der Fluchtroute.\n\nBoris: „Break was versklavt. Behalten Sie, was jemandem helfen kann“"},
new string[] {"Die Gefangene, die auf Regen wartete","Mila fand Lada lebendig in der markierten Zelle, geschwächt, aber immer noch die Wände zu studieren. Ihre Wiedervereinigung begann mit Tränen und wurde zum Streit, als Lada ihren Lehrling bat, zu gehen.","Mila weigerte sich, Angst für einen von ihnen entscheiden zu lassen. Lada enthüllte, dass das Herz in Varkuls Kronenmotor intakt war. Das Ascheriegel verband es mit dem Ofen: Das Entfernen des Herzens würde einen Rückstoß durch jeden gestohlenen magischen Schutzkanal auslösen. Lada hatte einen Weg gefunden, diese Welle abzulenken, aber der nötige äußere Anker blieb jenseits der Zitadelle.\n\nLada: „Ich wollte eine Lösung. Ich fand die Form der Gefahr“"},
new string[] {"Der Befehlshaber der Glut","Der Kommandant der Zitadelle, Ruzhen, blockierte die Gefängnistreppe mit einer Klinge, die aus dem gefangenen Wärterlicht geschmiedet wurde. Er verspottete Ivan, weil er seine Mission, Fremde zu befreien, verlangsamte.","Ivan antwortete durch die Schlacht selbst: Jaroslav schützte die Gefangenen, während der General Ruzhen vom schmalen Ausgang wegzog. Daria entließ ein Gegengewicht, das den Kommandanten von seiner Machtquelle trennte. Boris zerschmetterte die freigelegte Leitung. Ruzhens Waffe wurde gewöhnliches Eisen, und Ivan besiegte ihn, ohne die Treppen zu stürzen. Die Gefangenen gingen durch den Raum, den ihr Entführer behauptet hatte.\n\nIvan: „Deine Gefangenen sind nicht der Preis meines Sieges“"},
new string[] {"Der Kronenmotor","Von einer Wartungsgalerie aus sahen die Begleiter eine Vision vom Motor des Ofens. Das goldene Herz schwebte in einem kronenförmigen Eisenrahmen und strömte rotes Licht in Varkuls fernen Thron.","Vier Anker hielten das System stabil: die Zitadellekette, die Glaswaldwurzel, das versunkene Reservoir und ein äußeres Regentor. Sie hatten bereits zwei restauriert. Boris konnte den Zitadelle-Anker freilassen, ohne die Arbeiter unten zu töten, wenn jemand seine Ladung zuerst durch Steinstützen ersetzte. Ivan verzögerte die Verfolgung erneut. Ein wiedergefundenes Herz, das über zerschlagenen Gefangenen ruht, wäre eine Niederlage.\n\nDaria: „Der Motor hat vier Anker. Wir können ändern, wie es scheitert“"},
new string[] {"Der Streit auf der Brüstung","Ivan bat Mila, Lada und die befreiten Gefangenen in Sicherheit zu bringen. Sie hörte Pflege, aber auch die Rückkehr eines Kommandos als Schutz verkleidet.","Mila erinnerte ihn an ihr Obstgarten-Versprechen. Er gab zu, daß die Liebe die Gefahr persönlich genug gemacht hatte, um sein Urteilsvermögen zu trüben. Sie gab zu, dass sie manchmal Erschöpfung versteckte, um als unverzichtbar zu erscheinen. Sie einigten sich auf gemeinsame Grenzen: keine versteckten Symptome, keine privaten Schnäppchen und keine Entscheidung über das Leben einer anderen Person ohne die Stimme dieser Person getroffen. Ihre Liebe wurde stärker, weil die Meinungsverschiedenheit bestand.\n\nMila: „Bitte mich, in Sicherheit zu bleiben. Entscheide nicht meinen Platz für mich“"},
new string[] {"Ein Versprechen ohne Prophezeiung","An jenem Abend schnitzte Ivan einen kleinen hölzernen Fensterrahmen aus einer kaputten Verpackungskiste. Er gab es Mila als Versprechen des Hügelheims, das sie beschrieben hatte.","Mila band ihr Indigoband durch und zerbrach dann den Rahmen in zwei passende Stücke, so dass jeder die Hälfte tragen konnte. Sie waren sich einig, dass die Andenken nichts garantierten; sie waren Erinnerungen daran, ein Leben nach der Mission zu suchen. Sie küsste ihn unter dem unvollendeten Parapeten. Über ihnen erschienen keine Sterne, sondern warteten auch nicht auf den Himmel, um ihre Wahl zu billigen.\n\nIvan: „Ein Fenster für den ersten Frühlingssturm. Wenn wir beide es noch wählen“"},
new string[] {"Die Kette unter der Stadt","Boris und die befreiten Arbeiter bauten die Stützen zusammen. Daria überprüfte die Ladungen, während Yaroslav die Wachen von der Baustelle fernhielt.","Ivan erreichte das Schloss der Hauptkette und fand Malrec mit einer neuen Rauchlaterne warten. Statt allein zu kämpfen, rief er seine Gefährten an und hielt den Gang bis sie ankamen. Mila kühlte die Laterne ab; Jaroslav brach sie mit seinem Schild. Malrec flüchtete in Richtung des Ofens, ausgezogen von seiner einfachsten Waffe. Die Arbeiter entließen die Kette, und die Zitadelle ließ sich sicher auf den Fundamenten nieder, die sie gemacht hatten.\n\nIvan: „Ich brauche dich hier. Das ist ein Befehl, den ich früher hätte lernen sollen“"},
new string[] {"Ladas Weg hinaus","Lada weigerte sich, ihre Rettung still zu warten. Sie organisierte die befreiten Arbeiter in Reparaturteams und gab Daria die Formel für das äußere Regentor.","Sie kehrte mit den Evakuierten ins versunkene Viertel zurück und stärkte die magischen Schutzkanäle hinter der Expedition. Bevor sie sich trennte, sagte sie Mila, dass Mut nicht daran gemessen wurde, wie viel Schmerz sie unsichtbar ertragen könne. Mila hat versprochen, diese Lektion zu halten. Ihr Abschied hielt Unsicherheit, aber es hielt auch einen praktischen Plan: Signale, Treffpunkte und Menschen, die für jeden Abschnitt der Straße verantwortlich sind.\n\nLada: „Bring dein ganzes Selbst nach Hause, nicht nur den Teil, der nützlich sein kann“"},
new string[] {"Das Tor jenseits der Zitadelle","Die Esse Straße begann an einem Bogen aus gekühlter Asche. Als sich der Zitadelleanker trennte, brach der Bogen und enthüllte einen Pfad durch einen Berg aus rotem Glas.","Milas Laterne war geplatzt, als sie das erste Siegel öffnete. Sie sagte es Ivan sofort, indem sie ihre Zustimmung einhielt. Sie teilten die Aufgaben der Laterne auf gewöhnliche Lampen und den Kompass, um ihre Stärke zu erhalten. Yaroslav hinterließ einen Marker für Ladas Teams. Die fünf Reisenden fuhren fort und trugen eine Route, die von jedem sicherer gemacht wurde, der sich dafür entschieden hatte, sie hinter ihnen zu reparieren.\n\nMila: „Die Laterne ist schwächer. Ich sage euch, bevor es scheitert“"},
new string[] {"Der Berg, der Hitze atmete","Die Passagen des Berges erweiterten sich mit dem Atem des Ofens. Heiße Luft schob sich in langen Abständen nach außen; zwischen ihnen zogen die Tunnel alles in Richtung Zentrum.","Daria maß den Rhythmus mit hängenden Fäden, während Boris Ruheplattformen in die Wände setzte. Ivan bewegte die Gefährten nur während des äußeren Atemzuges. In der ersten sicheren Kammer fand Mila unter dem roten Glas klare Wassertropfen. Das äußere Regentor war noch irgendwo im Inneren des Berges lebendig, versteckt unter Schichten gestohlener Hitze.\n\nDaria: „Wir bewegen uns auf dem Rhythmus, den wir messen, nicht auf den, den wir hoffen“"},
new string[] {"Die Halle der unfertigen Schwerter","Eine verlassene Schmiede hielt Reihen von Schwertern ohne Griffe. Der Ofen hatte Waffen hergestellt, ohne dass jemand sie trug.","Boris erkannte, dass die Klingen Lichtsammler waren und zog Energie von jeder Person, die eintrat. Er bedeckte ihre Schnittkanten mit Station-Clay, während Mila das gespeicherte Licht durch einen Abfluss geerdet hat. Ivan fand ein einfaches unfertiges Schwert und ließ es dort stehen, wo es stand. Seine eigene Waffe, die von Menschenhand gehalten wurde, war genug. An der weit entfernten Wand enthüllte das abgekühlte Muster des Schmiedes den ersten Schlüssel des Regentors.\n\nBoris: „Eine Waffe, die aus ihrem Wielder nimmt, ist eine weitere Kette“"},
new string[] {"Ein Handel mit Ivans Stimme","Varkul sprach durch die Schmiede mit Ivans eigener Stimme. Er bot an, das Herz zurückzugeben, wenn der General Milas Laterne kapituliert.","Er versprach ihr sogar Sicherheit, weigerte sich aber, die Menschen zu nennen, deren magische Schutzkanäle versklavt bleiben würden. Ivan bat um eine vollständige Antwort; die nachahmende Stimme wiederholte nur das Angebot. Mila hob die Laterne auf und enthüllte die Sprechleitung. Zusammen haben sie es versiegelt. Die gefährlichste Waffe des Dämons war keine Flamme. Es war ein Schnäppchen, um wie eine Entscheidung zu klingen, die Ivan bereits gewählt hatte.\n\nIvan: „Wenn deine Barmherzigkeit ihre Kosten nicht nennen kann, dann ist sie keine Gnade“"},
new string[] {"Das erste Regentor","Das Tor lag unter einem Glasboden, ein kreisförmiger Mechanismus, um die ruhenden Sturmwächter der Stadt zu nennen. Sein Steinwerk war durch Hitze verschmolzen.","Boris kühlte es allmählich ab, während Daria die Markierungen aus Ladas Formel anordnete. Mila benutzte nur ein wenig Laternenlicht, so dass das eigene Wasser des Mechanismus den Rest tragen konnte. Das Tor öffnete sich, aber seine untere Kammer war leer. Ein zentraler Anker wurde entfernt und tiefer in den Berg getragen. Die Wiederherstellung des Tores würde erfordern, diesen Anker zu finden, bevor das Herz berührt wird.\n\nMila: „Wir haben eine Tür geöffnet. Wir haben noch nicht gelöst, was dahinter liegt“"},
new string[] {"Der General legt sein Banner nieder","Eine Wachkammer verlangte das Banner eines Kommandeurs als Eintrittspreis. Ivan erkannte, dass der Ofen die Symbole der Autorität leichter erkannte als die Menschen unter ihnen.","Er entfernte seinen dekorativen Schulterverschluss und wickelte seine Rüstung in einen Arbeitermantel. Daria führte die Gefährten durch den Wartungsdurchgang, den die Wachkammer ignorierte. Mila beobachtete, wie er das Emblem ohne Groll hinter sich ließ. Er blieb ein General wegen seiner Verantwortung, nicht weil ein verzaubertes Tor seinen Rang anerkannte. Darüber hinaus wartete die zweite Schmiede.\n\nIvan: „Die Pflicht kommt mit mir. Die Verzierung kann bleiben“"},
new string[] {"Ein Raum ohne Echo","Die zweite Schmiede enthielt eine Kammer, die jeden Ton verschlang. Unfähig, Anweisungen zu rufen, arbeiteten die Reisenden von Signalen, die sie zuvor vereinbart hatten.","Yaroslav hielt die Gruppe zusammen mit Wasserhähnen auf seinem Schild; Daria markierte Gefahren in Kreide. Mila nahm Ivan die Hand, als sich die Dunkelheit vertiefte, und er folgte ihrer Laterne, ohne zu versuchen, jeden Schritt zu führen. An der anderen Tür restaurierte Boris einen geknackten Resonator. Ton kam in einem einzigen Rausch zurück, und Milas erstes hörbares Wort war Ivans Name.\n\nMila: „Ivan. Da bist du ja“"},
new string[] {"Der fehlende Anker","Der Regenanker stand in der dritten Schmiede, verwandelte sich in ein Podest für Serevs gestohlenes Tageslicht. Der Leutnant kehrte mit einer Maske aus Spiegelglas zurück und versuchte, die Gefährten in Visionen ihrer gewünschten Zukunft einzufangen.","Ivan sah den Hügel zu Hause; Mila sah Lada sicher und lächelnd. Sie erkannten, wie genau die Falle das verwendete, was sie liebten. Daria bedeckte die Spiegel, während Jaroslav Serevs Mantel festhielt. Boris befreite den Anker und Mila entleerte die falschen Visionen. Serev floh ohne seine Maske und konnte die Wahrheit, die er enthüllt hatte, nicht tragen.\n\nMila: „Eine Zukunft zu wollen, macht diese Vision nicht real“"},
new string[] {"Das Geheimnis des Ascheriegels","Ladas letzte Zeichnung traf über die reparierte Signalleitung ein. Sie bestätigte einen schrecklichen Mechanismus: Sobald das Herz den Kronenmotor verließ, würde der Ascheriegel die gespeicherte Hitze zur Stadt zurückschicken.","Der Regenanker konnte den größten Teil der Welle zum äußeren Tor umlenken. Ein zweiter Riegel musste in der Motorkammer von Hand gehalten werden, bis das Herz die Schwelle überschritt. Wer ihn hielt, konnte entkommen, wenn das Tor stabil blieb; niemand musste sterben. Ivan stellte diesen Unterschied ausdrücklich klar und plante eine Befreiung mithilfe eines Seils, eine Ersatzstütze und einen alternativen Ausgang.\n\nIvan: „Wir planen so, dass alle herauskommen. Niemand wird zum Opfer bestimmt.“"},
new string[] {"Das Zuhause, das sie bauen wollten","Bevor der Anker zurück getragen wurde, ruhten die Begleiter in einer kühlen Nische. Mila fragte Ivan, was er tun würde, wenn er kein Schwert mehr halten müsse.","Er antwortete, er wolle lernen, wie man gut genug baut, um Boriss Zustimmung zu verdienen. Sie stellte sich vor, Laternen-Handwerk zu lehren und pflanzen Gänseblümchen Blumen vor ihrem Fenster. Sie drückten die beiden Hälften ihrer hölzernen Andenken zusammen. Ihre Zukunft war jetzt spezifisch, aus Aufgaben und Fehlern gemacht, die sie teilen wollten. Seine Zärtlichkeit gab ihnen Grund, einen sichereren Plan zu verfolgen, nicht einen Grund, einen aufzugeben.\n\nIvan: „Lehre mir die Laterne. Ich werde das Fenster lernen“"},
new string[] {"Das Tor lernt den Regen","Boris setzt den Anker zurück, während Daria den Mechanismus synchronisiert hat. Mila führte einen Wasserfaden durch jeden restaurierten Kanal.","Weit entfernt zeigte der Kompass die zentrale Kammer des alten Moskau, die mit einem schwachen goldenen Puls antwortete. Das Tor funktionierte, obwohl ein roter Bruch unter seinem Fundament über ihre Werkzeuge hinaus blieb. Sie dokumentierten die Schwäche und vorbereiteten Ersatzstützen. Yaroslav schickte die Ergebnisse an Lada und Vera. Die Gefährten öffneten dann die innere Bergtür. Darüber hinaus stand das Hohle Esse, wo das Herz über Varkuls leeren Thron schlug.\n\nDaria: „Die Route antwortet. Wir beobachten immer noch den Bruch“"},
new string[] {"Das Versteck des Hohlen Königs","Das Hohle Esse war eine nach innen gebaute Festung, deren Türme über einem Schacht aus rotem Licht hängen. Varkuls Diener hatten jeden Korridor gestaltet, um Besucher auf den Thron zu lenken.","Daria suchte stattdessen nach den Routen der Arbeiter. Sie fand handgewickelte Fußgriffe und Werkzeugregale, die hinter den zeremoniellen Wänden versteckt waren. Ivan folgte ihr durch die engen Passagen, während Mila dem Puls des Herzens zuhörte. Sie betraten die Höhle, ohne sich selbst anzukündigen. Unterhalb der Throngalerie wartete eine Kette von besetzten Zellen in der Hitze.\n\nDaria: „Jemand musste diesen Ort pflegen. Ihr Weg wird uns gehören“"},
new string[] {"Jene, die noch hinter den Mauern sind","Die Zellen hielten Handwerker fest, deren Wissen die Esse am Leben hielt. Unter ihnen war ein Steinmetze, der das ursprüngliche Regentor durchschnitten hatte.","Sie warnte davor, dass ihr Fundament bewusst geschwächt worden sei, um nach der Entfernung des Herzens zusammenzubrechen. Boris bat sie, den versteckten Rand des Bruchs zu markieren. Mila übergab ein Signal an Lada, die Reparaturen von der äußeren Seite organisieren konnte. Ivan öffnete die Zellen und gab den Gefangenen Werkzeuge statt Befehle. Sie wählten, ob sie sofort gehen oder helfen, die Maschine, die sie gehalten hatte, zu demontieren.\n\nIvan: „Deine Freiheit ist nicht davon abhängig, uns zu helfen“"},
new string[] {"Der Widerstand des Hauptmanns","Eine Patrouille entdeckte die offenen Zellen. Yaroslav hielt eine schmale Landung, während die Gefangenen hinter ihm kreuzten.","Sein Schild riss unter den erhitzten Klingen der Wachen, und ein fallender Stein verletzte sein Bein. Ivan kehrte zurück, um zu helfen, obwohl der Kompass ihn in Richtung Herz zog. Gemeinsam zogen sie sich hinter Boris' temporärer Barriere zurück. Yaroslav weigerte sich, die Verletzung eine edle Zahlung zu nennen; es war ein Problem zu behandeln. Mila kühlte die Schwellung ab, Daria passte ihre Route an, und der Kapitän fuhr mit einem Stab fort, anstatt vorzugeben, nichts hätte sich geändert.\n\nYaroslav: „Lösen Sie die Wunde nicht. Hilf mir zu gehen“"},
new string[] {"Die Tür des Maurers","Boris versiegelte den Patrouillengang mit einer Mauer, die der Ofen nicht schnell schmelzen konnte. Dahinter schnitzte er einen schmalen herausnehmbaren Block und hinterließ eine absichtliche Rückkehrroute.","Der General fragte, ob er halten würde. Boris antwortete mit einer Grenze, nicht mit einer Beruhigung: lang genug für eine Passage, vielleicht zwei, wenn niemand die Basis getroffen. Daria schrieb den Zustand neben der Karte. Sie schickten die restlichen Gefangenen durch, während die Barriere festhielt. Jede ehrliche Grenze machte ihren Plan weniger glorreich und wahrscheinlicher, jemanden am Leben zu halten.\n\nBoris: „Es hält unter diesen Bedingungen. Erinnere dich an die Bedingungen“"},
new string[] {"Der geraubte Kompass","Malrec tauchte aus einem Rauchboden auf und ergriff den Kompass. Seine goldene Nadel drehte sich auf den Thron zu und zog ihn von seinem Fluchtweg ab.","Ivan verfolgte fast allein, aber Mila hielt ihn an der zerbrochenen Treppe auf. Daria erkannte unten eine Servicebrücke und führte die Gruppe herum. Sie haben den Kompass aus Malrecs verlassenem Laternenkäfig gefunden. Der Gesandte hatte erfahren, dass der Kompass nicht einem Träger dienen würde, der nur Besitz suchte. Furios brach er den Käfig und floh zu seinem Meister, um eine andere Waffe zu holen.\n\nMila: „Wir können es gemeinsam wiederherstellen. Verwandelt die Dringlichkeit nicht in Einsamkeit“"},
new string[] {"Der eigene Kampf der jungen Frau","Mila fand den Laternengewölbe des Ofens, wo gebrochene Regenhüterkristalle eine Mauer aus rotem Feuer füttern. Ivan bot an, den Eingang zu bewachen, während sie wählte, wie sie sie befreien.","Mit Darias Hilfe änderte Mila die Ausrichtung der Kristalle, anstatt ihre eigene Stärke in die Wand zu gießen. Das Feuer erweichte sich in blaues Licht. Sie holte die alte Linse ihrer Lehrerin zurück und passte sie an ihre Laterne an. Die Verbesserung machte sie nicht unbesiegbar, aber es gab ihr mehr Kontrolle. Ivan bewunderte das Können hinter dem Wunder mehr als das Schauspiel selbst.\n\nMila: „Halten Sie die Tür. Dieser Teil ist mein zu lösen“"},
new string[] {"Die Halle der geborgten Gesichter","Varkul füllte den nächsten Saal mit Kopien von Menschen aus Ivans Vergangenheit. Jeder verlangte eine andere Rettung und zerstreute seine Aufmerksamkeit, bis er sich kaum bewegen konnte.","Mila weigerte sich, den wahren Weg zu identifizieren, indem sie erraten, welche Stimme am aufrichtigsten klang. Sie und Daria verfolgten die magischen Schutzkanäle des Bodens, während Boris jede Tür testete. Ivan folgte der Arbeit, die sie überprüfen konnten. Die kopierten Gesichter verblassten, als der versteckte Motor getrennt wurde. Ein wahres Signal blieb: Veras Bericht, dass das alte Moskau noch stand, und die reparierten Brunnen hatten begonnen zu leuchten.\n\nIvan: „Die Stadt ist immer noch da. Wir beantworten die wirkliche Botschaft“"},
new string[] {"Malrecs letzte Laterne","Der Gesandte wartete am inneren Tor mit einer Laterne, die aus der Zitadelle geschnitzt wurde. Er zog jeden Funken in den Korridor zu Ivans Rüstung.","Der General legte sein Schwert beiseite und benutzte einen Arbeiterhaken, um die Kette zu zermalmen. Jaroslav schlug das Scharnier der Laterne; Mila kühlte seinen Kern ab. Malrec versuchte, durch Rauch zu entkommen, aber die Erdkette versiegelte seinen Durchgang. Seine Schwarzsteinform zerbröckelte in harmlose Asche, als Boris die leere Laterne brach. Sie verließen den Korridor für die Rückkehr intakt, anstatt den Sieg in seine Mauern zu brennen.\n\nYaroslav: „Das Scharnier, Ivan. Lassen Sie das helle Zentrum in Ruhe“"},
new string[] {"Die Schwelle des Herzens","Hinter dem inneren Tor schwebte das Herz innerhalb des Kronenmotors. Sein goldenes Licht flimmerte um rote Ketten, und Ivan erkannte den Rhythmus aus der Stadtkammer.","Die fünf Reisenden überprüften ihren Plan noch einmal: Regentor antworten, Seil gesichert, alternative Passage markiert. Mila würde die Wasserverriegelung betreiben, weil ihre restaurierte Linse sie kontrollieren konnte; Boris würde sie festigen, Daria das Tor koordinieren und Yaroslav den Ausgang schützen. Ivan würde Varkul konfrontieren. Mila bat ihn, sie anzuschauen, bevor er auf den Thron schaute, und das tat er.\n\nMila: „Erinnerst du dich an den Ausweg, auch wenn du siehst, wofür du gekommen bist“"},
new string[] {"Der Herr, der sich Morgenröte nannte","Varkul stieg vom leeren Thron ab, einer aufragenden humanoiden Figur aus geknacktem Obsidian, eingewickelt in emberrote Roben. Er behauptete, dass gestohlenes Licht ihn zur rechtmäßigen Morgendämmerung der Stadt machte.","Ivan fragte, warum eine Morgendämmerung Gefangene, gebrochene Brunnen und Dunkelheit benötigte, um zu überleben. Der Dämon antwortete, indem er die Ketten des Kronenmotors hob. Mila hielt die Wasserverriegelung offen; Daria nannte die Pulsintervalle. Ivan rückte mit seiner gewöhnlichen Stahlklinge vor. Die Schlacht begann um eine Maschine, die verstanden, unterbrochen und demontiert werden konnte.\n\nIvan: „Licht, das unsere Dunkelheit braucht, hat keinen Anspruch, uns zu regieren“"},
new string[] {"Eine Krone aus fremden Leben","Varkuls Krone schöpfte Stärke aus den auf den gestohlenen magischen Schutzkanälen geschnitzten Namen. Jeder Schlag, den Ivan schlug, kehrte als Hitze durch den Boden zurück.","Daria erkannte die Reservoir-Symbole und sagte ihm, er solle aufhören, die Krone direkt anzugreifen. Mila öffnete einen blauen Kanal für die freigegebenen Namenstafeln; Boris schnitt den nächsten Kanal. Die Krone verlor eines ihrer Lichter. Ivan änderte seinen Ansatz und kämpfte, um die Verbindungen aufzudecken, anstatt den Dämon zu überwältigen. Varkul kehrte beim ersten, was er nicht ersetzen konnte zurück: eine gefangene Quelle, die frei wird.\n\nDaria: „Beenden Sie die Verbindung. Füttere die Krone nicht noch einen Schlag“"},
new string[] {"Der vierteilige Plan","Die Schlacht erstreckte sich über vier Galerien. Yaroslav hielt den Ausgang gegen Rußwächter; Boris verstärkte die Verriegelung; Daria signalisierte Lada am äußeren Tor; Mila kontrollierte den Wasserdruck.","Ivan konnte keinen von ihnen durch die steigende Hitze deutlich sehen, also vertraute er den vereinbarten Signalen. Als eine Galerie knackte, rief Daria eine Pause an, anstatt die Verzögerung zu verbergen. Ivan zog Varkul lange genug weg, um ihn zu stabilisieren. Der Plan funktionierte, weil es allen erlaubt war, Misserfolge zu melden, solange noch Zeit blieb, darauf zu reagieren.\n\nDaria: „Dauern Sie die Freigabe. Die westliche Unterstützung bewegt sich“"},
new string[] {"Das Angebot einer lebendigen Stadt","Varkul zeigte Ivan eine Vision des alten Moskau wiederhergestellt, mit Mila neben ihm unter einem klaren Himmel. Er bot es im Austausch für die Namen aus dem Reservoir: Fremde, deren Häuser für immer dunkel bleiben würden.","Ivan spürte die Grausamkeit einer Wahl, die genau wie sein Wunsch geformt war. Er weigerte sich, für die Menschen zu sprechen, die gehandelt werden. Mila schloss die Vision mit einem Strom aus ihrer Laterne. Das Angebot des Dämons scheiterte, weil seine Liebe Raum für eine Zukunft geschaffen hatte, aber ihm nie das Eigentum von jemand anderem gegeben hatte.\n\nIvan: „Ich kann unser Haus nicht mit jemand anderem kaufen“"},
new string[] {"Die Klinge aus gewöhnlichem Eisen","Varkul zerschmetterte Ivans Schwert bei der Wache. Boris warf ihm die unfertige Klinge aus der Schmiede, jetzt mit einem einfachen Holzgriff ausgestattet.","Es hielt kein gestohlenes Licht. Ivan benutzte es, um die Wartungsplatte des Kronenmotors zu öffnen, während Yaroslav seine Annäherung deckte. Daria nannte die exponierten Schlösser in Folge. Der Dämon schlug wild, als seine Stärke zu einer Reihe von verwundbaren Teilen wurde. Ivans letzte Waffe war wichtig, weil sie eine einfache Aufgabe zuverlässig erledigen konnte, nicht weil eine Prophezeiung ihren Träger genannt hatte.\n\nBoris: „Es ist Eisen. Lass es die Arbeit machen“"},
new string[] {"Der Riegel gibt nicht nach","Die ersten drei Kronenschlösser öffneten sich. Der vierte blieb zu einem beschädigten magischen Schutzkanal unter Varkuls Thron verschmolzen.","Mila warnte davor, dass es eine Welle in die gebrochenen Fundamente des Regentors schicken würde. Boris und Daria schlugen vor, es schrittweise abzukühlen, während Lada die äußere Seite stärkte. Ivan hielt Varkul von der Verriegelung fern und zählte die Signale. Sie gewannen Zeit auf Kosten der Erschöpfung, vermieden aber eine blinde Befreiung. Unter dem Thron begann sich eine unsichtbare rote Ader schneller zu erwärmen, als ihre Diagramme vorausgesagt hatten.\n\nMila: „Es ist noch nicht fertig. Geben Sie dem Tor Zeit zu antworten“"},
new string[] {"Eine Stimme aus dem Alten Moskau","Veras Signal erreichte die Kammer durch die fast restaurierten magischen Schutzkanäle. Sie berichtete, dass die Bürger die Steckdose des Herzens geräumt und die Schutzräume mit ihren Kanälen verbunden hatten.","Die Stadt bereitete sich darauf vor, das zu empfangen, was die Gefährten hofften, zurückzukehren. Ivan hörte bekannte Stimmen unter dem Knistern: der Töpfer Anya, befreite Arbeiter und Menschen von der Straße. Varkul versuchte, sie im Donner vom Motor zu ertränken, aber Mila verstärkte das Signal. Ihre Arbeit war zu einem Kreis von Menschen geworden, die einander über die Distanz halfen, ohne dass ein einzelner Held seine ganze Kraft hielt.\n\nVera: „Die Kammer ist fertig. Die Stadt arbeitet mit Ihnen zusammen“"},
new string[] {"Die Krone fällt","Ladas Signal bestätigte die erste Verstärkung des Regentors. Daria löste das letzte Kronschloss, und Boris trennte die Thronleitung.","Varkuls Krone zerbrach in stumpfe Eisensegmente. Das Herz stieg aus dem Rahmen heraus, immer noch durch das innere Ascheriegel gehalten. Ivan traf den Dämon auf der unteren Treppe und trieb ihn von der restlichen Energiequelle weg. Zum ersten Mal warf Varkul einen gewöhnlichen Schatten. Er war noch gefährlich, aber nicht mehr weit mit Licht von anderen genommen.\n\nIvan: „In der Krone, die dir gehört, ist nichts mehr übrig“"},
new string[] {"Varkuls Niederlage","Varkul versuchte, sich durch den gebrochenen Thron wieder mit dem Herzen zu verbinden. Ivan zwang ihn auf die Wartungsbrücke, während Mila den letzten lebenden Kanal versiegelte.","Yaroslav schnitt die Brücke an Darias Signal, ließ ihren leeren Abschnitt fallen und löste den Rückzug des Dämons. Ivan schlug den entblößten Kern in Varkuls Brust mit der einfachen Eisenklinge. Die gestohlene Flamme ging aus. Varkul brach in kalte Fragmente ein, und der Ofen schwieg. Ivan hatte den Anführer des Dämons besiegt, aber das Herz hatte noch nicht die Schwelle überschritten.\n\nIvan: „Das Licht der Stadt geht nach Hause“"},
new string[] {"Das Herz in Menschenhänden","Das innere Ascheriegel öffnete sich, als Mila seinen letzten Wasserkanal ausbalancierte. Ivan hob das Herz aus seiner Wiege.","Seine Wärme war sanft, im Gegensatz zur Hitze des Ofens, und sein Licht zeigte jedes erschöpfte Gesicht deutlich. Boris überprüfte die Zahnspange; Yaroslav begann sich zum markierten Ausgang zu bewegen. Daria wartete auf die Freigabebestätigung des äußeren Tors. Ivan sagte Mila, das Herz sei frei und griff nach ihrer Hand. Die geplante Seil-unterstützte Freigabe hätte folgen sollen. Stattdessen brach die rote Ader unter dem toten Thron durch den Boden.\n\nIvan: „Wir haben es. Jetzt bringen wir uns alle heraus“"},
new string[] {"Der letzte Befehl der Esse","Varkuls Tod löste einen verdeckten Zusammenbruchsmechanismus jenseits des kartierten Ascheriegel aus. Das äußere Regentor verlor seine zweite Stütze; das Lösungsseil brannte durch, bevor Mila den Riegel loslassen konnte.","Sie meldete den Misserfolg sofort. Boris versuchte, das Seil zu ersetzen, während Daria nach einer anderen Kontrolle suchte. Ivan setzte das Herz auf eine stabile Kante und kehrte nach Mila zurück. Der Motor fing an, Hitze in Richtung der Stadt zu ziehen, und eine rote Welle überquerte die weite Galerie. Ihr Feind war weg. Seine Maschine verlangte immer noch eine Antwort.\n\nMila: „Das Seil ist weg. Der Riegel hält den Stoß zurück“"},
new string[] {"Die Entscheidung am kaputten Riegel","Ivan und Boris versuchten, den Riegel mit der Ersatzgarnitur zu verstopfen. Die verborgene Wärmeader erweichte das Eisen, bevor es Platz nehmen konnte.","Daria fand einen schmalen Durchgang zur Schwelle, aber keine zweite Kontrolle. Mila verstand das Timing: Wenn das Herz die Schwelle überquerte, während der Riegel gehalten blieb, würde die Welle in den Berg anstatt in die Stadt ablenken. Sie bat die anderen, weiterhin eine Freilassung zu suchen, während Ivan das Herz ausführte. Ivan weigerte sich, sie zu verlassen, ohne die verbleibende Passage zuerst zu versuchen. Sie arbeiteten immer noch für fünf Überlebende.\n\nMila: „Suche weiter. Tragen Sie es nur, wenn ich das Signal gebe“"},
new string[] {"Der Weg, der sich schloss","Yaroslav überquerte den schmalen Gang, um sein weites Ende zu sichern. Eine fallende Platte versiegelte die Rückseite und zerschmetterte die Stütze unter Ivans Füßen.","Mila lenkte den Wasserkanal um und fing die Platte lange genug, damit Boris ihn klar ziehen konnte. Der Aufwand knackte ihre Laternenlinse. Daria versuchte Lada zu signalisieren, aber das zusammenbrechende Tor antwortete nur in gebrochenen Impulsen. Ivan konnte nun das Herz und die Schwelle erreichen; er konnte den Riegel von außen nicht erreichen. Mila bat ihn, die Fakten zu hören, bevor er entschied, was Hoffnung noch erlaubt.\n\nMila: „Höre auf das, was sich geändert hat. Dann wähle mit mir“"},
new string[] {"Der letzte Rettungsversuch","Boris baute einen Steinkeil aus den Treppenstufen; Daria synchronisierte ihn mit den restlichen Impulsen des äußeren Tors. Für einen Moment hielt der Riegel ohne Milas Hände.","Ivan erreichte sie, und sie machten einen Schritt zusammen. Dann spaltete die verborgene Vene den Keil und schickte eine rote Lanze auf seine Brust. Mila zog ihn hinter den Steinschild des Riegels. Sie wurde von der Gegenreaktion durch ihre Laterne getroffen, nicht von seiner Wahl, sie zu verlassen. Der Schaden konnte nicht mehr rückgängig gemacht werden. Sie blieb bei Bewusstsein und bat ihn, sich zu bewegen, während der Schild noch hielt.\n\nIvan: „Einen Weg noch. Es muss noch einen Weg geben“"},
new string[] {"Die junge Frau hält den Regen","Mila setzte ihre zerbrochene Laterne in den Riegel und schuf einen letzten stabilen Kanal. Sie wusste, dass er ihre Kräfte überdauern würde, doch nur lange genug, damit Ivan mit dem Herzen hinübergelangen konnte.","Sie sagte ihm, ihr erhofftes Zuhause sei wirklich gewesen, weil sie sich dafür entschieden hatten, auch wenn sie seine Räume nie teilen würden. Ivan kniete neben ihr und legte die beiden Hälften ihres Andenkens zusammen. Sie bat ihn, das große Fenster zu bewahren, jemandem das Laternenhandwerk beizubringen und weiterzuleben. Unter Tränen versprach er es, dann hob er das Herz auf.\n\nMila: „Trag das Licht hinaus. Lebe weiter dort, wo es dich erreichen kann.“"},
new string[] {"Jenseits der Schwelle","Ivan überquerte die Schwelle, als Mila den letzten Anstieg in den Berg freisetzte. Yaroslav und Boris zogen ihn hinter die Schutzmauer; Daria versiegelte den Gang, bevor die rote Welle folgen konnte.","Das Herz hat sich gefestigt. Durch eine schmale Öffnung sah Ivan Mila jenseits des fallenden Staubes, noch neben dem blauen Kanal, den sie gemacht hatte. Die Hitze ging vorüber und der Motor wurde wieder steinig. Die Begleiter öffneten den kleinsten sicheren Weg sofort wieder. Ivan ging ohne das Herz zurück und ließ es in die bewachten Hände seiner Freunde.\n\nIvan: „Beschütze das Herz. Ich gehe zu ihr zurück“"},
new string[] {"Die Stille nach ihrem Namen","Sie fanden Mila in der abgekühlten Kammer. Ivan hielt sie im Arm, während das letzte blaue Licht aus der zerbrochenen Laterne wich.","Sie hörte ihn ihren Namen sagen und antwortete mit seinem. Ihre letzten Worte waren schlicht: Sie war froh, dass sie sich auf dem Weg begegnet waren. Dann starb sie. Kein verborgener Handel brachte sie zurück; kein Kuss machte den Verlust ungeschehen. Boris wickelte sie behutsam in ein sauberes Tuch, und gemeinsam trugen die Gefährten sie hinaus. Sie hatten das Herz gerettet und Varkul besiegt. Dieser Preis war kein Liebesbeweis, und sie nannten ihn nicht gerecht.\n\nMila: „Ich bin froh, dass du es warst, dem ich auf dem Weg begegnet bin.“"},
new string[] {"Die Last, die vier gemeinsam tragen","Außerhalb des Ofens konnte Ivan das Herz und Milas eingewickelten Körper nicht allein heben. Yaroslav nahm das Herz; Boris und Daria bildeten einen Tragerahmen für ihren Freund.","Als Ivan versuchte, Befehle zu erteilen, scheiterte seine Stimme. Daria sagte ihm die nächsten Schritte deutlich: Ruhe, Wasser, dann das äußere Tor. Die anderen nahmen das Werk an, ohne ihn zu bitten, ein Symbol des Ausharrens zu werden. Hinter ihnen verblasste das rote Leuchten des Ofens. Vor ihm blieb die Straße, die sie repariert hatten, bereit, sowohl das gerettete Licht als auch die Person zu tragen, die sie verloren hatten.\n\nDaria: „Du musst nicht jeden Teil davon tragen“"},
new string[] {"Lada am Regentor","Lada traf die Gefährten neben dem beschädigten äußeren Tor. Sie hatte die erhaltenen Kanäle mit den frei gewordenen Handwerkern repariert, war aber nicht in der Lage gewesen, die zusammengebrochene Unterstützung rechtzeitig wiederherzustellen.","Als sie die zerbrochene Laterne sah, verstand sie, bevor Ivan sprechen konnte. Sie gab dem Lehrling, der sie gerettet hatte, nicht die Schuld, noch entschuldigte sie die Maschine, die die Wahl gezwungen hatte. Zusammen nahmen sie auf, was gescheitert war, so dass keine zukünftige Station von einer Person abhängen würde, die einen tödlichen Riegel hält. Dann setzte Lada Milas silberner Kreis neben die eingewickelte Laterne.\n\nLada: „Wir werden uns an sie erinnern, und wir werden das ändern, was ihr fehlgeschlagen ist“"},
new string[] {"Die Heimkehr durch lebendige Orte","Die Arbeiter der Zitadelle öffneten ihre Tore für die Reisenden. Im versunkenen Viertel bot Anya saubere Decken an; in Glaswald schützten die restaurierten Bäume den Tragerahmen.","Ivan erkannte jeden Ort, den sie angehalten hatten, um zu helfen, und half ihnen jetzt im Gegenzug. Er erzählte denjenigen, die fragten, dass Mila eine Handwerkerin, Führerin, Lehrerlehrling und jemand war, der über seinen Tanz lachte. Er weigerte sich, sie erst in dem Moment werden zu lassen, in dem sie starb. Ihre Geschichte gehörte zu dem Leben, das sie entlang der Straße gelebt hatte.\n\nIvan: „Denkt daran, was sie ermöglicht hat, während sie hier war“"},
new string[] {"Die Hügel vor der Stadt","Auf den Hügeln über dem alten Moskau wählte Ivan einen geschützten Ort in der Nähe der Quelle, um Mila zur Ruhe zu legen. Lada und die drei Freunde standen bei ihm.","Er pflanzte keinen magischen Samen und erwartete keine Rückkehr von der Erde. Er ließ die Hälfte des Holzfensters neben sich und hielt das andere unter seinem Mantel. Unter ihnen brannte die Stadt immer noch entlang ihrer äußeren Gassen. Veras Signal hat vom Gate aus angerufen. Ivan stand auf, als er konnte, und die Gefährten weiter mit dem Herzen in Richtung der Kammer warten unter dem Platz.\n\nIvan: „Ich werde mich an dich in dem Leben erinnern, das ich noch habe“"},
new string[] {"Das Tor öffnet sich wieder","Das überlebende westliche Tor des alten Moskau öffnete sich, bevor der General es erreichte. Vera hatte die Schutzräume intakt gehalten, und die reparierten Brunnen lieferten die letzten Feuerbrüche.","Die Bürger säumten die geräumte Straße ohne zu jubeln. Sie sahen die Erschöpfung der vier Freunde, die zerbrochene Laterne und das goldene Herz, das sorgfältig zwischen ihnen getragen wurde. Ivan gab der Stadtuhr einen vollständigen Bericht: Der Dämon wurde besiegt, das Herz erholte sich und Mila war tot. Vera hörte zu und gab dann dem Kammerwerk frische Hände. Die Rückkehr bedeutete nicht, dass die Aufgabe erledigt war.\n\nVera: „Wir haben die Straße gehalten. Lassen Sie uns den nächsten Teil tragen“"},
new string[] {"Die Stadt schafft Raum für Licht","Der Platz blieb überfüllt mit Unterschlupf und gerettetem Holz. Vor der Wiederherstellung des Herzens half Ivan Vera, Familien von der instabilen Decke der Kammer zu entfernen.","Boris überprüfte die Reparaturen; Daria passte die neuen Kanäle zu ihrer Rückkehrkarte an. Lada platzierte Milas überlebende Linse in die Signalnische, wo sie Licht verteilen konnte, ohne gefährliche Hitze zu tragen. Orel, schwach aber lebendig, erkannte die reparierten Routen, die über die Stadt hinausreichten. Das Herz würde zu einem breiteren Netzwerk zurückkehren als das, aus dem es gestohlen worden war.\n\nOrel: „Sie haben sowohl die Straßen als auch das Licht zurückgebracht“"},
new string[] {"Das Herz findet seinen Platz","Ivan stieg mit dem Herzen in seinen Händen herab. Die Steckdose unterhalb des Platzes wurde mit Anya's Station-Clay, Dorfholzspangen und Stein von befreiten Arbeitern geformt umgebaut.","Nichts davon war unberührt; alles daran war bereit. Milas gebrochene Laterne ruhte in der Nähe als Erinnerung, nicht als Mechanismus, der ein anderes Leben erfordert. Ivan setzte das Herz in seine ursprüngliche Mitte. Für einen langen Atemzug blieb die Kammer dunkel. Dann füllte Goldlicht den reparierten Ring und bewegte sich nach außen durch jeden Kanal, den sie vollständig gemacht hatten.\n\nIvan: „Für die Leute hier und für die unterwegs“"},
new string[] {"Blitze über den Türmen","Der wiederhergestellte Puls des Herzens erreichte das Regentor durch die angeschlossenen magischen Schutzkanäle. Ein weißer Blitzschlag überquerte den schwarzen Himmel über dem alten Moskau, erleuchtete jedes verbrannte Dach und baute den Bogen wieder auf.","Die Bürger schlugen zu, dann hörte sie die tiefe Antwort des Donners. Ivan kletterte auf den Platz, als die ersten kalten Tropfen die Steine schlugen. Daria überprüfte die Abflüsse; Vera bewegte Menschen unter stabile Deckung. Das lang erwartete Wunder kam mit Arbeit zu tun, und die Stadt war bereit, es zu empfangen, ohne Wunder als Ersatz für Pflege zu behandeln.\n\nDaria: „Öffnet die Abflüsse. Der Sturm ist real“"},
new string[] {"Der Regen, der das Feuer löschte","Der Regen fiel in Strömen. Flammen zischten entlang der Holzdächer, dann in Dampf gefaltet.","Der rote Glanz in den Brunnen verschwand und ließ das Wasser klar genug, um die Laternen zu reflektieren. Ivan stand unter dem Regen, bis Yaroslav einen Mantel über seine Schultern legte. Um sie herum umarmten die Bürger, trugen Wasser zu versteckten Gluten und nannten die Namen der noch vermissten Menschen. Die Stadt war vor dem Feuer gerettet worden. Es war nicht jeden Verlust verschont worden. Beide Wahrheiten gehörten unter dem gleichen zurückkehrenden Himmel.\n\nYaroslav: „Kommt unter den Mantel. Du darfst kalt sein“"},
new string[] {"Der erste Morgen","Am Morgen wurde der Regen zu Silberfäden dünn. Sonnenlicht erreichte den zentralen Platz durch zerrissene Wolken, berühren nassen Stein, geflickte Wände und erschöpfte Gesichter.","Orel kündigte an, dass der Herzrhythmus stabil sei. Ivan sah die Stadt aufwachen, ohne Freude zu erwarten, seine Trauer zu ersetzen. Milas Abwesenheit blieb neben der Schönheit, die sie zurückgewonnen hatte. Er nahm seine Hälfte des hölzernen Fensterrahmens heraus und hielt es im Licht. Dann schloss er sich Boris in einem beschädigten Haus an, wo noch ein echtes Fenster gebaut werden musste.\n\nIvan: „Der Morgen ist da. Lasst uns dafür Raum schaffen“"},
new string[] {"Hirschmargeriten auf den Hügeln","Wenige Tage später öffneten sich auf den Hügeln über dem Alten Moskau weiße Hirschmargeriten. Es waren die Blumen, die die Dorfbewohner schon immer so genannt hatten: weiße Blütenblätter, goldene Mitten und schmale, silbergrüne Blätter.","Noch glänzten Regentropfen an ihren Stängeln. Ivan ging mit Lada und den drei Freunden zu Milas Ruhestätte. Er brachte einen kleinen Blumenstrauß mit und erzählte vom reparierten Fenster, von den Kindern, die das Laternenhandwerk lernten, und vom Regen, der endlich gekommen war. Er erzählte ihr vom Leben, denn dieses Versprechen konnte er noch halten.\n\nIvan: „Sie sind aufgeblüht. Ich wünschte, du könntest sie sehen.“"},
new string[] {"Die Schule der offenen Laternen","Lada eröffnete eine Laternenwerkstatt in einem reparierten Haus nahe dem Platz. Seine erste Regel wurde über die Bank geschrieben: keine Station sollte eine gefangene Hand erfordern.","Daria half dabei, sichere Freisetzungen und Ausfallsignale zu dokumentieren. Boris lehrte die Schüler, Schallgehäuse zu bauen, bevor sie auf helle Kristalle vertrauten. Ivan besuchte die erste Lektion als Anfänger und kämpfte mit einem zarten Verschluss. Als die Schüler lachten, lachte er mit ihnen. Mila's Handwerk setzte sich durch Unterricht statt durch eine Behauptung, dass sie zurückgekehrt war. Ihr Name gehörte neben dem Werk, nicht über die Forderung nach Opfer.\n\nLada: „Baue die Veröffentlichung, bevor du das Licht baust“"},
new string[] {"Der General und die unfertige Stadt","Ivan hielt sein Kommando, änderte aber seine Arbeit. Die Uhr reparierte Straßen, trainierte Rettungsteams und schützte die mit dem Herzen verbundenen Siedlungen.","Yaroslavs Bein heilte langsam; er lehrte jüngere Kapitäne, Verletzungen ohne Scham zu melden. Boris beaufsichtigte die neuen Stiftungen, und Daria veröffentlichte eine Karte, die die Dörfer einst weggelassen. Ivan baute das Hangfenster, das er versprochen hatte, und ließ den Raum für Reisende zur Verfügung stehen. Er nannte es nicht das Haus, das er und Mila geteilt hätten. Es war ein lebendiger Ort, der durch die Erinnerung an sie möglich wurde.\n\nIvan: „Die Stadt ist sicher genug, um wieder aufzubauen. Das ist unsere nächste Pflicht“"},
new string[] {"Die Legende vom heimkehrenden Regen","Jahre später erzählten die Menschen, wie ein General aus einem Dorf und seine drei Freunde dem gestohlenen Herzen in die Dunkelheit gefolgt waren. Sie erzählten von Mila, die den Weg gangbar gemacht, aus freien Stücken geliebt und Ivan gerettet hatte, als die Esse ihren Fluchtweg zerstörte.","Ivan fügte stets die Namen der Lehrer, Arbeiter, Flüchtlinge und Nachbarn hinzu, die die Reise gemeinsam getragen hatten. Als der erste Frühlingssturm die Hügel erreichte, öffnete er das große Fenster. Auf den Regen folgte Sonnenlicht, und die Hirschmargeriten leuchteten über dem Alten Moskau. Die Legende endete mit einer Stadt, die weiterlebte, und einer Liebe, die in Erinnerung blieb, ohne den Verlust rückgängig zu machen.\n\nIvan: „Erzählt auch von ihrem Leben. Erzählt von all den Händen, die das Licht nach Hause gebracht haben.“"},
},
new string[][] { // ru
new string[] {"Сельский колодец","В деревне Зареч, где над серебристой рекой росли белые оленьи ромашки, Иван научился чинить крыши раньше, чем носить меч. Годы спустя он вернулся туда генералом городской стражи Древней Москвы.","Жители деревни приветствовали военачальника, но его давняя подруга Дарья спросила, помнит ли он ещё их имена. В ответ Иван помог починить деревенский колодец. В тот вечер прибыл посланник: священное Сердце города начало биться неровно. Иван оставил парадное знамя и взял дорожный плащ.\n\nИван: «Город — это люди, которым жить с последствиями наших решений»."},
new string[] {"Зал под площадью","Под центральным квадратом Иван вошел в комнату, построенную вокруг светящегося камня: Сердца древнего Москвы. Свет его шел по зарытым каналам в колодцы, сады и защитные комнаты.","Хранитель Орел показал ему трещину на внешнем ринге. Кто-то накормил Сердце шёпотом недоверия, изменяя страх города против его обороны. Иван приказал запечатать помещение, а городские охранники обыскали каналы. Поверх них, фонари фестиваля сияли, хотя по улицам ветер не двигался.\n\nОрел: «Он охраняет нас только тогда, когда доходит до нас свет»"},
new string[] {"Дверь из дыма","Украденные шепотки открыли узкий проход через стену камеры. Сквозь него прошла фигура черного камня, с железным фонарем, наполненным красным дымом.","Он был Малреком, посланником Варкула, лордом Холлоу Печи. Иван ударил фонарь, но его дым разделился на три тени и поскользнулся вокруг него. Орел вытащил генерала, когда внешнее кольцо разбилось. Малрек поднял Сердце, не трогая его. В один ужасный момент каждый фонарь в Древней Москве бросил тень на небо.\n\nМалрек: «Твой страх открыл нам дверь»"},
new string[] {"Ночь падающих углей","Когда Сердце исчезло, погребенные каналы перевернулись. Эмберы лопнули из пустых источников; тьма скопилась между домами, и пламя поднялось на крыши древесины.","Иван не мог преследовать Малрека, пока люди были в ловушке под разрушенной дорожкой. Он приказал городским стражам разжечь пожары и доставить ребенка на площадь. Из западного хребта наступил звук трёх железных колоколов, хотя там не стояла ни одна башня. Орел узнал сигнал Холлоу-Форнаса. Сердце передвигалось за пределы города.\n\nИван: «Откройте полосы. Никто не останется позади»"},
new string[] {"Трое, что не остались","Ярослав, старший капитан Ивана, организовал оставшиеся часы. Борис, деревенский каменщик и кузнец, укрепил приюты.","Дарья нарисовала движение огня и нашла след, где тьма текла на запад. Все трое предложили присоединиться к Ивану. Сначала он отказался: генерал не должен опустошать защиту своего города для личного преследования. Ярослав передал командование капитану Вере, который уже обеспечил безопасность убежищ. Вместе они согласились на спасательную миссию с четырьмя путешественниками и городом, который все еще может защитить себя.\n\nДарья: «Возьми нас, потому что мы можем помочь, а не потому, что мы твои друзья»"},
new string[] {"Последний свет хранителя","Орел выжил в разбитой камере, но отъезд Сердца приглушил волшебный защитный камень, который он носил. Он дал Ивану оставшуюся искру внутри кристаллического компаса.","Компас указал на Сердце всякий раз, когда его носитель вспоминал того, кого он хотел защитить. Он не мог отличить дорогу от стены, и он не обещал победы. Орел предупредил, что Варкул хочет больше, чем горящий город: он хотел, чтобы выжившие поверили, что для каждой спасения требуется новая жертва. Иван принял компас и отклонил эту сделку.\n\nИван: «Тогда мы должны принести больше, чем камень»"},
new string[] {"Ворота, что ещё держались","У западных ворот городские охранники умоляли Ивана взять большую силу. За стенами, однако, широкая армия привлекла бы внимание Печи и оставила бы приюты открытыми.","Иван выбрал узкую дорогу. Перед отъездом он приказал Вере укрыть семьи вместе, держать колодцы прикрытыми и записывать всех пропавших без вести. Четверо путешественников подошло к выжившей арке. За ними рядовые жители подняли защитный барьер от падения искр. Иван однажды оглянулся назад, понимая, что сопротивление города уже началось.\n\nВера: «Принеси рассвет. Мы пристанищем для него»"},
new string[] {"Дорога пепла","Эш стер дорожную разметку возле Древней Москвы. Дарья восстановила свое направление от дренажных отрубов под пылью; Борис положил плоские камни через горячую землю.","На закате они обнаружили беженцев, скрывшихся в без крыши часовне. Компас отошел на запад, от оказавшихся в беде семей, но Иван остановился. Ярослав раздавал им запасную еду, а остальные расчистили путь к городскому приюту. Задержка стоила им дневного света. Она также доказала, что миссия генерала не позволит превратить людей, которым она служит, в препятствия.\n\nЯрослав: «Спасенное Сердце мало значит для пустого города»"},
new string[] {"Не сгоревшая лента","На краю поля пепла с черным столбом висела узкая лента индиго. В отличие от всего вокруг, ткань оставалась крутой.","Дарья обнаружила похожие следы на близлежащих камнях: кто-то проводил беженцев через безопасные проходы. Иван последовал за знамениями до источника, запечатанного под плитой. Когда Борис сдвинул его, чистая вода поднялась через пепел. Сообщение, поцарапанное на камне, не называлось автором, только предупреждение: западный мост слушал слышенный страх. Иван уложил ленту рядом с компасом.\n\nДарья: «Кто-то шел этой дорогой перед нами и заботился о том, кто пришел после»"},
new string[] {"Мост трёх колоколов","Западный мост стоял над ущельем, наполненным противоестественной тьмой. Три пустых колокола повесили над его центром.","Когда Борис признался, что опасался, что упадет срок, первый звонок и доска исчезли. Иван попросил каждого спутника сообщить о практической опасности и дать практический ответ. Ярослав защитил верёвку, Дарья идентифицировала каменные опоры, а Борис проверил остальные доски. Их честность укрепила мост; паника только накормила его заклинание. С другой стороны, среди разрушенных арок появился женский фонарь.\n\nИван: «Назови опасность. Тогда назови, что мы можем сделать»"},
new string[] {"Фонарь за оврагом","Женщина за мостом не ждала, когда ее спасут. Она опускала веревку к двум незнакомцам, застрявшим на выступе.","Иван присоединился к ней, и вместе они отправили путешественников в безопасное место. Она представила себя Милой, учеником исчезнувших Рейнварденов, и спросила, собирается ли генерал помочь людям или просто победить врага. Иван ответил, дав незнакомцам последние сухие плащи. Мила заметила ленту индиго у его пояса. Она была ее, оставлена, чтобы отметить путь, который пламя не могло проглотить.\n\nМила: «Оставь ленточку. Все еще есть люди, которым нужна дорога»"},
new string[] {"Родник под камнем","Мила привела товарищей в прикрытую спринг-хаус, где жара Фёрнаса не могла войти. Она могла направлять воду по старым волшебным каналам защиты, но не могла ни вызвать дождь, ни восстановить украденное Сердце.","Борис починил сломанный бассейн, пока Мила очистила обожженную руку Ивана. Генерал поблагодарил ее слишком официально, и она рассмеялась на расстоянии, которое он держал за своим титулом. Снаружи Ярослав стоял на страже; внутри Дарья сравнила следы Милы со своей собственной картой. Их отдельные путешествия стали одним путем.\n\nМила: «Можете оставить своё место достаточно долго, чтобы выпить»"},
new string[] {"Карта для двух рук","Карта Дарьи закончилась на ущелье. Воспоминания Милы начались за ее пределами, где движущийся туман прятал дорогу к Холоу-Форнасу.","Один, ни один гид не смог добраться до логова демона. Вместе они наметили маршрут через Стеклянный лес, Затонувший квартал и Цитадель Синдерс. Мила настояла на присоединении к экспедиции, потому что пропавшие Рейнвардены оставили записи по этому пути. Иван принял ее опыт, не обещая ей повиноваться. На рассвете пять путешественников покинули Спрингхаус, связанные скорее общей целью, чем командованием.\n\nДарья: «Твоя память — дорога. Моя карта может дать ему края»"},
new string[] {"Сад без теней","Они вошли в сад из серебряных деревьев, корни которых были очерствены колдовством. Никакого плода не осталось, и каждый ствол бросает одну и ту же тень независимо от света.","Мила обнаружила, что тени удерживали воду под землей. Иван хотел порезать прямой путь, но Борис предупредил, что корни держат склон вместе. Они ослабили заклинание по одному дереву за раз. Когда вода текла, под серебряной коркой появились живые листья. Иван стал рассматривать восстановление как своего рода победу, которую никогда не учили вести.\n\nБорис: «Дорога, которая рухнет позади нас, это не дорога домой»"},
new string[] {"Обещание генерала","Окружил сад сажаный патруль: безмолвные гуманоидальные охранники вырезаны из растресканного черного камня. Ярослав создал линию щита, а Иван сражался на пути к верхушке.","Мила перенаправила источник под охраной, охлаждая их суставы, пока они не заперты. После этого Иван пообещал держать ее подальше от опасности. Мила отказалась от обещания, которое он не мог сдержать. Она просила правду о каждом риске и голосе в каждом решении. Иван согласился, неудобно, как сильно от него требовалась простая честность.\n\nМила: «Не обещай, что я никогда не буду бояться. Обещай, что будешь слушать»"},
new string[] {"Письма в разрушенной башне","Внутри разрушенной сигнальной башни Мила нашла письмо Рейнвардена, запечатанное стеклом. Она описала кражу Варкула менее магическими защитными камнями и его попытку построить корону из одолженного света.","Последняя страница была удалена. Иван обыскал верхний этаж и обнаружил, что сигнал башни все еще может достичь города. Он продиктовал Вере послание: Сердце выжило, и миссия нашла проводника. Мила тихо добавила направление к восстановленной весне. Надежда, они согласились, должна путешествовать с чем-то, что может пригодиться людям.\n\nИван: «Скажи им, где вода. Тогда скажи им, что мы возвращаемся»"},
new string[] {"Стол на пятерых","Дождь не упал, но холодный туман позволил товарищам покоиться под башней. Борис приготовил тонкий ужин в отремонтированном кастрюле.","Ярослав рассказал Миле, как Иван однажды пытался командовать течью крышей и проиграл спор. Впервые после кражи Иван смеялся. Мила говорила о доме на холме, который она надеялась построить, с окном достаточно широким, чтобы увидеть первую весеннюю бурю. Иван описал деревенскую воду. Их желания звучали как обычно, и по этой причине они ценнее любого очарованного сокровища.\n\nМила: «Когда все закончится, я хочу комнату, которая не принадлежит ни одному пророчеству»"},
new string[] {"Цена короткого пути","Ночью появилась новая дорога с нетронутым белым камнем. На входе безликий посланник предложил пройти прямо к сердцу в обмен на хрустальный компас.","Мила подозревала в сделке, но камни дороги были настоящими. Дарья обнаружила, что каждый шаг отошел дальше. Иван отказался от сделки и привел всех к трудному пути. Перед тем, как исчезнуть, курьер показал, что Варкул знал имя Милы. Она надеялась, что ее путешествие останется от него в тайне.\n\nИван: «Обещание, которое двигается при испытании - это всего лишь еще одна ловушка»"},
new string[] {"Недосказанная правда Милы","Мила призналась, что ее учительница вошла в печь и так и не вернулась. Она потратила месяцы, следуя фрагментам записей Рейнварденса, надеясь узнать, что произошло.","Ее фонарь был последним рабочим инструментом этого порядка, и Варкул пытался захватить его раньше. Ивану было больно, что она ждала, чтобы рассказать ему, но он понял, как мало доверия заслуживает одна униформа. Он спросил, что еще может сделать фонарь. Мила ответила правдиво: она еще не знала. Они согласились с тем, что неопределенность будет говориться, а не скрываться.\n\nМила: «Я могу дать тебе то, что знаю. Я не могу дать вам уверенности»"},
new string[] {"Дверь в Стеклянный лес","На входе в Стеклянный лес прозрачные стволы образовали стену вокруг старых ворот. Его замок ответил на компас и фонарь вместе.","Когда Иван и Мила подняли их, врата открылись на лес, отражавший небо, которого не видели. Дарья пометила порог обычным мелом, так что никакое заклинание не могло стереть путь назад. Ярослав ужесточил свои крепежные ремни; Борис нес дополнительные клинья для нестабильной земли. Спутники вошли как команда. За ними впервые заржавели новые листья в саду.\n\nЯрослав: «Отметьте возвращение, прежде чем мы сделаем следующий шаг»"},
new string[] {"Деревья заёмного света","Сундук Стеклянного леса хранил украденный дневной свет. В каждом филиале было по-разному воспоминание о Древней Москве, некоторые из них были правдивы, а другие — изобретены.","Иван видел, как деревня не коснулась огня и чуть не отошла от тропы. Мила проверяла зрение фонариком; оно не отражало воды и не бросало человеческого дыхания на стекло. Они разрушили ложное изображение, не повредив живой корень под ним. Дарья начала помечать достоверными деревьями шнур. Лес будет проходить через наблюдение, а не из-за уверенности в самой яркой сцене.\n\nМила: «Красивый ответ все еще может быть не той дорогой»"},
new string[] {"Второй шанс капитана","Ярослав столкнулся с отражением солдат, которых он не смог спасти несколько лет назад. Стакан предложил ему битву, которую он мог бы выиграть в этот раз, если бы оставил остальных.","Он понизил свой щит и признался Ивану в старом поражению. Генерал не предложил легкого отпущения. Он напомнил своему другу о людях, ждущих на этой дороге. Вместе они ушли от отражения. Ярослав оставил на багажнике полоску синей ткани, маленькое признание того, что память о потерях не должна становиться капитуляцией.\n\nЯрослав: «Я помню их. Я не оставлю за ними живых»"},
new string[] {"Мера каменщика","Светлая лестница пересекла пропасть, но Борис не видел ни одного несущего сустава. Волшебный камень требовал, чтобы путешественники верили в его силу.","Вместо этого Борис построил простую браслет из падших лучей и показал другим, где должна приземлиться каждая нога. Лестница сломалась точно там, где он предсказывал, оставив их крепежную часть нетронутой. Мила помогла охладить отрезанные поверхности, а Дарья измерила оставшуюся часть. Иван поблагодарил Бориса за то, что он не согласился с ним перед переходом. Власть генерала, он учился, должна оставить место для лучшего ответа.\n\nБорис: «Приветствуется вера. Звуковой сустав по-прежнему необходим»"},
new string[] {"Карта того, что осталось","Дарья обнаружила, что Стеклянный лес сместился вокруг желаний, а не шагов. Каждый раз, когда кто-то воображал, что доходит до печи, пункт назначения двигался.","Она нарисовала то, что можно было прикоснуться: колодец, падшая арка, бассейн, который пахнет дождем. Вытекающий из этого маршрут выглядел кривым, но оставался стабильным. Мила добавила следы от путешествия учителя, включая спираль рядом с бассейном. Иван узнал эту спираль из камеры сердца. Впервые исчезновение Рейнварденса и краденый свет города, казалось, принадлежали одному и тому же дизайну.\n\nДарья: «Мы будем картировать то, что останется, а не то, что обещает лес»"},
new string[] {"Водоём невысказанных слов","Спиральный бассейн держал голоса вместо размышлений. Иван услышал надежду Милы на дом, и она услышала его страх, что он вернется как герой в город могил.","Смущенные, они пытались уйти, но вода встала на их пути. Мила предложила сказать слова напрямую, чтобы бассейн больше не обладал ими. Иван признался, что начал заботиться о ней вне миссии. Она сказала, что это чувство взаимно, а затем попросила его позволить ему расти, не сделав клятву, сделанную в осаде.\n\nМила: «Давайте выберем друг друга и при свете дня»"},
new string[] {"Собиратель осколков","Замаскированный лейтенант по имени Серев охранял лесной центр. Он собрал осколки дневного света и предложил продать их людям, у которых они были украдены.","Когда Иван отказался, Серев запечатал след горящим стеклом. Дарья идентифицировал свою линию поставок; Борис сломал ее опоры, а Ярослав защищал остальных. Мила охладила стену, а Иван разбил маску лейтенанта. Серев сбежал через дымовую щель, оставив позади свой магазин дневного света. Спутники выпустили его на деревья, вместо того чтобы брать его в добычу.\n\nИван: «Лицо, взятое из дома, не твоё, чтобы продавать»"},
new string[] {"Поляна настоящих звёзд","Дневной свет открыл расчистку, где можно было увидеть истинное ночное небо. Соседи отдыхали без наблюдателя, который пытался с ними торговаться.","Мила научила Ивану, как ее фонарь измерял влажность в воздухе. Он показал ей простую ткань под доспехами, зашитую его матерью до его первого приказа. Они говорили о людях, которые сделали свою работу возможной. Когда их руки встретились над рукояткой фонаря, они не удалились. Момент был достаточно мал, чтобы принадлежать им одному.\n\nИван: «Я хочу знать тебя, когда никто не нуждается в спасении»"},
new string[] {"Письмо без печати","Рядом с очисткой Мила нашла письмо от своего учителя, Лады. Оно объяснило, что Сердце может быть возвращено только через нерушимую последовательность магических защитных каналов.","Жестокий побег может вернуть камень, но уничтожить дорогу, которая несла его легкий дом. Лада вошла в печь, чтобы найти более безопасный маршрут. Письмо завершилось предупреждением о устройстве под названием Пепельный Затвор. Его цель отсутствовала, но его план был похож на спираль Ивана, который видел под городом. Перед тем, как двигаться дальше, товарищи копировали каждую линию.\n\nМила: «Она искала способ вернуть всех»"},
new string[] {"Поцелуй перед порогом","На дальних воротах Стеклянного леса рассвет появился как тонкая группа вдалеке. Иван предложил Миле возможность вернуться в приют с найденными записями.","Она решила продолжить, а затем задала ему тот же вопрос. Он улыбнулся, когда ему предложили выйти из собственной легенды. Перед тем, как присоединиться к остальным, они поцеловались в тишину. И не называла это судьбой. Они обещали продолжать спрашивать, слушать и давать место будущему, большему, чем эта дорога. Ворота открылись к окраине утопления.\n\nМила: «Я здесь, потому что выбираю быть»"},
new string[] {"Лес возвращает утраченное","Когда пятеро путешественников ушли, стеклянная корка упала с ближайших деревьев. Зеленые ветви появились, не проглотив старых путей.","Дарья послала второй сигнал в сторону Древней Москвы, пометив лес как возможное убежище. Ярослав записал маску лейтенанта и направление его побега. Борис оставил один безобидный осколок для треснувшей рамы компаса. Иван оглянулся назад на восстановленную расчистку и понял, каково это путешествие: каждое отремонтированное место может стать частью дома. Под хребтом из темной воды поднялись испорченные башни.\n\nБорис: «Мы не только находим дорогу. Воистину, Мы используем его»"},
new string[] {"Улицы под тихой водой","Затонувший квартал принадлежал к небольшому поселению на старой торговой дороге. Волшебство затопило его без дождя, удерживая воду над лучами крыши.","Мила могла сделать узкую сухую полосу, но долго не могла ее поддерживать. Дарья обнаружила на своей карте возвышенную лестницу; Борис испытывал подводные ступеньки с помощью столба. Иван заказал короткие переезды и многократные остановки для отдыха, а не героические спешки. Под поверхностью бледные окна передвигались из дома в дом, приглашая их покинуть безопасный путь.\n\nИван: «Мы пересекаемся темпами, которые наш гид может поддерживать»"},
new string[] {"Дом с сухим окном","Одна верхняя комната осталась сухой. Пожилой горшечник по имени Аня запечатал свое окно подопечным и укрыл нескольких соседей внутри.","Они выжили, собирая конденсацию и делясь зерном. Иван помог опустить жителей на дорогу, пока Борис изучал глиняную печать. Мила узнала рецепт Рейнвардена, спрятанный в обычной работе горшечника. Аня дала им сумку глины и попросила запомнить ее цель. Никакое название не защищало комнату; мастерство, терпение и соседи, которые доверяют друг другу, сделали это.\n\nAnya: «Возьми глину. Оставьте знания кому-то, кто в них нуждается»"},
new string[] {"Рынок пустых чашек","На утонувшем рынке чашки зависли над заброшенными кабинками. Каждая чашка предлагала удалить одно болезненное воспоминание, оставив путешественника легче и менее уверенным в том, почему он пришел.","Ярослав почти принял одно из них после того, как услышал голоса своих потерянных солдат. Мила влила в него обычную воду. Чашка треснула, показав дым, спрятанный внутри. Вместе они сломали заклинание рынка и нашли полезные сосуды для беженцев. Иван сохранил свое горе и страх. Он не сдал бы людей внутри них, чтобы облегчить дорогу.\n\nЯрослав: «Боль может обременять меня, не принимая решений»"},
new string[] {"Запись под колоколом","Часовой колокол лежал под водой, лежа на закрытой двери архива. Борис и Ярослав подняли его с помощью рычага, пока Мила держала воду в стороне.","Внутри Дарья нашла доказательства того, что слуги Варкула перенаправили магические каналы защиты квартала на Печь. Наводнения были резервуаром для кражи энергии. Второй рекорд, названный Ладой как заключенный, переведен в Цитадель Синдерс. Надежда Милы росла слишком быстро, и Иван нежно спросил, сколько лет записям. Они несли улики, не притворяясь, что они обещали выживание.\n\nИван: «Мы последуем за записям. Мы не заставим его говорить больше, чем он говорит»"},
new string[] {"Танец на дамбе","В то время, как жители в безопасности за потопом, Аня нажала старую деревенскую мелодию. Дарья запустила свой ритм на пустую чашку, и Борис добавил неровный ритм.","Мила взяла руку Ивана и научила его нескольким шагам по широкой дороге. Он двигался, как командир, пытаясь пройти через танец, что заставляло ее смеяться, пока она почти не забыла про холод. Момент не стирал опасность. Это напомнило им о том, что представляет опасность: простое удовольствие, свободно разделяемое, без врага, который решает свою цену.\n\nМила: «Ты можешь возглавить армию. Я буду вести этот танец»"},
new string[] {"Вода, что поднялась","Малрек вернулся в полночь и перевернул ток квартала. Вода взобралась на стены башни и прижалась к лестнице.","Иван хотел его преследовать, но Мила могла держать только одну полосу сбежаний открытой. Генерал снова решил защитить жителей. Дарья открыла дренажные ворота, а Борис сломал железные зубы, держа его закрытым. Ярослав заблокировал дымовый фонарь Малрека достаточно долго, чтобы все отступили. Посланник сбежал, в ярости, что его приманка провалилась. В осушенном квартале была обнаружена каменная лестница, ведущая под старым водохранилищем.\n\nИван: «Пусть бежит. Держите полосу открытой»"},
new string[] {"Водохранилище имён","Под кварталом на стенах водохранилища были указаны имена людей, чьи волшебные защитные камни были украдены. Писание светилось, когда кто-то вспомнил человека, которого он назвал.","Дарья обнаружила, что с каждой карты опущены деревни. Мила нашла имя Лады, все еще слабо освещенная. Иван заказал полный экземпляр, отказываясь считать незнакомые жизни менее достойными спасения. Компас укрепился, когда он прочитал имена вслух. Свет сердца притягивал не только к его собственному дому; он признавал заботу, обращенную за пределы знакомых улиц.\n\nДарья: «Пропавшее место - это все еще место. Мы вернем его на карту»"},
new string[] {"Чего не исправить фонарю","Мила нашла сломанное жильё фонаря Рейнвардена. Она пыталась починить его, пока не поколебались руки, но его внутренний кристалл был съеден.","Иван сидел рядом с ней и не приказывал ей отдохнуть и не говорил, что у потери была цель. В конце концов, она поставила фрагменты. Она признала, что спасение сердца не может спасти ее учителя. Иван признался, что боялся потерять Милу сейчас, когда он начал представлять себе будущее вместе с ней. Они оставляли обе истины в силе и разделяли молчание, не пытаясь превратить его в мужество.\n\nИван: «Вы не должны делать эту боль полезной»"},
new string[] {"Лестница возвращённого света","Используя подставу Ани, Борис запечатал поврежденные суставы водохранилища. Мила перенаправила свою оставшуюся энергию на пустые каналы в сторону Древней Москвы.","На мгновение компас показал полную дорогу из золота, а затем опустошил на перерыве под Цитадель. Дарья отметила этот разрыв в качестве своей следующей цели. Над ними спасённые жители снова начали открывать сухие комнаты. Спутники оставили инструменты и инструкции, превратив убежище в рабочее поселение. Восстановление сердца потребовало бы такого же труда в большем масштабе.\n\nБорис: «Маджик открывает канал. Кто-то должен починить его стены»"},
new string[] {"Цитадель на красном горизонте","С верхней лестницы путешественники видели Цитадель Синдеров подвешенной над шрамом равнины. Его башни стояли на больших цепях, связанных с печью Холлоу.","Под цитаделью деревенские жители несли камни, чтобы починить стены, которые их похитители продолжали разбивать. Иван изучал охранников, а не рисовал меч. Мила узнала отметку своего учителя на одном тюремном окне. Путь превратился в спасательную миссию, а также в кражу. Вместе они спланировали вход, который оставит выход более чем для пяти человек.\n\nИван: «Мы не войдем, пока не узнаем, как уходят заключенные»"},
new string[] {"Ворота для пленных рабочих","Дарья обнаружила ворота снабжения под западной цепью Цитадели. Работники-похитители проходили через него через определенные промежутки времени, наблюдая за каменными стражами, которые следовали за звуками, а не лицами.","Ярослав создал диверсию с растянутыми щитами, а Борис заглушил луч ворот. Иван и Мила провели первую группу через дренажный проход. Рабочие выбрали представителей для организации своего собственного побега. Генерал дал им свою карту и спросил, какие опасности он упустил. Их знания изменили план до того, как охранники заметили открытие.\n\nИван: «Вы знаете эту тюрьму. Покажите нам, в чем наша хитрость!»"},
new string[] {"Мастерская украденных лет","Внутри Цитадели, банки теплого света висят над мастерской. Каждое из них провело лето, украденное из волшебного защитного камня, оставив свой дом холодным и бесплодным.","Борис нашел каменистую отметку своей деревни на демонтированном канале и понял, как далеко мухи достигли. Мила аккуратно открыла банки, возвращая их свет к ближайшим нетронутым каналам. Иван хотел уничтожить мастерскую, но заключенные могли использовать ее инструменты. Они сломали сафоны, сохранили скамейки и сделали комнату станцией первой медицинской помощи.\n\nБорис: «Что порабощает? Оставь то, что может помочь кому-то жить»"},
new string[] {"Пленница, что ждала дождя","Мила нашла Ладу живой в помеченной камере, ослабленной, но все еще изучающей стены. Их воссоединение началось со слез и стало спором, когда Лада попросила своего ученика уйти.","Мила отказалась позволить страху решать за любого из них. Лада обнаружила, что Сердце было нетронуто в движке Варкула. Пепельный Затвор подключил его к печи: удаление Сердца вызовет обратный всплеск по каждому украденному волшебному каналу защиты. Лада нашла способ отвлечь эту волну, но необходимый внешний якорь остался за пределами цитадели.\n\nЛада: «Я хотел найти решение. Я нашел форму опасности»"},
new string[] {"Командир пепла","Командир Цитадели Рузен заблокировал тюремную лестницу с помощью лезвия, выкованного из захваченного фонаря. Он насмехался над Иваном за то, что он замедлил свою миссию освободить незнакомцев.","Иван ответил в самой битве: Ярослав защищал пленных, в то время как генерал вытащил Рузена из узкого выхода. Дарья выпустила встречный вес, отделив командира от его источника энергии. Борис разбил открытый канал. Оружие Ружана стало обычным железом, и Иван победил его, не сломав лестницу. Заключенные прошли через пространство, которое заявил их похититель.\n\nИван: «Твои пленники не цена моей победы»"},
new string[] {"Двигатель короны","Из галереи, где обслуживалось обслуживание, спутники видели вид на двигатель Фёрнаса. Золотое Сердце зависло внутри железной рамы в форме короны, питая красный свет на дальний трон Варкула.","Четыре якоря держали систему стабильной: цепь Цитадель, корень стеклянной древесины, затонувший водохранилище и внешние дождевые ворота. Они уже восстановили два. Борис мог бы освободить якорь цитадели, не убив рабочих внизу, если бы кто-то сначала заменил его на каменные опоры. Иван опять задержал преследование. Выздоравливаемое сердце, лежащее над разбитыми заключенными, было бы поражением.\n\nДарья: «Двигатель имеет четыре якоря. Мы можем изменить его неудачу»"},
new string[] {"Спор на парапете","Иван попросил Милу сопровождать Ладу и освобожденных заключенных в безопасное место. Она услышала осторожность, но также и возвращение команды, замаскированной под защиту.","Мила напомнила ему об их обещании в саду. Он признал, что из - за любви он чувствовал себя достаточно лично, чтобы затуманить свой рассудок. Она призналась, что иногда скрывала усталость, чтобы казаться незаменимой. Они договорились об общих пределах: никаких скрытых симптомов, никаких личных сделок и никакого решения о жизни другого человека без его голоса. Их любовь стала сильнее, потому что разногласия были разрешены.\n\nМила: «Попроси меня быть в безопасности. Не думай о моём месте»"},
new string[] {"Обещание без пророчества","В тот вечер Иван вырезал маленькую деревянную раму из разбитого ящика. Он дал его Миле в качестве обещания дома на холме, который она описала.","Мила связала ленту индиго через нее, а затем разбила раму на два совпадающих куска, чтобы каждый мог нести половину. Они согласились с тем, что на память ничего не было гарантировано; они были напоминаниями о том, чтобы искать жизнь после миссии. Она поцеловала его под незаконченным парапетом. Над ними не появилась звезда, но ни одна из них не ждала, пока небо одобрит их выбор.\n\nИван: «Окно для первого весеннего шторма. Если мы оба выберем его по-прежнему»"},
new string[] {"Цепь под городом","Борис и освобожденные рабочие вместе построили опоры. Дарья проверила груз, а Ярослав удержал охранников от работы.","Иван подошел к замку главной цепи и нашел Малрека, ожидающего с новым дымовым фонарем. Вместо того чтобы сражаться в одиночку, он позвонил своим товарищам и держал проход до их прибытия. Мила охладила фонарь, Ярослав сломал его своим щитом. Малрек бежал в сторону Печи, лишився самого простого оружия. Рабочие выпустили цепь, и Цитадель благополучно поселилась на фундаменте, который они создали.\n\nИван: «Ты нужен мне здесь. Это приказ, который я должен был выучить раньше»"},
new string[] {"Путь Лады наружу","Лада отказалась провести свое спасение, ожидая тихо. Она отправила освобожденных рабочих в ремонтные команды и дала Дарьи формулу для внешних дождевых ворот.","Она возвращалась с эвакуированными в сторону Затонувшего квартала, укрепляя магические каналы защиты за экспедицией. Перед расставанием она сказала Миле, что мужество не измеряется тем, сколько боли она может пережить. Мила обещала сохранить этот урок. Прощание с ними было неясным, но оно также содержало практический план: сигналы, пункты встреч и лица, ответственные за каждый участок дороги.\n\nЛада: «Приведите себя домой, а не только ту часть, которая может быть полезной»"},
new string[] {"Ворота за цитаделью","Дорога Фёрнас началась у арки, сделанной из прохладной пепла. Когда якорь Цитадель отключился, арка раскололась и открыла путь через гору красного стекла.","Фонарь Милы потух, когда она открыла первую печать. Она сразу же сказала Ивану, выполняя их соглашение. Они разделили задачи фонаря между обычными лампами и компасом, чтобы сохранить его силу. Ярослав оставил маркер для команды Лады. Пятеро путешественников продолжили путь, который стал безопаснее для всех, кто решил починить его за спиной.\n\nМила: «Фонарь слабее. Я говорю вам прежде, чем оно потерпит неудачу»"},
new string[] {"Гора, что дышала жаром","Проходы горы расширились с дыханием печени. Горячий воздух выталкивался наружу через длительные промежутки времени; между ними тоннели притягивали все к центру.","Дарья измеряла ритм висящими нитками, а Борис закреплял в стенах опорные платформы. Иван двигал товарищей только во время внешнего дыхания. В первой безопасной камере Мила обнаружила капли чистой воды под красным стеклом. Внешние врата дождя были все еще живы где-то внутри горы, спрятанные под слоями украденного тепла.\n\nДарья: «Мы движемся по ритму, на который измеряем, а не к тому, на кого мы надеемся»"},
new string[] {"Зал незаконченных мечей","Заброшенный кузнец держал ряды мечей без ручек. Печь изготовил оружие, и никто не оставил его у себя.","Борис узнал, что лезвие - это коллекционеры света, которые извлекали энергию от каждого входившего. Он покрыл их края кулисами, а Мила закрыла хранимый свет через канализацию. Иван нашел простой незаконченный меч и оставил его на месте. Его собственного оружия, хранимого руками человека, было достаточно. На дальней стене прохладная схема подделки показала первый ключ от дождевых ворот.\n\nБорис: «Оружие, которое берет у своего обладателя - это другая цепь»"},
new string[] {"Сделка голосом Ивана","Варкул разговаривал через кузницу, используя собственный голос Ивана. Он предложил вернуть Сердце, если генерал сдаст фонарь Милы.","Он даже обещал ей безопасность, но отказался назвать людей, чьи волшебные каналы защиты останутся порабощенными. Иван просил дать полный ответ; имитирующий голос повторил только предложение. Мила подняла фонарь и открыла канал связи. Вместе они запечатали его. Самым опасным оружием демона было не пламя. Это была сделка, сделанная как решение, которое Иван уже выбрал.\n\nИван: «Если твоя милость не может назвать ее цену, это не милость»"},
new string[] {"Первые Врата Дождя","Ворота лежали под стеклянным полом, круговым механизмом, предназначенным для того, чтобы называть город бездействующими штормовыми блоками. Его каменные работы были сплавлены теплом.","Борис охладил его постепенно, пока Дарья выравнила маркировку с формулой Лады. Мила использовала только маленький фонарь, что позволило самой воде механизма нести остальное. Ворота открылись, но нижняя камера была пуста. Центральный якорь был снят и унес в гору глубже. Восстановление врат потребует поиска якоря, прежде чем дотронуться до сердца.\n\nМила: «Мы открыли дверь. Мы еще не раскрыли того, что позади него»"},
new string[] {"Генерал опускает знамя","Охранная камера потребовала знамя командира в качестве цены за вход. Иван понял, что печенье распознает символы власти более легко, чем люди под ними.","Он снял свою декоративную застёжку на плече и завернул броню в плащ работника. Дарья провёл товарищей через служебный проход, и охранная камера проигнорировала его. Мила видела, как он оставил эмблему без обиды. Он остался генералом из-за своих обязанностей, а не потому, что заколдованные ворота признали его звание. За ним ждала вторая подделка.\n\nИван: «Долг приходит со мной. Орден может остаться»"},
new string[] {"Комната без эха","Во втором кузнечике была камера, проглотившая каждый звук. Путешественники, которые не смогли позвонить по инструкциям, работали по сигналам, о которых они договорились ранее.","Ярослав держал группу вместе с кранами на его щите; Дарья отметила опасность в мелке. Мила взяла руку Ивана, когда тьма углубилась, и он последовал за ее фонарем, не пытаясь возглавить каждый шаг. На дальней двери Борис восстановил сломанный резонатор. Звук вернулся в один раз, и первое звуковое слово Милы было имя Ивана.\n\nМила: «Айван. Вот ты где»"},
new string[] {"Пропавший якорь","Дождевой якорь стоял в третьем кузнечике и превратился в пьедестал для украденного Серева дневного света. Лейтенант вернулся с маской зеркального стекла и попытался заманить товарищей в ловушку видения их желаемого будущего.","Иван видел дом на холме; Мила видела, как Лада в безопасности и улыбалась. Они поняли, как именно ловушка использовала то, что они любили. Дарья покрыла зеркала, а Ярослав прижал плащ Серева. Борис освободил якорь, а Мила осушила ложные видения. Серев сбежал без маски, не имея возможности нести правду, которую он раскрыл.\n\nМила: «Хотя мечтать о будущем, это видение не становится реальностью»"},
new string[] {"Тайна Пепельного Затвора","Последняя схема Лады пришла по восстановленной сигнальной линии. Она подтверждала страшный механизм: когда Сердце покинет двигатель короны, Пепельный Затвор направит накопленный жар обратно к городу.","Дождевой якорь мог отвести большую часть волны к внешним воротам. Вторую защёлку нужно было удерживать вручную внутри машинного зала, пока Сердце не пересечёт порог. Тот, кто её держал, мог спастись, если ворота сохранят устойчивость; никто не был обязан погибать. Иван особо подчеркнул это и предусмотрел освобождение с помощью верёвки, запасную подпорку и другой выход.\n\nИван: «Мы строим план так, чтобы вышли все. Никого не назначают жертвой»."},
new string[] {"Дом, который они хотели построить","Перед тем как вернуть якорь, товарищи поселились в прохладном алькове. Мила спросила Ивана, что он будет делать, когда ему больше не нужно держать меч.","Он ответил, что хочет научиться строить достаточно хорошо, чтобы заслужить одобрение Бориса. Она воображала, как преподаёт фонарики и сажает цветы за их окном. Они сжали две половинки своего деревянного блюда вместе. Сегодня их будущее носит конкретный характер и состоит из задач и ошибок, которыми они надеются поделиться. Его нежность дала им повод для того, чтобы следовать более безопасному плану, а не для того, чтобы отказаться от него.\n\nИван: «Научи меня фонарю. Я выучу окно»"},
new string[] {"Ворота познают дождь","Борис перезагрузил якорь, а Дарья синхронизировала механизм. Мила направляла нить воды по каждому восстановленному каналу.","Далеко отсюда, компас показал центральную камеру Древней Москвы, ответившую со слабым золотым пульсом. Врата работали, хотя красный перелом под их фундаментом оставался вне их инструментов. Они зафиксировали слабость и подготовили запасные опоры. Ярослав отправил результаты Ладе и Вере. Затем товарищи открыли внутреннюю горную дверь. За ним стоял печенье Холлоу, где сердце бьется над пустым троном Варкула.\n\nДарья: «Путь отвечает. Мы все еще смотрим на перелом»"},
new string[] {"Логово Полого Короля","Холлоу Фёрнас — это крепость, построенная внутри, ее башни висели над шахтой красного света. Служители Варкула создали каждый коридор, чтобы направить посетителей к престолу.","Вместо этого Дарья искала маршруты рабочих. Она нашла опоры для ног и полки инструментов, спрятанные за церемониальными стенами. Иван последовал за ней через узкие проходы, пока Мила слушала пульс сердца. Они вошли в логово, не заявив о себе. Под тронной галереей цепочка оккупированных клеток ждала в жару.\n\nДарья: «Кто - то должен был содержать это место. Их путь будет нашим»"},
new string[] {"Те, кто ещё за стенами","В камерах были ремесленники, чьи знания сохранили жизнь печени. Среди них был каменщик, который перерезал первоначальные ворота дождя.","Она предупредила, что его основание было преднамеренно ослаблено, чтобы разрушиться после удаления сердца. Борис попросил её отметить скрытый край перелома. Мила передала Ладе сигнал, который мог организовать ремонт с внешней стороны. Иван открыл камеры и дал заключенным инструменты, а не командование. Они решили немедленно уйти или помочь демонтировать машину, которая их держала.\n\nИван: «Ваша свобода не зависит от помощи нам»"},
new string[] {"Стойкость капитана","Патруль обнаружил открытые камеры. Ярослав держал узкую посадку, пока заключенные пересекали его.","Его щит треснул под горячими лезвиями охранников, и падающий камень ранил его ногу. Иван вернулся, чтобы помочь, несмотря на то, что компас тянул его к сердцу. Вместе они отошли за временный барьер Бориса. Ярослав отказался назвать ущерб благородной платой; это была проблема лечения. Мила охладила опухоль, Дарья адаптировала свой маршрут, и капитан продолжал с посохом вместо того, чтобы притворяться, что ничего не изменилось.\n\nЯрослав: «Не восхваляй рану. Помоги мне идти»"},
new string[] {"Дверь каменщика","Борис запечатал патрульный проход стеной, которая не могла быстро расплавиться. За ним он вырезал узкий съемный блок, оставив преднамеренный обратный путь.","Генерал спросил, не продержится ли. Борис ответил с пределом, а не заверением: достаточно долго для одного прохода, может быть, два, если никто не ударит по базе. Дарья написала состояние рядом с картой. Они отправили остальных заключенных через заграждение. Каждый честный предел сделал их план менее славным и более вероятным, чтобы сохранить кого-то живым.\n\nБорис: «Он держится в таких условиях. Запомните условия»"},
new string[] {"Похищенный компас","Малрек вышел из дыма и захватил компас. Золотая иголка подскакивала к престолу, отталкивая его от пути спасения.","Иван почти преследовал его в одиночку, но Мила остановила его на сломанной лестнице. Дарья узнала служебный мост внизу и направляла группу вокруг. Они нашли компас из заброшенной клетки Малрека. Посланник узнал, что компас не будет служить носителю, который стремится только к владению. Он сломал клетку и бежал к своему хозяину за другим оружием.\n\nМила: «Мы можем вернуть его вместе. Не превращайте срочность в одиночество»"},
new string[] {"Собственная битва девушки","Мила нашла фонарь Фирнаса, где сломанные кристаллы Рейнвардена покормили стену красного огня. Иван предложил охранять вход, пока она решила освободить их.","С помощью Дарьи Мила изменила направление кристаллов вместо того, чтобы вливать свою собственную силу в стену. Огонь смягчился до синего света. Она нашла старую линзу учителя и поставила ее на фонарь. Улучшение не сделало ее непобедимой, но дало ей больший контроль. Иван восхищался мастерством за чудом больше, чем самим зрелищем.\n\nМила: «Держи дверь. Эта часть моя, чтобы решить»"},
new string[] {"Зал заимствованных лиц","Варкул заполнил следующий зал копиями людей из прошлого Ивана. Каждый потребовал другого спасения, отвлекая внимание, пока он не сможет двигаться.","Мила отказалась определить истинный путь, угадывая, какой голос звучит очень искренне. Они с Дарьей отследили волшебные каналы защиты пола, а Борис проверил каждую дверь. Иван следил за работой, которую они могли проверить. Скопированные лица исчезли, когда скрытый двигатель был отключен. Остался один истинный сигнал: сообщение Веры о том, что Древняя Москва все еще удерживалась, и отремонтированные колодцы начали светиться.\n\nИван: «Город все еще там. Мы отвечаем на настоящее сообщение»"},
new string[] {"Последний фонарь Малрека","Посланник ждал у внутренних ворот с фонарём, вырезанным из цепи цитадель. Он нарисовал все искры в коридоре к доспехам Ивана.","Генерал отодвинул свой меч в сторону и использовал крюк рабочего, чтобы заполучить цепь. Ярослав ударил петлю фонаря; Мила охладила сердцевину. Малрек пытался сбежать через дым, но заземленная цепь запечатала его проход. Его черный камень превратился в безвредную пепел, когда Борис сломал пустой фонарь. Они оставили коридор нетронутым для возвращения, а вместо того, чтобы сжечь победу в его стенах.\n\nЯрослав: «Петля, Иван. Оставь яркий центр в покое»"},
new string[] {"Порог Сердца","За внутренними вратами сердце плывло внутри главного двигателя. Его золотые светлые окрашенные в красные цепи, и Иван узнал ритм из городской комнаты.","Пять путешественников еще раз проверили свой план: ответ на вопрос о дождевых воротах, закреплённый веревка, помечен альтернативный проход. Мила будет управлять водяной защелкой, потому что ее восстановленные линзы могут контролировать его; Борис будет крепить его, Дарья будет координировать ворота, а Ярослав защитит выход. Иван встретит Варкула. Мила попросила его посмотреть на неё перед тем, как посмотреть на трон, и он это сделал.\n\nМила: «Помни выход, даже когда видишь, за чем пришел»"},
new string[] {"Владыка, назвавшийся Рассветом","Варкул спустился с пустого трона, высотой гуманоидной фигуры разбитого обсидиана, завернутого в эмбер-красные одежды. Он утверждал, что украденный свет сделал его законным рассветом города.","Иван спросил, почему рассвету нужны заключенные, разрушенные колодцы и тьма, чтобы выжить. Демон ответил, подняв цепи конского двигателя. Мила держала водяную защелку открытой; Дарья позвонила в интервалы импульсов. Иван продвинулся с обычным стальным лезвием. Битва началась вокруг машины, которую можно было понять, прервать и демонтировать.\n\nИван: «Солнце, которому нужна наша тьма, не имеет права править нами»"},
new string[] {"Корона из чужих жизней","Корона Варкула черпала силу из имен, вырезанных на украденных волшебных защитных каналах. Каждый удар, нанесенный Иваном, возвращался сквозь пол.","Дарья узнала символы водохранилищ и сказала ему прекратить атаковать корону напрямую. Мила открыла синий канал для распечатанных таблеток, Борис перерезал ближайший канал. Корона потеряла один из своих огней. Иван изменил свой подход, борясь за то, чтобы разоблачить связи, а не одолеть демона. Варкул откаливался в первую очередь, что он не смог заменить: невольный источник становится свободным.\n\nДарья: «Завязывай связь. Не накорми корону еще раз»"},
new string[] {"План из четырёх частей","Битва распространилась по четырем галереям. Ярослав держал выход против сажиных охранников; Борис усилил защелку; Дарья дала сигнал Ладе у внешних ворот; Мила контролировала давление воды.","Иван не мог видеть ни одного из них через подъём, поэтому он доверял согласованным сигналам. Когда галерея сломалась, Дарья вызвала паузу вместо того, чтобы скрывать задержку. Иван вытащил Варкула достаточно долго, чтобы Борис мог стабилизировать его. План сработал, потому что всем было разрешено сообщать о неудачах, пока еще оставалось время для ответа.\n\nДарья: «Приостановите выпуск. Западная поддержка движется»"},
new string[] {"Предложение живого города","Варкул показал Ивану видение восстановления Древней Москвы, с Милой рядом с ним под ясным небом. Он предложил его в обмен на имена из водохранилища: чужие, чьи дома останутся тёмными навсегда.","Иван чувствовал жестокость выбора в точности, как и его желание. Он отказался говорить за тех, кого торгуют. Мила закрыла зрение потоком из своего фонаря. Предложение демона провалилось, потому что их любовь сделала место для будущего, но никогда не давала им права собственности на чужие.\n\nИван: «Я не могу купить наш дом с кем-то другим»"},
new string[] {"Клинок из обычного железа","Варкул разбил Ивану меч на страже. Борис бросил ему незаконченное лезвие, найденное из кузницы, теперь оснащенное простой деревянной рукояткой.","Там не было угнанного света. Иван использовал его, чтобы открыть тарелку для технического обслуживания двигателя, пока Ярослав закрыл свой подход. Дарья звонила в открытые замки по порядку. Демон сильно ударил, когда его сила превратилась в ряд уязвимых частей. Последнее оружие Ивана имело значение, потому что он мог надежно выполнить простую задачу, а не потому, что в пророчестве его носитель был назван.\n\nБорис: «Это звук железа. Заставь его работать»"},
new string[] {"Затвор не поддаётся","Первые три замка были открыты. Четвёртый остался сплавленным на поврежденный волшебный защитный канал под троном Варкула.","Мила предупреждала, что его принуждение приведёт к разрыву фундамента ворот дождя. Борис и Дарья предложили его охлаждение поэтапно, в то время как Лада укрепила внешнюю сторону. Иван держал Варкула подальше от защелки и считал сигналы. Они набрали время за счет истощения, но избежали слепого освобождения. Под троном невидимая красная вена начала нагреваться быстрее, чем предсказывали их диаграммы.\n\nМила: «Она не готова. Дай вратам время ответить»"},
new string[] {"Голос из Древней Москвы","Сигнал Веры достиг камеры через почти восстановленные волшебные каналы защиты. Она сообщила, что граждане очистили сердечную розетку и подключили убежища к ее каналам.","Город готовился получить то, что его товарищи надеялись вернуть. Иван слышал знакомые голоса под грохотом: гончар Аня, освобожденные рабочие и люди с дороги. Варкул пытался утопить их в громе от двигателя, но Мила усилила сигнал. Их работа превратилась в круг людей, которые помогают друг другу на расстоянии, и ни один герой не имеет всей своей силы.\n\nВера: «Камера готова. Город работает с вами»"},
new string[] {"Корона падает","Сигнал Лады подтвердил первое подкрепление ворот дождя. Дарья выпустила последний замок, и Борис разорвал тронный канал.","Корона Варкула разорвалась на скучные железные сегменты. Сердце выпрыгнуло из рамы, все еще удерживаясь внутри Пепельный Затвор. Иван встретил демона на нижней лестнице и оттолкнул его от оставшегося источника энергии. Впервые Варкул бросил обычную тень. Он был все еще опасен, но больше не огромен светом, взятым у других.\n\nИван: «В короне не осталось ничего, что принадлежало бы тебе»"},
new string[] {"Поражение Варкула","Варкул пытался воссоединиться с Сердцем через сломанный трон. Иван заставил его выйти на мост, пока Мила опечатала последний прямой канал.","Ярослав перерезал цепочку моста по сигналу Дарьи, сбросив пустой дальний участок и оторвав от демона. Иван ударил обнаженное эмбер-ядро в грудь Варкула простым железным лезвием. Украденное пламя вышло из строя. Варкул разбился на холодные фрагменты, а печь замолчала. Иван победил лидера демона, но Сердце еще не перешло порог.\n\nИван: «Сити-шоу идет домой»"},
new string[] {"Сердце в человеческих руках","Внутренний Эш-Лок открылся, когда Мила уравновешивала свой последний водный канал. Иван поднял Сердце из колыбели.","Его тепло было мягким, в отличие от жары печи, и его свет ясно показал каждое измученное лицо. Борис проверил брекет, Ярослав начал двигаться к отмеченному выходу. Дарья ждала подтверждения освобождения внешних ворот. Иван сказал Миле, что сердце свободно и тянется за рукой. За этим должно было последовать запланированное высвобождение с помощью веревки. Вместо этого красная вена под мертвым троном прорвалась через пол.\n\nИван: «У нас есть. Теперь мы выведем всех из могил»"},
new string[] {"Последний приказ Печи","Смерть Варкула спровоцировала скрытое коллапсовое устройство за картами Эша Локка. Внешние врата дождя потеряли вторую опору; чистая веревка сгорела до того, как Мила смогла отпустить защелку.","Она сразу же сообщила о провале. Борис пытался заменить верёвку, а Дарья искала другой контроль. Иван поставил Сердце на стабильную выступы и вернулся в Милу. Двигатель начал тянуть тепло к городу, и красная волна пересекла дальнюю галерею. Их враг исчез. Его машина все еще требовала ответа.\n\nМила: «Верёвка пропала. Защелка сдерживает волну»"},
new string[] {"Выбор у сломанной защёлки","Иван и Борис пытались запереть защелку запасным брекетом. Скрытая тепловая вена смягчила железо прежде, чем оно могло сесть.","Дарья нашла узкий проход к порогу, но нет второго контроля. Мила понимала время: если Сердце пересекло порог, пока защелка оставалась в силе, то прилив переместился бы на гору вместо города. Она просила остальных продолжать искать освобождения, пока Иван вытаскивал Сердце. Иван отказался оставить ее, не пробовав сперва оставшийся проход. Они все еще работали на пятерых выживших.\n\nМила: «Продолжай искать. Носите его только тогда, когда я дам сигнал»"},
new string[] {"Путь, что закрылся","Ярослав перешел узкий проход, чтобы обеспечить его дальний конец. Падающая плита запечатала возвратную сторону и раздавила поддержку под ногами Ивана.","Мила перенаправила водный канал, поймав плиту достаточно долго, чтобы Борис вытащил его. Усердие сломало ее фонарь. Дарья пыталась связаться с Ладой, но рушающиеся ворота ответили только сломанными импульсами. Теперь Иван мог достичь сердца и порога; он не смог дотянуться до защелки снаружи. Мила попросила его выслушать факты, прежде чем решить, какая надежда все еще допустима.\n\nМила: «Послушай, что изменилось. Тогда выбери со мной»"},
new string[] {"Последняя попытка спасения","Борис построил каменный клин из ступенек галереи; Дарья синхронизировала его с оставшимися пульсами внешних ворот. На мгновение защелка держалась без рук Милы.","Иван дошел до нее, и они сделали один шаг вместе. Затем скрытая вена разделила клин, отправив красный копье на грудь. Мила вытащила его за каменный щит защелки. Её поразила ответная реакция через свой фонарь, а не его выбор бросить ее. Ущерб больше не может быть обращен вспять. Она осталась в сознании и попросила его двигаться, пока щит все еще удерживается.\n\nИван: «Ещё один способ. Должен быть еще один способ»"},
new string[] {"Девушка удерживает дождь","Мила вставила разбитый фонарь в защёлку, создав последний устойчивый канал. Она знала, что он продержится дольше, чем хватит её сил, но лишь настолько, чтобы Иван успел перейти с Сердцем.","Она сказала ему, что дом, о котором они мечтали, был настоящим, потому что они его выбрали, даже если им не суждено делить его комнаты. Иван опустился рядом на колени и соединил половинки их памятной вещицы. Она попросила его сохранить широкое окно, научить кого-нибудь фонарному ремеслу и продолжать жить. Сквозь слёзы он пообещал это, а потом поднял Сердце.\n\nМила: «Неси свет. Продолжай жить там, где он сможет тебя коснуться»."},
new string[] {"За порогом","Иван пересек порог, когда Мила выпустила последний всплеск в гору. Ярослав и Борис вытащили его за охранную стену; Дарья запечатала проход до того, как появилась красная волна.","Сердце зажато. Через узкое отверстие Иван увидел Милу за павшей пылью, все еще рядом с голубым каналом, который она создала. Тепло прошло, и двигатель снова стал камнем. Спутники немедленно открыли самый маленький безопасный путь. Иван вернулся без Сердца, оставив его в руках своих друзей.\n\nИван: «Защищай сердце. Я вернусь за ней»"},
new string[] {"Тишина после её имени","Они нашли Милу в остывшей палате. Иван держал её на руках, пока последний голубой свет покидал разбитый фонарь.","Она услышала, как он произнёс её имя, и ответила его именем. Её последние слова были простыми: она была рада, что они встретились в дороге. Потом она умерла. Никакая тайная сделка не вернула её; никакой поцелуй не отменил утраты. Борис бережно завернул её в чистую ткань, и спутники вместе вынесли её наружу. Они спасли Сердце и победили Варкула. Эта цена не была доказательством любви, и они не называли её справедливой.\n\nМила: «Я рада, что в дороге встретила именно тебя»."},
new string[] {"Бремя на четверых","Айван не мог поднять сердце и завернутое тело Милы в одиночку. Ярослав забрал Сердце; Борис и Дарья сделали рамку для своего друга.","Когда Иван пытался отдать приказы, его голос провалился. Дарья ясно сказала ему следующие шаги: отдохни, вода, а потом внешние ворота. Другие приняли это дело, не попросив его стать символом стойкости. За ними погасло красное сияние Фёрнаса. Напереди дорога, которую они отремонтировали, осталась, готовая нести как спасенный свет, так и человека, которого они потеряли.\n\nДарья: «Тебе не обязательно нести все это»"},
new string[] {"Лада у Врат Дождя","Лада встретила товарищей рядом с поврежденными внешними воротами. Она отремонтировала оставшиеся в живых каналы с освобожденными ремесленниками, но не смогла вовремя восстановить разрушенную поддержку.","Когда она увидела сломанный фонарь, она поняла, прежде чем Иван мог говорить. Она не обвиняла ученика, который спас их, и не извинялась за машину, которая вынудила сделать выбор. Вместе они зафиксировали то, что потерпело неудачу, так что ни одна будущая палата не будет зависеть от одного человека с смертельной защелкой. Потом Лада положила серебряный круг Милы возле завернутого фонаря.\n\nЛада: «Мы будем помнить ее, и мы изменим то, что подвело ее»"},
new string[] {"Возвращение через ожившие места","Работники Цитадели открыли свои ворота путешественникам. В затонувшем квартале Аня предложила чистые одеяла; в Стеклянном лесу восстановленные деревья защищали рамку.","Иван узнал каждое место, где они остановились, чтобы помочь им, а теперь помог им взамен. Он сказал тем, кто спросил, что Мила была мастером, гидом, учеником учителя и кто-то, кто смеялся над его танцами. Он отказался позволить ей стать только в тот момент, когда она умерла. Ее история принадлежала той жизни, которую она жила по дороге.\n\nИван: «Помни, что она сделала возможным, пока была здесь»"},
new string[] {"Холмы перед городом","На холмах над Древней Москвой Иван выбрал приют около весны, чтобы упокоить Милу. Лада и трое друзей стояли с ним.","Он не посадил семя волшебное и не ожидал возвращения из земли. Он оставил половину деревянного окна на память рядом с ней, держа другую под его плащом. Под ними город по-прежнему горел вдоль своих внешних путей. Сигнал Веры звонил с ворот. Иван встал, когда мог, и товарищи продолжили с сердцем к камере, ожидающей под квадратом.\n\nИван: «Я буду помнить тебя в своей жизни»"},
new string[] {"Ворота открываются вновь","Выжившие западные ворота Москвы открылись до того, как генерал добрался до них. Вера сохранила приюты в целости, а отремонтированные колодцы поставляли последние пожарные пробки.","Граждане выстраивали дорогу без лишних наслаждений. Они видели утомление четырех друзей, сломанный фонарь, и золотое Сердце таскалось между ними осторожно. Иван дал городским часам полный отчет: демон был побежден, сердце выздоровело, и Мила была мертва. Вера слушала, а потом отдавала свежие руки работе в камере. Возвращение не означает, что эта задача была завершена.\n\nВера: «Мы держим дорогу. Давайте перейдем к следующей части»"},
new string[] {"Город впускает свет","Площадь по-прежнему переполнена приютами и древесиной. Прежде чем восстановить Сердце, Иван помог Вере убрать семьи из нестабильного потолка камеры.","Борис проверил ремонт, Дарья сопоставила новые каналы с ее картой возвращения. Лада поместила выживающую линзу Милы в нишу сигнала, где она могла распространять свет без опасного тепла. Орел, слабый, но живой, узнал отремонтированные маршруты, ведущие за пределы города. Сердце вернется к более широкой сети, чем та, из которой оно было украдено.\n\nОрел: «Вы принесли дороги, а также свет»"},
new string[] {"Сердце находит своё место","Иван спустился с сердцем в руках. Под квадратом была восстановлена розетка с браслетами Аня, деревенскими деревянными деревянными брекетами и камнями в форме освобожденных рабочих.","Ничего не было нетронуто, все было готово. Сломанный фонарь Милы лежал рядом, как память, а не механизм, требующий другой жизни. Иван поместил Сердце в свой первоначальный центр. В течение одного долгого вздоха камера оставалась темной. Затем золотой свет заполнил отремонтированное кольцо и передвигался наружу по каждому каналу, который они сделали цельным.\n\nИван: «Для людей здесь и для тех, кто на дороге»"},
new string[] {"Молнии над башнями","Возвращенный пульс сердца достиг дождевых ворот через связанные волшебные каналы защиты. Белый удар молнии пересек чёрное небо над Древней Москвой, освещая каждую сожженную крышу и восстанавливая арку.","Граждане рухнули, а потом услышали глубокий ответ грома. Иван залез на площадь, когда первые холодные капли попали в камни. Дарья проверила дренаж, Вера перевела людей в стабильное укрытие. Давно ожидаемое чудо пришло с работой, и город был готов принять его, не рассматривая чудо как замену ухода.\n\nДарья: «Открой канализацию. Шторм настоящий»"},
new string[] {"Дождь, что погасил огонь","Дождь падал в потоках. Пламя хлещет по крышам древесины, а затем сворачивается в пар.","Красный свет в колодцах исчез, оставляя воду достаточно чистой, чтобы отразить фонари. Иван стоял под ливнем, пока Ярослав не положил плащ на плечи. Вокруг них жители обнимали, перевозили воду в скрытые эмберы и называли имена людей, которые все еще пропали без вести. Город был спасен от огня. Это не пощадило всех потерь. Обе истины находились под одним и тем же возвращающимся небом.\n\nЯрослав: «Подойди под плащ. Тебе позволено быть холодным»"},
new string[] {"Первое утро","К утру дождь разлился на серебряные нити. Солнечный свет достиг центральной площади через рваные облака, прикоснувшись к мокрому камню, застрявшие стены и изнурённые лица.","Орел объявил, что ритм Сердца стабилен. Иван смотрел, как просыпается город, не ожидая радости, чтобы заменить свое горе. Отсутствие Милы оставалось рядом с красотой, которую она помогла восстановить. Он вытащил свою половину деревянных оконных рамы и держал ее в свете. Затем он присоединился к Борису в поврежденном доме, где по - прежнему нужно было создать настоящее окно.\n\nИван: «Пришло утро. Давайте оставим для этого место»"},
new string[] {"Оленьи ромашки на холмах","Через несколько дней на холмах над Древней Москвой распустились белые оленьи ромашки. Это были цветы, которые жители деревни всегда называли так: белые лепестки, золотые сердцевины и тонкие серебристо-зелёные листья.","На их стеблях ещё блестели капли дождя. Иван пришёл к месту упокоения Милы с Ладой и тремя друзьями. Он принёс небольшой букет и рассказал о починенном окне, о детях, которые учились фонарному ремеслу, и о дожде, который наконец пришёл. Он говорил ей о жизни, потому что это обещание всё ещё мог сдержать.\n\nИван: «Они расцвели. Как бы я хотел, чтобы ты их увидела»."},
new string[] {"Школа открытых фонарей","Лада открыла мастерскую для фонарей в отремонтированном доме недалеко от площади. Его первое правило было написано на скамейке судей: ни одна палата не должна нуждаться в руке пленника.","Дарья помогала документировать сигналы о безопасном высвобождении и неисправности. Борис учил студентов строить звуковые жилые помещения, прежде чем доверять ярким кристаллам. Иван присутствовал на первом уроке как новичок, борясь с нежной застёжкой. Когда студенты смеялись, он смеялся вместе с ними. Ремесла Милы продолжились с помощью преподавания, а не утверждения о том, что она вернулась. Ее имя было рядом с работой, а не сверх требования жертвовать.\n\nЛада: «Построй релиз прежде, чем построишь свет»"},
new string[] {"Генерал и недостроенный город","Иван сдержал командование, но изменил свою работу. Часы отремонтировали дороги, тренировали спасательные команды и защищали поселения, связанные с сердцем.","Нога Ярослава медленно заживала; он учил молодых капитанов сообщать о травмах без стыда. Борис наблюдал за новыми фондами, и Дарья опубликовала карту, которая включала деревни, которые когда-то опущены. Иван построил окно на холме, которое обещал, оставив комнату доступной для путешественников. Он не назвал это домом, в котором они с Милой могли бы жить вместе. Это было живое место, которое стало возможным благодаря её воспоминанию.\n\nИван: «Город достаточно безопасен, чтобы восстановиться. Это наш следующий долг»"},
new string[] {"Легенда о возвращении дождя","Годы спустя люди рассказывали, как генерал родом из деревни и трое его друзей пошли за украденным Сердцем во тьму. Они рассказывали о Миле, которая открыла путь, любила по собственной воле и спасла Ивана, когда Печь разрушила их путь к отступлению.","Иван всегда добавлял имена учителей, рабочих, беженцев и соседей, благодаря которым это путешествие стало возможным. Когда первая весенняя гроза дошла до холмов, он открыл широкое окно. За дождём пришёл солнечный свет, и над Древней Москвой засияли оленьи ромашки. Легенда заканчивалась городом, который продолжал жить, и любовью, о которой помнили, не отменяя утраты.\n\nИван: «Расскажите и о её жизни. Расскажите обо всех руках, которые вернули свет домой»."},
},
}; } }
